    // Q73 unified true-glass spec (all floating pieces share this): frozen/live snapshot blur
    // (applyGlass blur13 + saturate1.65, aligned to the tile +/check frost the user approved in Q47)
    // + ONLY a thin tint over it + a fixed light wash + a soft 1dp edge. Tint must stay thin and
    // see-through (never a thick milky block, never Q34 solid white plastic); dark mode swaps to a
    // dark thin tint. Pieces: float toast/undo bar, more-menu, detail close, card +/check (Q47),
    // search/filter fabs, top fab, dock, search capsules. Sampling stays Q29/Q41 static-band:
    // refresh on settle/tab-switch only, zero capture while scrolling, no Bitmap.recycle (Q21).
    // Q97：透明程度三档的染色浓淡倍率——只缩放填充 alpha，描边高光不参与（那是边缘顺滑，不是染色）。
    // Q105 改档距（2.19，用户 21:36 点名「选了没什么改变」）：旧三档 0.70/0.88/1.0 步距
    // 太小、且只有染色一轴在动，1 与 2 档肉眼几乎无差。改四轴联动拉开：染色本系数
    // 0.45/0.72/1.00、wash 独立系数 glassWashScale 0.30/0.62/1.00、模糊半径
    // BACKDROP_BLUR_R 2/4/6、饱和 BACKDROP_SAT 1.20/1.55/1.90。0=薄透：染色与 wash
    // 只剩小半、糊最轻，背后内容最清楚但仍隔一层带色雾面（不是清玻璃、更不是白
    // 塑料）；2=毛玻璃（默认）：染色满格、糊度较旧默认（半径 5）微升一档，守住 Q97
    // 以来用户认过的浓档观感。糊层 bitmap 自身的 alpha 不分档——frozen/过期帧与
    // 真实页面叠加会透出重影，清晰度差改由模糊＋饱和承担。窗级玻璃 glassWindowTint
    // 不跟档：Q103 按用户点名定的近实档（菜单透出背后开关显脏），不许薄透请回来。
    float glassTintScale() { return glassLevel <= 0 ? 0.45f : glassLevel == 1 ? 0.72f : 1.0f; }
    float glassWashScale() { return glassLevel <= 0 ? 0.30f : glassLevel == 1 ? 0.62f : 1.0f; }
    static int scaleColorAlpha(int color, float scale) {
        int a = Math.round(Color.alpha(color) * scale);
        if (a < 0) a = 0; if (a > 255) a = 255;
        return Color.argb(a, Color.red(color), Color.green(color), Color.blue(color));
    }
    GradientDrawable glassTintDrawable(float radiusDp, boolean oval) {
        GradientDrawable g;
        float ts = glassTintScale();
        if (darkEff()) {
            g = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,
                new int[]{scaleColorAlpha(Color.argb(96, 52, 52, 58), ts), scaleColorAlpha(Color.argb(84, 40, 40, 46), ts), scaleColorAlpha(Color.argb(76, 34, 34, 40), ts)});
        } else {
            g = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,
                new int[]{scaleColorAlpha(Color.argb(120, 255, 255, 255), ts), scaleColorAlpha(Color.argb(110, 248, 250, 253), ts), scaleColorAlpha(Color.argb(100, 240, 245, 251), ts)}); // Q94 铺开：染色加白去花
        }
        if (oval) g.setShape(GradientDrawable.OVAL); else g.setCornerRadius(dp(this, radiusDp));
        g.setStroke(dp(this, 1), darkEff() ? Color.argb(44, 255, 255, 255) : Color.argb(84, 255, 255, 255)); // Q94 铺开：描边收软
        return g;
    }
    GradientDrawable glassWashDrawable(float radiusDp, boolean oval) {
        GradientDrawable g;
        float ts = glassWashScale(); // Q105：wash 独立档距（旧实现与染色同系数，1/2 档差被染色盖住）
        if (darkEff()) {
            g = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,
                new int[]{scaleColorAlpha(Color.argb(34, 255, 255, 255), ts), scaleColorAlpha(Color.argb(22, 255, 255, 255), ts)});
        } else {
            g = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,
                new int[]{scaleColorAlpha(Color.argb(58, 255, 255, 255), ts), scaleColorAlpha(Color.argb(44, 248, 250, 253), ts)}); // Q94 铺开：提亮压平，不再顶出一条白带
        }
        if (oval) g.setShape(GradientDrawable.OVAL); else g.setCornerRadius(dp(this, radiusDp));
        g.setStroke(dp(this, 1), darkEff() ? Color.argb(36, 255, 255, 255) : Color.argb(72, 255, 255, 255)); // Q94 铺开：描边收软
        return g;
    }
    View glassWashView(float radiusDp, boolean oval) {
        View wash = new View(this);
        wash.setClickable(false); wash.setFocusable(false);
        wash.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
        wash.setBackground(glassWashDrawable(radiusDp, oval));
        return wash;
    }
    void glassClip(View v, final float radiusDp, final boolean oval) {
        try {
            v.setClipToOutline(true);
            v.setOutlineProvider(new android.view.ViewOutlineProvider() {
                @Override public void getOutline(View vv, android.graphics.Outline o) {
                    if (oval) o.setOval(0, 0, Math.max(1, vv.getWidth()), Math.max(1, vv.getHeight()));
                    else o.setRoundRect(0, 0, Math.max(1, vv.getWidth()), Math.max(1, vv.getHeight()), dp(vv.getContext(), radiusDp));
                }
            });
        } catch (Throwable ignored) {}
    }
    // 切深色先套色再显页：根底色与状态/导航栏图标明暗在建页前就定，不许闪白
    void applyAppearanceChrome() {
        try {
            if (rootView != null) rootView.setBackground(softPageBg()); // Q94 铺开：同根页底
            // 19:37 验收项「切深色」：dock 与药丸底色在 buildNav 只套过一次，深浅切换时
            // 一并按当前档重套，并按当前页签实测重钉药丸几何（四种验收姿势之一）。
            if (navBar != null) navBar.setBackground(dockBarBg());
            if (navIndicator != null) {
                navIndicator.setBackground(navPillBg());
                layoutNavIndicator(Math.max(0, navOrder == null ? 0 : navOrder.indexOf(tab)), false);
            }
            Window w = getWindow();
            int flags = w.getDecorView().getSystemUiVisibility();
            if (darkEff()) flags &= ~(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR | View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
            else flags |= View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR | View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR;
            w.getDecorView().setSystemUiVisibility(flags);
        } catch (Throwable ignored) {}
    }
    void loadPlaceholderPrefs() {
        try {
            placeholderStyle = prefs == null ? "light" : prefs.getString("placeholder_style", "light");
            if (!"dark".equals(placeholderStyle)) placeholderStyle = "light";
            placeholderCustomEnabled = prefs != null && prefs.getBoolean("placeholder_custom_enabled", false);
            placeholderCustom = new java.util.HashMap<>();
            String raw = prefs == null ? null : prefs.getString("placeholder_custom_json", "{}");
            org.json.JSONObject o = new org.json.JSONObject(raw == null || raw.isEmpty() ? "{}" : raw);
            java.util.Iterator<String> ks = o.keys();
            while (ks.hasNext()) { String k = ks.next(); int v = o.optInt(k, -1); if (v >= 0 && v < PLACEHOLDER_PALETTE.length) placeholderCustom.put(k, v); }
        } catch (Throwable ignored) { placeholderCustom = new java.util.HashMap<>(); }
    }
    void savePlaceholderCustom() {
        try {
            org.json.JSONObject o = new org.json.JSONObject();
            for (java.util.Map.Entry<String, Integer> e : placeholderCustom.entrySet()) o.put(e.getKey(), e.getValue());
            if (prefs != null) prefs.edit().putString("placeholder_custom_json", o.toString()).apply();
        } catch (Throwable ignored) {}
    }
    int placeholderIdxFor(String id) {
        if (placeholderCustomEnabled && id != null && placeholderCustom.containsKey(id)) return placeholderCustom.get(id);
        return placeholderIdx(id);
    }
    GradientDrawable placeholderGradFor(String id, float radiusDp, Context c) {
        int idx = placeholderIdxFor(id);
        int[] pair;
        if (placeholderCustomEnabled && id != null && placeholderCustom.containsKey(id)) pair = PLACEHOLDER_PALETTE[idx];
        else pair = ("dark".equals(placeholderStyle) ? PLACEHOLDER_PALETTE : PLACEHOLDER_PALETTE_LIGHT)[idx];
        GradientDrawable g = new GradientDrawable(GradientDrawable.Orientation.TL_BR,
            new int[]{ Color.rgb(Color.red(pair[0]), Color.green(pair[0]), Color.blue(pair[0])),
                       Color.rgb(Color.red(pair[1]), Color.green(pair[1]), Color.blue(pair[1])) });
        g.setCornerRadius(dp(c, radiusDp));
        return g;
    }
    static boolean hasOrgBadge(String org) {
        if (org == null) return false;
        String o = org.trim();
        return o.equals("unionpay") || o.equals("mastercard") || o.equals("mastercard-nucc")
            || o.equals("visa") || o.equals("jcb") || o.equals("amex-cn");
    }
    static int orgBadgeWidthDp(String org) {
        // Q93：统一按示意图板 240×120（2:1）画幅取宽，高 24dp → 宽恒 48dp；各组织在同一画幅内按画板几何留白
        return 48;
    }
    // Q93：占位面深底判定——与 placeholderGradFor 完全同口径取色板对，两端平均亮度低即深底，
    // 组织小标的银联小字/Visa 字色据此切深底白字版（示意图板深色底一档口径）
    boolean placeholderDarkFor(String id) {
        int idx = placeholderIdxFor(id);
        int[] pair;
        if (placeholderCustomEnabled && id != null && placeholderCustom.containsKey(id)) pair = PLACEHOLDER_PALETTE[idx];
        else pair = ("dark".equals(placeholderStyle) ? PLACEHOLDER_PALETTE : PLACEHOLDER_PALETTE_LIGHT)[idx];
        return pairLuminance(pair[0], pair[1]) < 0.52f;
    }
    static boolean customStyleDark(int style) {
        int[] pair = CUSTOM_STYLES[Math.max(0, Math.min(style, CUSTOM_STYLES.length - 1))];
        return pairLuminance(pair[0], pair[1]) < 0.52f;
    }
    static float pairLuminance(int c0, int c1) {
        return (hexLuminance(c0) + hexLuminance(c1)) / 2f;
    }
    static float hexLuminance(int hex) {
        float r = ((hex >> 16) & 0xFF) / 255f, g = ((hex >> 8) & 0xFF) / 255f, b = (hex & 0xFF) / 255f;
        return 0.299f * r + 0.587f * g + 0.114f * b;
    }
    // Q27：圆角裁切不能只靠默认 BACKGROUND outline（GradientDrawable/RippleDrawable 的 outline 在部分机型上
    // 退化为直角矩形，ImageView 的方形位图四角便盖过圆角背景、elevation 阴影也按直角轮廓打出黑角）。
    // 显式给视图装 RoundRect outline 并 clipToOutline，位图/背景/阴影三者共用同一圆角半径。
    static void roundClip(final View v, final float radiusDp, final Context c) {
        try {
            final float r = dp(c, radiusDp);
            v.setOutlineProvider(new ViewOutlineProvider() {
                @Override public void getOutline(View view, Outline outline) {
                    outline.setRoundRect(0, 0, view.getWidth(), view.getHeight(), r);
                }
            });
            v.setClipToOutline(true);
        } catch (Throwable ignored) { /* 个别机型 outline 异常时保留原背景圆角，不为裁切冒崩点 */ }
    }
    // Q45：贴底窗专用裁切——窗体背景虽已仅顶部圆角，但默认 outline 取自 GradientDrawable 时
    // 只认统一半径、会把底部两角也裁圆，角下露出玻璃/遮罩即用户截图里的黑三角。API 29+ 用
    // 「顶圆底直」的 Path 轮廓让裁切与阴影都只圆顶部；低版本回落统一圆角（旧行为，不冒新崩点）。
    static void topSheetClip(final View v, final float radiusDp, final Context c) {
        try {
            final float r = dp(c, radiusDp);
            v.setOutlineProvider(new ViewOutlineProvider() {
                @Override public void getOutline(View view, Outline outline) {
                    int w = Math.max(1, view.getWidth()), h = Math.max(1, view.getHeight());
                    if (Build.VERSION.SDK_INT >= 29) {
                        Path p = new Path();
                        p.moveTo(0, h);
                        p.lineTo(0, r);
                        p.quadTo(0, 0, r, 0);
                        p.lineTo(w - r, 0);
                        p.quadTo(w, 0, w, r);
                        p.lineTo(w, h);
                        p.close();
                        outline.setPath(p);
                    } else {
                        outline.setRoundRect(0, 0, w, h, r);
                    }
                }
            });
            v.setClipToOutline(true);
        } catch (Throwable ignored) { /* 个别机型 outline 异常时保留原裁切，不为修角冒崩点 */ }
    }
    // Q27（用户 19:24 钉法）：位图级四角圆角——按显示尺寸把半径换算到位图坐标里，用 SRC_IN 把源图
    // 四角真切成透明，不靠视图 outline 硬剪；源图在 Img 缓存里多处共用，只出圆角副本、绝不动源图。
    static Bitmap roundBitmap(Bitmap src, float radiusPx) {
        if (src == null || src.getWidth() <= 0 || src.getHeight() <= 0) return src;
        try {
            Bitmap out = Bitmap.createBitmap(src.getWidth(), src.getHeight(), Bitmap.Config.ARGB_8888);
            Canvas cv = new Canvas(out);
            Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
            RectF rf = new RectF(0, 0, src.getWidth(), src.getHeight());
            cv.drawRoundRect(rf, radiusPx, radiusPx, p);
            p.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.SRC_IN));
            cv.drawBitmap(src, 0, 0, p);
            p.setXfermode(null);
            return out;
        } catch (Throwable t) { return src; } // 圆角副本失败回落源图，不为修角冒崩点
    }
    // Q33：卡面圆角照实体银行卡模具——半径按显示图宽约 4% 取（Q33 钉的 3.5–4% 量级取上沿，
    // 对照混合版 styles.css .p-slide img 的 12px 固定值在全宽图上约合 3.5%，原生旧值 12dp 恰卡下沿显尖）；
    // 随图宽缩放、夹在 8–24dp，详情大图/瓷砖/无图占位共用同一口径，肉眼明确圆润。
    static float cardRadiusDp(float widthDp) {
        float r = widthDp * 0.04f;
        if (r < 8f) r = 8f;
        if (r > 24f) r = 24f;
        return r;
    }

    // ---------- Q18 崩溃留痕 + 玻璃自动降级 ----------
    void noteGlassFailure() {
        glassFailCount++;
        if (glassFailCount >= 3 && !glassDisabled) {
            glassDisabled = true;
            refreshDockBg(); // Q117：自动关停同为关态，dock 兜底同步换上
            try { if (prefs != null) prefs.edit().putBoolean("glass_disabled", true).apply(); } catch (Throwable ignored) {}
            // clear all live glass images/effects so tint fallback shows, never drag the page down
            try {
                for (ImageView iv : new java.util.ArrayList<>(glassViews)) {
                    try { iv.setImageBitmap(null); if (Build.VERSION.SDK_INT >= 31) iv.setRenderEffect(null); } catch (Throwable ignored) {}
                }
                // Q21 黑匣子定案：绝不主动 recycle——仍被某个 ImageView 显示列表引用的图一旦 recycle，下一帧 onDraw 即
                // 「Canvas: trying to use a recycled bitmap」整 App 闪退（0.67/0.70 两案同签名）。只解引用交系统回收。
                glassSnap = null;
            } catch (Throwable ignored) {}
        }
    }
    void noteGlassSuccess() { if (glassFailCount > 0) glassFailCount = 0; }

    void installCrashHandler() {
        try { sCrashVersion = appVersion(); } catch (Throwable ignored) { sCrashVersion = ""; }
        final Thread.UncaughtExceptionHandler prev = Thread.getDefaultUncaughtExceptionHandler();
        Thread.setDefaultUncaughtExceptionHandler((t, e) -> {
            try {
                java.io.StringWriter sw = new java.io.StringWriter();
                java.io.PrintWriter pw = new java.io.PrintWriter(sw);
                e.printStackTrace(pw); pw.flush();
                StringBuilder sb = new StringBuilder();
                sb.append("time=").append(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.US).format(new java.util.Date())).append("\n");
                sb.append("version=").append(sCrashVersion).append("\n");
                sb.append("page=").append(sCrashTab).append("\n");
                sb.append("thread=").append(t == null ? "" : t.getName()).append("\n");
                sb.append(sw.toString());
                String txt = sb.toString();
                // file first (survives even if prefs write races process death)
                try {
                    File f = new File(getFilesDir(), "crash_last.txt");
                    FileOutputStream fos = new FileOutputStream(f, false);
                    fos.write(txt.getBytes("UTF-8")); fos.close();
                } catch (Throwable ignored) {}
                try {
                    if (prefs != null) prefs.edit().putString("crash_log", txt).commit();
                } catch (Throwable ignored) {}
            } catch (Throwable ignored) {}
            if (prev != null) prev.uncaughtException(t, e);
            else { android.os.Process.killProcess(android.os.Process.myPid()); System.exit(10); }
        });
    }
    void loadCrashLog() {
        crashLogText = null;
        try { if (prefs != null) crashLogText = prefs.getString("crash_log", null); } catch (Throwable ignored) {}
        if (crashLogText == null || crashLogText.trim().isEmpty()) {
            try {
                File f = new File(getFilesDir(), "crash_last.txt");
                if (f.exists()) {
                    FileInputStream in = new FileInputStream(f);
                    ByteArrayOutputStream bos = new ByteArrayOutputStream();
                    byte[] buf = new byte[8192]; int n;
                    while ((n = in.read(buf)) > 0) bos.write(buf, 0, n);
                    in.close();
                    crashLogText = new String(bos.toByteArray(), "UTF-8");
                    if (crashLogText != null && prefs != null) {
                        try { prefs.edit().putString("crash_log", crashLogText).apply(); } catch (Throwable ignored) {}
                    }
                }
            } catch (Throwable ignored) { crashLogText = null; }
        }
        if (crashLogText != null && crashLogText.trim().isEmpty()) crashLogText = null;
    }
    void clearCrashLog() {
        crashLogText = null;
        try { if (prefs != null) prefs.edit().remove("crash_log").apply(); } catch (Throwable ignored) {}
        try { File f = new File(getFilesDir(), "crash_last.txt"); if (f.exists()) f.delete(); } catch (Throwable ignored) {}
    }

    // ---------- Q11 真毛玻璃地基 ----------
    void pruneGlass() {
        java.util.Iterator<ImageView> it = glassViews.iterator();
        while (it.hasNext()) {
            ImageView iv = it.next();
            if (!iv.isAttachedToWindow()) {
                glassCrops.remove(iv); // Q21：只解引用不 recycle（同 noteGlassFailure 定案，防 recycled bitmap 闪退）
                glassHosts.remove(iv);
                it.remove();
            }
        }
    }

    /** 建一层玻璃模糊层：host 是它要贴合的玻璃面（定位/抓图时整面让开），radiusDp<0 为椭圆。 */
    ImageView glassLayer(View host, float radiusDp, boolean live) {
        if (glassDisabled) {
            // Q18: glass chain auto-disabled after consecutive failures -> return invisible placeholder,
            // tint underneath takes over; never crash the host page for glass.
            ImageView ph = new ImageView(this);
            ph.setClickable(false); ph.setFocusable(false);
            ph.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
            ph.setTag(live ? "live" : "frozen");
            ph.setVisibility(View.INVISIBLE);
            return ph;
        }
        // Q97 玻璃换代（软件背板）：不再分 API——背板是软件 Canvas 抓根视图→降采样
        // →盒式模糊的普通 Bitmap，全版本同一实现（Q90 的 RenderNode/RenderEffect 链
        // 因 vivo X200 Pro mini/Android 15 HWUI 原生层崩溃定案后整段拆除，见 Q96/Q97）。
        final GlassBackdropView iv = new GlassBackdropView(this);
        setupGlassLayerVisual(iv, radiusDp);
        iv.setTag(live ? "live" : "frozen");
        glassViews.add(iv);
        if (host != null) glassHosts.put(iv, host);
        ensureBackdropHook();
        return iv;
    }

    /** Q108 试点件构造（2.22，底栏＋⋯菜单）；Q109（2.23）曾全面铺开，Q112（2.25）
     * 收敛：只有窗件与底栏走此构造进硬件名册，live 常驻件（搜索胶囊/悬浮钮）与
     * 详情主钮已改回 glassLayer 永远软件（同帧单 live 消费者不变量）。与 glassLayer
     * 同路同视觉，仅多打一个硬件标；硬件关/退/低版本时 onDraw 自动回落软件路。
     * Q111（2.24）：每件带稳定 key（金丝雀逐件记账的身份，见 HW_PIECE_ORDER 与
     * GlassBackdropView.hwDrawGate）——key 只作记账标识，不影响任何视觉参数。 */
    ImageView glassLayerHw(View host, float radiusDp, boolean live, String key) {
        ImageView iv = glassLayer(host, radiusDp, live);
        if (iv instanceof GlassBackdropView) {
            ((GlassBackdropView) iv).hwPilot = true;
            ((GlassBackdropView) iv).hwKey = key;
        }
        return iv;
    }

    /** Q90 抽出：玻璃层的圆角裁切 + 边缘高光（旧快照层与新背板层同一套视觉口径）。 */
    void setupGlassLayerVisual(ImageView iv, float radiusDp) {
        iv.setScaleType(ImageView.ScaleType.FIT_XY);
        iv.setClickable(false);
        iv.setFocusable(false);
        iv.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
        if (Build.VERSION.SDK_INT >= 21) {
            iv.setClipToOutline(true);
            final float r = radiusDp < 0 ? -1f : dp(this, radiusDp);
            iv.setOutlineProvider(new android.view.ViewOutlineProvider() {
                @Override public void getOutline(View v, android.graphics.Outline o) {
                    if (r < 0) o.setOval(0, 0, Math.max(1, v.getWidth()), Math.max(1, v.getHeight()));
                    else o.setRoundRect(0, 0, Math.max(1, v.getWidth()), Math.max(1, v.getHeight()), r);
                }
            });
        }
        if (Build.VERSION.SDK_INT >= 23) {
            // Q16 (3): edge highlight band (hand-drawn Fresnel approximation) - 1dp white bright line, center stays unfogged, no AGSL refraction
            GradientDrawable fg = new GradientDrawable();
            fg.setColor(Color.TRANSPARENT);
            if (radiusDp < 0) fg.setShape(GradientDrawable.OVAL); else fg.setCornerRadius(dp(this, radiusDp));
            fg.setStroke(dp(this, 1), Color.argb(48, 255, 255, 255)); // Q94 铺开：高光描边收软（旧 95 在 dock 顶沿勒出一条发白硬带，19:22 点名）
            try { iv.setForeground(fg); } catch (Throwable t) { /* some OEMs unsupported -> no highlight */ }
        }
    }

    // ---------- Q97 实时背板玻璃（软件 Bitmap 背板，全版本同一实现） ----------
    // 定案背景：Q90 的 RenderNode 录制＋RenderEffect 链在用户机（vivo X200 Pro mini /
    // Android 15）HWUI 原生层崩溃（2.08 硬关玻璃后真机可正常进 App，Q96 定位版定案），
    // 故整段拆除。新链不碰任何 HWUI 录制：根视图每帧 preDraw 由钩子以 BACKDROP_SCALE
    // 降采样用软件 Canvas 画进一张复用 Bitmap（抓图时全部玻璃宿主整面让开，与旧抓图
    // 同语义），再做三遍盒式模糊近似高斯（手写滑动窗均值）；饱和在绘制期以
    // ColorMatrixColorFilter 施加。每件玻璃层 onDraw 只把这张共享背板按自身与根视图
    // 的屏幕位差对位绘出（与 Q90 同一组对位数学），故糊层跟随身后内容滚动。
    // 抓图节流 50ms（preDraw 只在有重绘时触发，静止零开销）；模糊半径已按
    // 「等效全分辨率 σ≈34px（浓档）」在 0.20 降采样下折算，强度三档由设置页「透明程度」
    // 成套映射（半径/饱和/染色 alpha，见 BACKDROP_BLUR_R / BACKDROP_SAT / glassTintScale）。
    // 自检降级：抓图/模糊/绘制任一环抛 Throwable → disableGlassNow 一次性持久关停
    // （Java 层记账、写 pref），玻璃件整面隐藏回静态染色兜底，绝不重试、不带走进程。
    // 位图纪律同 Q21：背板图只复用/解引用，绝不主动 Bitmap.recycle()。
    static final float BACKDROP_SCALE = 0.20f;
    static final int[] BACKDROP_BLUR_R = {2, 4, 6};        // Q105 拉档距（旧 2/3/5）：薄透≈10px / 标准≈22px / 毛玻璃≈34px（全分辨率 σ 折算）
    static final float[] BACKDROP_SAT = {1.20f, 1.55f, 1.9f}; // Q105 拉档距（旧 1.35/1.6/1.9）：薄透近原色、浓档仍是 Q99 基准 1.9
    static final long BACKDROP_MIN_INTERVAL_MS = 50;
    Bitmap backdropBmp = null;
    boolean backdropCapturing = false;
    boolean backdropHookInstalled = false;
    long backdropLastCapMs = 0;
    // Q130（2.42，件五/八）：frozen 玻璃窗通用冻结武装位——无 frozen 窗在场时为 true；
    // 任一 frozen 窗从无到有只放行一帧 captureBackdrop 抓冻结帧后置 false，窗在场期间
    // tick 不再整树重抓＋三遍模糊。false→无窗时自然重新武装（见 captureBackdropTick 尾段）。
    boolean frozenFrameArmed130 = true;
    // Q131（2.43）：色带拖动排序的末次触摸打点（开拖与每次 MOVE 刷新）——tick 在
    // 350ms 窗内跳过背板抓图/录制，防拖动帧与抓图抢主线程、松手瞬间挤帧（件一）。
    long dragReorderTouchMs131 = 0;
    // Q131：色带落位动画代次——落位未稳时再起拖，旧落位的收尾（摘拖动态框/影）
    // 回调凭此作废，不许把新拖动态的框误摘（件一）。
    int customDragGen131 = 0;
    // Q98：滚动冻结与失败自愈的状态位——lastScrollEventMs 由根视图滚动监听打点，
    // preDraw 抓图在滚动活跃期（末次滚动事件 200ms 内）跳过，背板稳定冻结、滚动
    // 零采样不抢主线程，停稳由既有 650ms 防抖强制重抓一帧；backdropFailStreak 数
    // 抓图/绘制的连续失败，单次失败只丢帧、下一帧自然重试，连续 3 次才持久关停。
    long lastScrollEventMs = 0;
    int backdropFailStreak = 0;
    final Paint backdropPaint = new Paint(Paint.FILTER_BITMAP_FLAG);
    int backdropPaintLevel = -1;
    final android.view.ViewTreeObserver.OnPreDrawListener backdropPreDraw =
        new android.view.ViewTreeObserver.OnPreDrawListener() {
            @Override public boolean onPreDraw() {
                captureBackdropTick();
                return true;
            }
        };

    // ---------- Q99 文档条带背板（live 玻璃同帧跟随） ----------
    // Q98 的「滚动冻结＋停稳 650ms 重抓」手感是停一秒才变（用户 18:31 点名）。Q99 改：
    // live 玻璃（dock/悬浮钮/胶囊）不再采样屏幕快照，改采样当前长滚动页的「文档条带」——
    // 以当前 scrollY 为中心、上下各半屏高的一段内容，降采样糊化成一张共享位图；滚动
    // 本质是内容平移，玻璃件 onDraw 时按当前 scrollY 取位图对应文档行，同帧对位、无
    // 需逐帧重抓重糊。条带只在结构性变化（切页/开关窗/数据重渲染/尺寸变）与取景区
    // 滑出条带时重抓（滚动活跃期顺延到停稳，靠既有 650ms 防抖落定）。frozen 玻璃
    // （底表/弹层，身后场景静止）仍走屏幕快照 backdropBmp，两路在 GlassBackdropView
    // .onDraw 按 tag 分流。整条 dock 同一张条带同一帧取景——Q98 左半旧帧/右半新帧
    // 的竖缝（两帧屏幕快照拼接感）从根上消失。
    Bitmap bandBmp = null;
    ScrollView bandBmpSv = null;   // 条带所属滚动页（切页即作废）
    // bandDocTopPx 复用 Q41 字段（条带顶端在文档坐标中的 y，全分辨率 px）
    int bandFullH = 0;             // 条带覆盖的文档高度（全分辨率 px）= bandBmp.height / SCALE
    long lastBandCapMs = 0;
    boolean bandCapPending = false;
    final Runnable bandCapTask = new Runnable() {
        @Override public void run() {
            // Q94：甩动期不再无限顺延（旧口径滚动活跃即 180ms 一路推迟，整场甩动条带
            // 一次不刷，玻璃钳在过期旧帧上发黑发实）；距上次抓图已满 500ms 就照抓——
            // 只画滚动子树、成本有界，条带新鲜度钉在半秒内，钳边垫帧转瞬即逝。
            // 500ms 内的活跃滚动仍顺延，不与滚动帧抢主线程（Q98 抖动教训不回退）。
            long now = android.os.SystemClock.uptimeMillis();
            if (now - lastScrollEventMs < 120 && now - lastBandCapMs < 500) {
                mainHandler.postDelayed(this, 180);
                return;
            }
            bandCapPending = false;
            captureBand();
        }
    };

    void scheduleBandCapture() {
        if (bandCapPending || glassDisabled) return;
        bandCapPending = true;
        mainHandler.postDelayed(bandCapTask, 180);
    }

    /** 抓当前长滚动页的文档条带并糊化（只画滚动子树，比整根抓图轻；结构性时刻调用）。 */
    void captureBand() {
        if (backdropCapturing || glassDisabled || helloOpen || rootView == null) return;
        ScrollView sv = bandScroll();
        if (sv == null || sv.getChildCount() == 0) { bandBmp = null; bandBmpSv = null; return; }
        View inner = sv.getChildAt(0);
        int contentH = inner.getHeight(), viewH = sv.getHeight(), viewW = inner.getWidth();
        if (contentH <= 0 || viewH <= 0 || viewW <= 0) return;
        long nowMs = android.os.SystemClock.uptimeMillis();
        int margin = viewH / 2;
        int bandH = Math.min(contentH, viewH + 2 * margin);
        int docTop = sv.getScrollY() - margin;
        docTop = Math.max(0, Math.min(docTop, Math.max(0, contentH - bandH)));
        int bw = Math.max(1, Math.round(viewW * BACKDROP_SCALE));
        int bh = Math.max(1, Math.round(bandH * BACKDROP_SCALE));
        backdropCapturing = true; // 抓图期间玻璃件自排除（同屏幕背板口径）
        // Q103（2.17）：与屏幕背板同口径把玻璃宿主整面让开——搜索胶囊本体就嵌在滚动
        // 内容里，只让玻璃层自排除挡不住胶囊的文字/图标被拍进条带：糊化后又垫回真实
        // 文字正下方，错开一两像素就是用户实拍的「你好」荧光晕边。隐藏只改可见性、
        // 不动布局尺寸，finally 原样恢复。
        java.util.Map<View, Integer> bandSavedVis = new java.util.HashMap<>();
        try {
            for (ImageView iv : new java.util.ArrayList<>(glassViews)) {
                View h = glassHosts.get(iv);
                View t = h != null ? h : iv;
                if (t != null && t.isAttachedToWindow() && !bandSavedVis.containsKey(t)) {
                    bandSavedVis.put(t, t.getVisibility());
                    t.setVisibility(View.INVISIBLE);
                }
            }
            if (bandBmp == null || bandBmp.isRecycled() || bandBmp.getWidth() != bw || bandBmp.getHeight() != bh) {
                bandBmp = Bitmap.createBitmap(bw, bh, Bitmap.Config.ARGB_8888); // 旧图只解引用（Q21）
            }
            Canvas cv = new Canvas(bandBmp);
            cv.drawColor(colBg()); // 内容透明区（玻璃宿主自排除留下的空位）以页底色垫齐
            cv.scale(BACKDROP_SCALE, BACKDROP_SCALE);
            cv.translate(-inner.getLeft(), -(docTop + inner.getTop()));
            inner.draw(cv);
            stackBlur(bandBmp, BACKDROP_BLUR_R[Math.max(0, Math.min(2, glassLevel))]);
            updateBackdropPaint();
            bandBmpSv = sv;
            bandDocTopPx = docTop;
            bandFullH = bandH;
            lastBandCapMs = nowMs;
            backdropFailStreak = 0;
            noteGlassSuccess();
        } catch (Throwable t) {
            noteBackdropFailure();
        } finally {
            for (java.util.Map.Entry<View, Integer> e : bandSavedVis.entrySet()) {
                try { e.getKey().setVisibility(e.getValue()); } catch (Throwable ignored) {}
            }
            backdropCapturing = false;
        }
        try {
            for (ImageView iv : new java.util.ArrayList<>(glassViews)) {
                if (iv instanceof GlassBackdropView && "live".equals(iv.getTag())) iv.invalidate();
            }
        } catch (Throwable ignored) {}
    }

    /** 滚动事件里调用：live 玻璃逐帧按新 scrollY 重采样（仅 invalidate，onDraw 内只做位图平移）。 */
    void invalidateLiveGlass() {
        if (glassDisabled || glassViews.isEmpty()) return;
        if (glassViews.size() > 400) pruneGlass();
        for (ImageView iv : glassViews) {
            if (iv instanceof GlassBackdropView && "live".equals(iv.getTag()) && iv.isShown()) iv.invalidate();
        }
    }

    boolean anyFrozenGlassShown() {
        for (ImageView iv : glassViews) {
            if (iv instanceof GlassBackdropView && !"live".equals(iv.getTag()) && iv.isAttachedToWindow() && iv.isShown()) return true;
        }
        return false;
    }

    /** Q98：preDraw 抓图入口——滚动活跃期（末次滚动事件 200ms 内）稳定冻结背板：
     * 滚动全程不抓图（旧链每 50ms 在主线程整树重绘＋三遍模糊，既与滚动帧抢主线程
     * 造成下拉抽搐，背板又以 20fps 阶梯换帧在玻璃件下跳）；停稳满 200ms 后 preDraw
     * 自然恢复跟随，且既有 650ms 停稳防抖会强制重抓一帧对齐。强制抓图（切页/开关窗/
     * 设置变更）走 captureBackdrop() 直调，不受冻结影响。 */
    void captureBackdropTick() {
        // Q131（2.43，件四）：守卫顺序调整——hello/菜单/详情三道 return 提前到
        // recordHwBackdrop 之前。旧序下只要 preDraw 在跑，recordHwBackdrop 每帧先把
        // 根视图整树录一遍 RenderNode（HW_BACKDROP_SCALE 0.5）才轮到守卫 return：
        // 详情窗内滑动时与 Q118「窗内零重抓」自相矛盾（软件路已冻结、硬件路还在逐帧
        // 整树录制）。详情冻结帧由 openDetail 的 +300ms 结构性抓帧供齐（含
        // captureBackdrop 末尾的节点录制），此处不再逐帧录。record 自带 helloOpen
        // 守卫、菜单由 moreMenuBackdropFrozen 同闸，提前 return 净效果不变。
        if (helloOpen) return; // Q99：你好页入场动画全程冻结背板采样，不与飞入抢主线程
        if (moreMenuBackdropFrozen) return; // Q102：⋯ 菜单开窗期间背板冻结（开窗瞬间已同步抓存静止帧），不许动画期逐帧整屏重抓＋三遍模糊抖背景
        if (detailCard != null) return; // Q118（2.31）：详情窗在场——冻结玻璃只用开窗落定那一帧（openDetail 已排一次结构性重抓），窗内上下滑动绝不再逐帧整树重抓＋三遍模糊（慢拖中途停顿逾 200ms 即被本 tick 抓一帧，正是详情页滑动卡顿主源）
        boolean frozenShown130 = anyFrozenGlassShown();
        // Q131：frozen 窗在场且冻结帧已备齐（武装位已落）时，硬件录制与软件抓图同
        // 口径停录——窗玻璃消费的是冻结帧，逐帧重录纯耗主线程且会把动画中的窗体
        // 录进节点自引用。无窗或正处武装帧（开窗跃迁）时照旧录。
        if (!frozenShown130 || frozenFrameArmed130) recordHwBackdrop();
        // Q131：我的卡片色带拖动排序期间同冻结——拖动每帧 setTranslationY 都触发
        // root preDraw，此刻抓图/录制与拖动帧抢主线程，松手瞬间又恰逢落位重排，
        // 两股活挤在一帧即用户所见「放下闪」。以末次拖动触摸打点 350ms 为界（覆盖
        // 140ms 落位动画），超时自动失效防 finish 未达时永久冻结。
        if (android.os.SystemClock.uptimeMillis() - dragReorderTouchMs131 < 350) return;
        if (android.os.SystemClock.uptimeMillis() - lastScrollEventMs < 200) return;
        // Q99：屏上只有 live 玻璃且文档条带有效时，屏幕快照不必逐帧重抓——live 玻璃走
        // 条带按 scrollY 同帧取景；重抓整根只剩抢主线程。有 frozen 玻璃（底表/弹层）
        // 或无长滚动页（条带无源）时照旧抓屏幕背板；条带失效则顺手补抓条带。
        // Q130（2.42，件五/八）：frozen 窗通用冻结——旧口径下任一 frozen 窗在场时每个
        // preDraw 都整树软件绘制＋三遍盒式模糊（50ms 节流），与约 280–400ms 的进场动画
        // 抢主线程，正是「＋」加入底窗/常识窗/筛选窗等弹窗出场顿、动画僵的共同根因。详情
        // （Q118 detailCard 守卫）与 ⋯ 菜单（Q102 moreMenuBackdropFrozen）已有专属冻结，
        // 现泛化到全部 frozen 窗：从无到有只放行一帧抓冻结帧（与窗自带的直接结构性抓帧
        // 同帧同图、互不叠加），之后冻结至无窗在场再重新武装。玻璃参数/默认值/硬件录制
        // （recordHwBackdrop）一字未动，只改执行时机。
        if (!frozenShown130) {
            frozenFrameArmed130 = true;
            if (bandScroll() != null) {
                if (bandBmp == null || bandBmpSv != bandScroll()) scheduleBandCapture();
                return;
            }
        } else if (!frozenFrameArmed130) {
            return; // 冻结帧已抓：窗在场期间（含进场动画全程）tick 零重抓
        }
        captureBackdrop();
        if (frozenShown130) frozenFrameArmed130 = false;
    }

    // Q131（2.43，件四）：开窗前预抓冻结帧——Q130 的武装位只保证开窗后「不再逐帧
    // 重抓」，但从无窗到有窗的跃迁帧仍放行一次整树软件绘制＋三遍盒式模糊，恰落在
    // 约 280ms 进场动画的首帧上，动画被堵成「蹲一下再升起」（用户 2.42 终审仍报
    // 筛选/常识开窗卡）。改：开窗方在窗上屏之前（点击事件内、动画时钟未启）同步把
    // 这一帧抓掉，落点无窗的纯页面、正是要冻结的身后场景；抓成即同步落武装位，
    // 首个 preDraw 起 tick 零重抓、动画全程只剩已备帧绘制。被 50ms 节流挡下且无
    // 旧帧时不动武装位，tick 仍按 Q130 放行一帧兜底（旧行为）。
    void prepareFrozenBackdrop131() {
        if (glassDisabled || helloOpen || detailCard != null || moreMenuBackdropFrozen) return;
        if (anyFrozenGlassShown()) return; // 已有 frozen 窗在场：背板已冻结，复用现帧
        try { captureBackdrop(); } catch (Throwable ignored) {}
        if (backdropBmp != null) frozenFrameArmed130 = false;
    }

    /** Q98：背板失败计数——单次抓图/绘制异常只丢这一帧（旧帧继续垫着），连续 3 次
     * 才走 disableGlassNow 一次性持久关停。旧口径「任一 Throwable 即永久关停」会让
     * 开悬浮搜索（键盘顶起、窗口尺寸骤变那一帧）之类的瞬时异常把玻璃永久打死、
     * 之后怎么点都不恢复（用户 17:12 实拍）；成功一帧即清零，状态机自愈。 */
    void noteBackdropFailure() {
        backdropFailStreak++;
        if (backdropFailStreak >= 3) disableGlassNow();
    }

    /** 绘制期饱和滤镜按当前档位刷新（档位没变不重建滤镜对象）。 */
    void updateBackdropPaint() {
        if (backdropPaintLevel == glassLevel) return;
        backdropPaintLevel = glassLevel;
        ColorMatrix cm = new ColorMatrix();
        cm.setSaturation(BACKDROP_SAT[Math.max(0, Math.min(2, glassLevel))]);
        backdropPaint.setColorFilter(new ColorMatrixColorFilter(cm));
    }

    /** Q97 降级：新链任一环异常即一次性关停并持久化，玻璃件整面隐藏回静态染色。 */
    void disableGlassNow() {
        glassDisabled = true;
        glassAutoOff = true;
        refreshDockBg(); // Q117：自动停用同为关态，dock 兜底同步换上
        backdropFailStreak = 0; // Q98：关停落盘后计数归零，设置页重新打开即从干净状态重试
        try { if (prefs != null) prefs.edit().putBoolean("glass_disabled", true).putBoolean("glass_auto_off", true).apply(); } catch (Throwable ignored) {}
        try {
            for (ImageView iv : new java.util.ArrayList<>(glassViews)) {
                try { iv.setVisibility(View.INVISIBLE); } catch (Throwable ignored) {}
            }
        } catch (Throwable ignored) {}
        backdropBmp = null; // 只解引用交系统回收（Q21 纪律，不 recycle）
        bandBmp = null; bandBmpSv = null; // Q99：条带背板同步作废
    }

    /** 背板玻璃层：自身不持位图，onDraw 只把共享背板按位置对位绘出。
     * Q99：live 件采样文档条带（按当前 scrollY 取文档行，同帧跟随）；frozen 件与
     * 条带无源时采样屏幕快照。两种取景共用同一组「平移→1/scale 放大」对位数学。 */
    class GlassBackdropView extends ImageView {
        boolean hwPilot = false; // Q108 硬件玻璃实验标（2.22 试点两件，Q109 起全件），onDraw 首行分流
        String hwKey = null;     // Q111 金丝雀记账身份（glassLayerHw 构造时注入，见 HW_PIECE_ORDER）
        final int[] rl2 = new int[2];
        final int[] ml2 = new int[2];
        final int[] sl2 = new int[2];
        GlassBackdropView(Context c) { super(c); }

        /** Q111 金丝雀闸门（本件本帧是否准走硬件路）：已证→准；已退→拒；未证→须
         * 已挣资格＋本进程满 3 秒＋试验位空着（Q112 延迟资格），且同屏没有更靠前
         * 的有资格未证件在场时才准，申领瞬间把件名同步落盘（glass_hw_trial）——
         * 绘制紧随其后，若原生崩死在本帧，试验标记永不被清，下次冷启由
         * initHwGlassGuard 判定该件单独退软件。名册外一律拒（Q112 不变量）。
         * 附带退化守卫：未挂载或宽高 ≤2 的件（首帧未落位/动画近零缩放）一律走
         * 软件兜底，不拿退化尺寸去碰 drawRenderNode。Java 级判定全程不抛。 */
        boolean hwDrawGate() {
            String k = hwKey;
            if (k == null || !isAttachedToWindow() || getWidth() <= 2 || getHeight() <= 2) return false;
            if (hwOrderIdx(k) < 0) return false; // Q112：名册外（live 常驻件/详情主钮）永远软件
            if (hwProven.contains(k)) return true;
            if (hwDeadPieces.contains(k)) return false;
            // Q112 延迟资格：未证件须已在往期会话挣得资格，且本进程已满 3 秒（首帧
            // 永不做试验场）；没资格的件在本进程画一万次也只走软件链。
            if (!hwEligible.contains(k)) return false;
            if (android.os.SystemClock.uptimeMillis() - hwSessionStartMs < 3000) return false;
            if (hwTrialClaimedBy != null) return k.equals(hwTrialClaimedBy);
            int myIdx = hwOrderIdx(k);
            for (ImageView iv2 : glassViews) {
                if (iv2 == this || !(iv2 instanceof GlassBackdropView)) continue;
                String k2 = ((GlassBackdropView) iv2).hwKey;
                if (k2 == null || k2.equals(k)) continue;
                int i2 = hwOrderIdx(k2);
                if (i2 >= 0 && i2 < myIdx && hwEligible.contains(k2) && !hwProven.contains(k2) && !hwDeadPieces.contains(k2)
                    && iv2.isAttachedToWindow() && iv2.isShown()) return false; // 让更靠前的有资格未证件先试
            }
            hwTrialClaimedBy = k;
            hwArmTrial(k); // 必须赶在 drawRenderNode 之前 commit 落盘（原生崩 Java 记不上账）
            return true;
        }

        /** 本帧 drawRenderNode 已成功返回：该件入证（写已证集合同步落盘并清试验标记）。 */
        void hwDrawProven() {
            String k = hwKey;
            if (k == null || hwProven.contains(k)) return;
            hwProven.add(k);
            hwEligible.remove(k); // Q112：已证即摘资格集（hwPersistPieces 一并落盘）
            hwPersistPieces();
        }
        @Override protected void onDraw(Canvas canvas) {
            // 抓图进行中自排除（否则背板画进背板自引用，同 LIQUID-GLASS-NOTES 红线）；
            // 玻璃被关停/背板未就绪时什么都不画，宿主下方薄染色兜底直接显形，绝不白屏。
            if (backdropCapturing || glassDisabled || rootView == null) return;
            try {
                rootView.getLocationInWindow(rl2);
                getLocationInWindow(ml2);
                canvas.save();
                // Q92 硬兜底：先把画布裁到本层自身 bounds——无论宿主布局如何异常，
                // 玻璃取样层物理上不可能画出自身矩形之外（防再次全屏糊层事故）。
                canvas.clipRect(0, 0, Math.max(1, getWidth()), Math.max(1, getHeight()));
                // Q108 硬件试点分流：节点与本层同一组对位数学（平移→1/scale 放大），
                // 只是取景源换成 RenderNode（模糊＋饱和在录制期由节点 RenderEffect 承担）。
                // Q111 改逐件取证：准入由 hwDrawGate（已证/金丝雀试验位/退化守卫）判定，
                // 首帧成功返回即本件入证并写全局 stable——原生崩若发生在本行之内两样都
                // 不落盘，未清的试验标记由下次冷启 initHwGlassGuard 判该件单独退软件。
                if (hwPilot && hwGlassEnabled && !hwGlassDead && hwNodeValid && hwNode != null
                    && Build.VERSION.SDK_INT >= 31 && hwDrawGate()) {
                    canvas.translate(-(ml2[0] - rl2[0]), -(ml2[1] - rl2[1]));
                    canvas.scale(1f / HW_BACKDROP_SCALE, 1f / HW_BACKDROP_SCALE);
                    canvas.drawRenderNode(hwNode);
                    canvas.restore();
                    hwDrawProven(); // Q111：首帧成功返回即入证（崩在本行之内则永不执行，试验标记留作铁证）
                    markHwStable();
                    return;
                }
                Bitmap band = bandBmp;
                ScrollView bsv = bandScroll();
                boolean bandOk = "live".equals(getTag()) && band != null && !band.isRecycled()
                    && bsv != null && bsv == bandBmpSv;
                if (bandOk) {
                    // 文档条带取景：本件顶端对应的文档 y = 当前 scrollY + 本件在视口内的纵偏移；
                    // 取景区滑出条带时先钳到条带边缘垫一帧，并排一次条带重抓（活跃期自动顺延）。
                    bsv.getLocationInWindow(sl2);
                    float docX = (ml2[0] - sl2[0]) + bsv.getScrollX();
                    float docY = bsv.getScrollY() + (ml2[1] - sl2[1]);
                    float sampleX = docX;
                    float sampleY = docY - bandDocTopPx;
                    float maxSY = Math.max(0f, bandFullH - getHeight());
                    float clampedY = Math.max(0f, Math.min(sampleY, maxSY));
                    if (clampedY != sampleY) scheduleBandCapture();
                    canvas.translate(-sampleX, -clampedY);
                    canvas.scale(1f / BACKDROP_SCALE, 1f / BACKDROP_SCALE);
                    canvas.drawBitmap(band, 0, 0, backdropPaint);
                } else {
                    // 19:37 定点②切页守卫窗：条带刚作废、新带未落位这几帧里，屏幕快照
                    // 还是上一页的旧帧——照旧回落画出来就是在新页签周围晕一圈旧色
                    // （实拍药丸旁橙红晕的来源）。守卫窗（切页后 400ms）内 live 件不画
                    // 旧帧，宿主浅透染色先顶着，新带由 showTab 的 +32ms 立即重抓接上。
                    if ("live".equals(getTag())
                        && android.os.SystemClock.uptimeMillis() - glassTabSwitchMs < 400) {
                        canvas.restore(); return;
                    }
                    // Q94 回落链（用户 19:10 点名快速甩动玻璃变黑）：条带不可用/已过期时
                    // 一律落最近一帧有效背板（屏幕快照），绝不落空帧；屏幕帧也没有时什么
                    // 都不画，宿主下方的浅透染色兜底显形——染色已按浅透口径收淡，不许发黑。
                    Bitmap bmp = backdropBmp;
                    if (bmp == null || bmp.isRecycled()) { canvas.restore(); return; }
                    // 对位：背板以 BACKDROP_SCALE 降采样（图 px = 根坐标 × scale），绘出时先按
                    // 本层在根坐标中的位置平移、再 1/scale 放大回全分辨率，与身后实景 1:1。
                    canvas.translate(-(ml2[0] - rl2[0]), -(ml2[1] - rl2[1]));
                    canvas.scale(1f / BACKDROP_SCALE, 1f / BACKDROP_SCALE);
                    canvas.drawBitmap(bmp, 0, 0, backdropPaint);
                }
                canvas.restore();
            } catch (Throwable t) { /* Q98：单件单帧绘制异常只跳过本帧，不再一击拖死全 App 玻璃 */ }
        }
    }

    void ensureBackdropHook() {
        if (backdropHookInstalled || rootView == null) return;
        try {
            rootView.getViewTreeObserver().addOnPreDrawListener(backdropPreDraw);
            backdropHookInstalled = true;
        } catch (Throwable ignored) {}
    }

    // ---------- Q108 硬件玻璃实验（2.22，用户 22:03 授权单试，崩则自退） ----------
    // 背景定案：Q90 的 RenderNode＋RenderEffect 实时背板在用户机（vivo X200 Pro mini /
    // Android 15）HWUI 原生层崩溃、Java catch 不住、失败计数永不落盘永不自愈（Q96 定案，
    // 现行玻璃自 Q97 起走软件背板安全链）。本版只给两个试点件换实现通道同参数试水：
    // 底栏（live）＋设置 ⋯ 菜单（frozen），其余玻璃件与三档四轴数值（BACKDROP_BLUR_R /
    // BACKDROP_SAT / glassTintScale / glassWashScale）一律不动；硬件路模糊半径由软件档
    // 同源折算（0.20 采样 px → 全分辨率 σ → 节点采样 px），饱和用同一组 BACKDROP_SAT。
    // Q109（2.23，用户 22:47 拍板「先备份、然后铺开、玻璃全面铺开」）：试点两件真机
    // 未崩且质感获认，本版把全部 GlassBackdropView 件改走硬件通道（构造点统一经
    // glassLayerHw 打标，清单与保留件见 PROGRESS Q109）。护栏/开关/录制策略原样扩面，
    // 参数（BACKDROP_BLUR_R/BACKDROP_SAT/三档四轴/染色wash边光）逐字未动；窗口类
    // frozen 语义不变（仍采样身后场景，⋯ 菜单 Q102 冻结闸保留），live 类仍同帧跟随。
    // 自退护栏（替代 catch，原生崩 Java 记不上账）：双标记法——首帧真正录制前同步写
    // glass_hw_armed=true＋glass_hw_stable=false（commit，必须赶在 HWUI 出事前落盘）；
    // 首帧 drawRenderNode 成功返回后写 glass_hw_stable=true。冷启 initHwGlassGuard 若见
    // armed && !stable，即认定上一会话死在硬件路上：置 glass_hw_dead、关实验开关、留
    // 时间戳 glass_hw_note（设置行可查），全程回落软件链——「崩一次、重开即愈」。
    // 手动开关「硬件玻璃（实验）」（glass_hw_exp，Q113 起默认关＝止损停用）随时可关：硬件件 onDraw 逐帧
    // 查开关，关掉下一帧即回软件路（即时生效）；自动退回后重新打开＝清 dead 再试一轮。
    // Q111（2.24）事故修订：2.23 真机进主页首帧必崩且重开不愈——全局 stable 被先进场
    // 的已证/无害件先行写下，后崩的件永远被信任。护栏改逐件金丝雀记账（见下方
    // HW_PIECE_ORDER 起的新账本）：试验标记判死单件、全局双标记只作最后防线；另补
    // 录制期 backdropCapturing 自排除（与宿主同级并列的窗玻璃层在根视图录制时不再
    // 漏画，杜绝把节点画进节点自身录制画布的自引用形态）。
    static final float HW_BACKDROP_SCALE = 0.5f; // 节点录制缩放（软件链 0.20；硬件路取 0.5 换细腻度，仍非全分辨率）
    boolean hwGlassEnabled = false;   // 本进程硬件通道可用（启动护栏判定结果）
    boolean hwGlassDead = false;      // 已自动退回（或本进程判定不可用）
    boolean hwArmWritten = false;     // 本进程已写过 armed（懒写：推迟到首帧录制前，缩小误判窗）
    boolean hwStableMarked = false;   // 本进程已写过 stable
    boolean hwJustRetreated = false;  // 本次冷启刚发生自动退回（待 UI 就绪后提示一次）
    String hwGlassNote = "";          // 自动退回时间戳（glass_hw_note，设置行可查）
    android.graphics.RenderNode hwNode = null;
    boolean hwNodeValid = false;
    float hwEffectLevel = -1f;        // 节点 RenderEffect 已按哪档建（-1 未建）
    long hwLastRecordMs = 0;
    boolean hwRecording = false;

    // ---------- Q111 金丝雀逐件记账（2.24，事故修复：2.23 进主页必崩且重开不愈） ----------
    // 事故机制（代码坐实）：旧护栏只有一颗全局 stable——任一件首帧 drawRenderNode
    // 成功即 markHwStable 写入，此后哪件崩都因 stable 已落盘而被冷启护栏永久信任，
    // 「进主页必崩、重开照崩」。改逐件记账：prefs 三件套——已证集 glass_hw_proven
    // （CSV）、已退集 glass_hw_deadpieces（CSV）、在试标记 glass_hw_trial（单件 key）。
    // dock＋moremenu 是 2.22 真机实证的两件，首次装载新账时直接播种入证。
    // 规则：每冷启最多放一件未证件试硬件（HW_PIECE_ORDER 定序，同屏多件在场时靠前
    // 者先试）；该件首帧绘制前申领试验位并 commit 试验标记，绘制成功返回即入证清
    // 标记；若进程死在该帧，标记残留下次冷启被判「该件崩」→ 单独进已退集走软件链，
    // 换下一件继续试，全程不再出现全 App 必崩。全局 armed/stable 与实验开关保留为
    // 最后防线（仅当崩点不在任何在试件绘制内——如录制本身——才由全局口径整体自退）。
    // Q112（2.25）事故再修订：2.24 真机清数据后仍「欢迎页点开始使用进主页必崩」。
    // 验真（读码）：2.22 主页同帧硬件消费者只有底栏一件（⋯菜单不在主页），不崩；
    // 2.23/2.24 主页首帧同帧多件（底栏＋内嵌搜索胶囊＋搜索/筛选悬浮钮）对同一个共享
    // RenderNode 并发 drawRenderNode——崩点在「同帧多消费者」形态而非单独某件，金丝雀
    // 逐件放行救不了（放行第二件 live 件的那一帧就崩，且逐件标记归因不到组合）。
    // 不变量（本版起写死）：live 常驻场景硬件消费者只许底栏一件；内嵌/悬浮搜索胶囊、
    // 搜索/筛选/回顶钮、详情主钮（与详情窗同帧）永远走软件背板链（构造已改回
    // glassLayer，不进本名册）。窗件同屏至多一件在画（详情开窗 hideChrome 藏底栏、
    // 向导下开详情为窗＋窗的双消费者，与 2.22「底栏＋菜单」已证的双消费者同级），
    // 维持金丝雀逐件记账，另叠延迟资格：未证件须先在往期会话「主页稳定 3 秒」挣得
    // 资格（glass_hw_eligible），试验只从其后冷启、进程满 3 秒后的开窗路径开始，
    // 首帧永不做试验场。出厂态＝默认软件，硬件是挣来的资格。
    static final String[] HW_PIECE_ORDER = {
        "dock", "moremenu", "toast", "filterwin", "wizard", "detail", "cardmenu",
        "binwin", "customform", "customdetail", "acctpicker", "colorpicker",
        "delconfirm", "updatewin", "simkeep", "subfollow", "footprint", "extsearch"
    };
    static final String[] HW_PIECE_NAME_ZH = {
        "底栏", "设置菜单", "悬浮提示条", "筛选窗", "情景选卡窗", "详情窗", "长按菜单",
        "BIN 查询窗", "自定义卡表单", "自定义卡详情", "账户分类选择窗", "占位配色选择窗",
        "删除确认窗", "数据更新窗", "保号表单", "订阅表单", "足迹表单", "扩展搜卡窗"
    };
    static final String[] HW_PIECE_NAME_EN = {
        "Dock", "Settings menu", "Toast bar", "Filter sheet", "Wizard sheet", "Detail sheet", "Card menu",
        "BIN lookup", "Custom card form", "Custom card detail", "Account class picker", "Color picker",
        "Delete confirm", "Data update sheet", "SIM keep form", "Subscription form", "Footprint form", "Extended search"
    };
    final java.util.Set<String> hwProven = new java.util.HashSet<>();
    final java.util.Set<String> hwDeadPieces = new java.util.HashSet<>();
    final java.util.Set<String> hwEligible = new java.util.HashSet<>(); // Q112：已挣得试验资格（往期会话主页稳定 3 秒后落）
    String hwTrialClaimedBy = null;   // 本进程试验位已被哪件申领（每冷启至多一件）
    boolean hwPiecesLoaded = false;
    long hwSessionStartMs = 0;        // Q112：本进程起点（initHwGlassGuard 落），试验须待进程满 3 秒
    boolean hwEligibilityScheduled = false; // Q112：本进程已排过资格挣取计时

    int hwOrderIdx(String k) {
        if (k == null) return -1;
        for (int i = 0; i < HW_PIECE_ORDER.length; i++) if (HW_PIECE_ORDER[i].equals(k)) return i;
        return -1;
    }
    String hwPieceName(String k) {
        int i = hwOrderIdx(k);
        if (i < 0) return k == null ? "" : k;
        return isEn() ? HW_PIECE_NAME_EN[i] : HW_PIECE_NAME_ZH[i];
    }
    /** 待验证下一件：定序里第一个既未证也未退的件（设置行副文案展示）。 */
    String hwNextCandidate() {
        for (String k : HW_PIECE_ORDER) if (!hwProven.contains(k) && !hwDeadPieces.contains(k)) return k;
        return null;
    }
    static String hwJoinCsv(java.util.Set<String> s) {
        // 按 HW_PIECE_ORDER 定序拼 CSV（落盘稳定可读；定序外的 key 不会出现，构造点全在册）
        StringBuilder sb = new StringBuilder();
        for (String k : HW_PIECE_ORDER) if (s.contains(k)) { if (sb.length() > 0) sb.append(','); sb.append(k); }
        return sb.toString();
    }
    /** 新账装载（只跑一次）：已证/已退/资格集读盘；已证集缺失＝首次启用新账，播种 2.22 两件。
     * Q112：读盘一律按名册过滤——旧账里已移出名册的件（内嵌搜索胶囊等 live 件）自动
     * 作废回软件链，不许残留资格把它们再放回硬件。 */
    void loadHwPieces() {
        if (hwPiecesLoaded) return;
        hwPiecesLoaded = true;
        try {
            if (prefs == null) return;
            if (!prefs.contains("glass_hw_proven")) {
                hwProven.add("dock"); hwProven.add("moremenu"); // 2.22 用户真机实证没崩且质感获认
                prefs.edit().putString("glass_hw_proven", hwJoinCsv(hwProven)).apply();
            } else {
                String csv = prefs.getString("glass_hw_proven", "");
                if (csv != null) for (String k : csv.split(",")) { String t = k.trim(); if (!t.isEmpty() && hwOrderIdx(t) >= 0) hwProven.add(t); }
            }
            String dead = prefs.getString("glass_hw_deadpieces", "");
            if (dead != null) for (String k : dead.split(",")) { String t = k.trim(); if (!t.isEmpty() && hwOrderIdx(t) >= 0) hwDeadPieces.add(t); }
            String elig = prefs.getString("glass_hw_eligible", "");
            if (elig != null) for (String k : elig.split(",")) { String t = k.trim(); if (!t.isEmpty() && hwOrderIdx(t) >= 0 && !hwProven.contains(t) && !hwDeadPieces.contains(t)) hwEligible.add(t); }
        } catch (Throwable ignored) {}
    }
    /** 试验位落盘：绘制前申领（commit）——崩在本帧即留证，下次冷启据此判该件退软件。 */
    void hwArmTrial(String k) {
        try { if (prefs != null) prefs.edit().putString("glass_hw_trial", k).commit(); } catch (Throwable ignored) {}
    }
    /** 已证/已退/资格集落盘并清在试标记（入证与判死共用，commit 同步）。 */
    void hwPersistPieces() {
        try {
            if (prefs == null) return;
            prefs.edit()
                .putString("glass_hw_proven", hwJoinCsv(hwProven))
                .putString("glass_hw_deadpieces", hwJoinCsv(hwDeadPieces))
                .putString("glass_hw_eligible", hwJoinCsv(hwEligible))
                .putString("glass_hw_trial", "")
                .commit();
        } catch (Throwable ignored) {}
    }

    /** Q112 资格集单独落盘：不碰在试标记（挣资格与某件正在试验可同会话交错，
     * 清掉试验标记会让崩后归因失效，故与 hwPersistPieces 分开）。 */
    void hwPersistEligible() {
        try {
            if (prefs == null) return;
            prefs.edit().putString("glass_hw_eligible", hwJoinCsv(hwEligible)).commit();
        } catch (Throwable ignored) {}
    }

    /** Q112 资格挣取（每会话至多挣一件）：主页已稳定渲染满约 3 秒、进程还活着，
     * 才把定序里第一个未证/未退/未有资格的窗件落「下次可试」标记（commit）。
     * 由 showTab 首调后 postDelayed 3s 触发；欢迎页还没进主页（helloOpen）时每秒
     * 重排，直到主页真出来——首帧与欢迎页停留期永远挣不到资格。试验本身只在
     * 其后冷启、进程满 3 秒后的开窗绘制里发生（见 hwDrawGate），首帧不做试验场。 */
    void earnHwEligibility() {
        if (!hwGlassEnabled || hwGlassDead || glassDisabled) return;
        if (helloOpen) { mainHandler.postDelayed(this::earnHwEligibility, 1000); return; }
        try {
            loadHwPieces();
            for (String k : HW_PIECE_ORDER) {
                if (!hwProven.contains(k) && !hwDeadPieces.contains(k) && !hwEligible.contains(k)) {
                    hwEligible.add(k);
                    hwPersistEligible();
                    return;
                }
            }
        } catch (Throwable ignored) {}
    }
    void scheduleHwEligibility() {
        if (hwEligibilityScheduled) return;
        hwEligibilityScheduled = true;
        mainHandler.postDelayed(this::earnHwEligibility, 3000);
    }

    /** 冷启护栏（onCreate 读完玻璃 prefs 后调用，先于任何页面构建）：
     * 上一会话 armed 而无 stable ＝判定硬件路原生崩，永久关闭本实验（直到用户手动
     * 在设置里重新打开再试），并落时间戳留痕。本函数不写 armed——武装推迟到首帧
     * 录制前一刻（recordHwBackdrop 懒写），把「开了 App 没碰玻璃就被杀」的误判窗压到
     * 约一帧。API<31 无硬件路，实验恒关。
     * Q111（2.24）起判定顺序改为：逐件试验标记判死在前（单件退软件、全局不牵连），
     * 本全局双标记退为最后防线，仅当试验标记干净时才按 armed&&!stable 整体自退。 */
    void initHwGlassGuard() {
        hwGlassEnabled = false;
        hwSessionStartMs = android.os.SystemClock.uptimeMillis(); // Q112：试验 3 秒门槛的计时起点
        try { hwGlassNote = prefs == null ? "" : prefs.getString("glass_hw_note", ""); } catch (Throwable ignored) { hwGlassNote = ""; }
        if (Build.VERSION.SDK_INT < 31 || prefs == null) { hwGlassDead = true; return; }
        try {
            loadHwPieces(); // Q111：逐件账本先行装载（首次新账播种 2.22 实证两件）
            // Q113（2.26）止损一次性复位：用户 23:47 拍板「玻璃通通关掉先……最后再
            // 设置这个毛玻璃」。存量设备上 glass_hw_exp 可能已被 2.22–2.25 试开并落盘
            // 为 true，仅改默认值救不了升级用户——故以版本标记做一次性强制复位：
            // 实验关、武装/稳定/在试标记全清，本次冷启硬件恒关；之后用户仍可在设置
            // 里手动重开（副文案带「可能闪退」提示），金丝雀/资格/双标记代码保留停用。
            if (prefs.getInt("glass_hw_pause_ver", 0) < 226) {
                prefs.edit().putInt("glass_hw_pause_ver", 226)
                    .putBoolean("glass_hw_exp", false)
                    .putBoolean("glass_hw_armed", false)
                    .putBoolean("glass_hw_stable", false)
                    .putString("glass_hw_trial", "")
                    .commit(); // 同步落盘：止损决定不许丢
                hwGlassDead = prefs.getBoolean("glass_hw_dead", false);
                return; // hwGlassEnabled 保持 false：全件本启走软件链
            }
            hwGlassDead = prefs.getBoolean("glass_hw_dead", false);
            boolean exp = prefs.getBoolean("glass_hw_exp", false); // Q113：默认关（止损），须用户在设置里手动重开
            if (hwGlassDead || !exp) return;
            // Q111 逐件判死（先于全局兜底）：上次进程残留在试标记且该件未入证＝进程死在
            // 该件首帧硬件绘制内——只判该件退软件（留时间戳、换下一件），全局不牵连。
            boolean trialResolved = false;
            String trial = prefs.getString("glass_hw_trial", "");
            if (trial != null && !trial.isEmpty()) {
                trialResolved = true;
                if (hwProven.contains(trial) || hwOrderIdx(trial) < 0) {
                    // 已入证的残留、或 Q112 移出名册的旧件残留：只清标记，不判死
                    try { prefs.edit().putString("glass_hw_trial", "").commit(); } catch (Throwable ignored) {}
                } else {
                    hwDeadPieces.add(trial);
                    hwGlassNote = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.US).format(new java.util.Date());
                    try { prefs.edit().putString("glass_hw_note", hwGlassNote).commit(); } catch (Throwable ignored) {}
                    hwPersistPieces(); // 已退集落盘＋清在试标记（同步）
                }
            }
            // 全局最后防线（原 Q108 双标记）：仅当崩点不在任何在试件绘制内（试验标记
            // 干净却 armed 无 stable，如崩在录制本身）才整体自退——逐件账在场时不许
            // 再出现「一件成功全盘信任、一件崩全盘陪葬」的旧毒。
            if (!trialResolved) {
                boolean armed = prefs.getBoolean("glass_hw_armed", false);
                boolean stable = prefs.getBoolean("glass_hw_stable", false);
                if (armed && !stable) {
                    hwGlassDead = true;
                    hwJustRetreated = true;
                    hwGlassNote = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.US).format(new java.util.Date());
                    prefs.edit().putBoolean("glass_hw_dead", true)
                        .putBoolean("glass_hw_exp", false)
                        .putBoolean("glass_hw_armed", false)
                        .putString("glass_hw_note", hwGlassNote)
                        .commit(); // 同步落盘：退回决定不许丢
                    return;
                }
            }
            hwGlassEnabled = true;
        } catch (Throwable ignored) { hwGlassEnabled = false; }
    }

    void markHwStable() {
        if (hwStableMarked) return;
        hwStableMarked = true;
        try { if (prefs != null) prefs.edit().putBoolean("glass_hw_stable", true).commit(); } catch (Throwable ignored) {}
    }

    /** 节点效果链按当前档重建（三档数值与软件链同源，不新设参数）：
     * 模糊半径＝BACKDROP_BLUR_R（0.20 采样 px）÷0.20 得全分辨率 σ 量级，再乘节点采样
     * HW_BACKDROP_SCALE 换回节点 px；饱和直接用 BACKDROP_SAT 同档。档位未变不重建。 */
    boolean updateHwEffect() {
        if (hwNode == null || Build.VERSION.SDK_INT < 31) return false;
        if (hwEffectLevel == glassLevel) return false;
        hwEffectLevel = glassLevel;
        try {
            int lv = Math.max(0, Math.min(2, glassLevel));
            float r = (BACKDROP_BLUR_R[lv] / BACKDROP_SCALE) * HW_BACKDROP_SCALE;
            ColorMatrix cm = new ColorMatrix();
            cm.setSaturation(BACKDROP_SAT[lv]);
            android.graphics.RenderEffect sat =
                android.graphics.RenderEffect.createColorFilterEffect(new ColorMatrixColorFilter(cm));
            android.graphics.RenderEffect blur =
                android.graphics.RenderEffect.createBlurEffect(r, r, sat, android.graphics.Shader.TileMode.CLAMP);
            hwNode.setRenderEffect(blur);
            return true;
        } catch (Throwable t) { return false; }
    }

    /** 硬件背板录制：玻璃宿主整面让开后把根视图以 HW_BACKDROP_SCALE 录进共享
     * RenderNode（preDraw 钩子与结构性抓图点调用，每帧至多一次）。Java 级异常只废
     * 这一帧、试点件自动回落软件路，不计数关停——原生崩靠启动期双标记自退，不在此
     * 处理。录制成功且节点由无效转有效（或效果换档）时才让试点件重绘，避免
     * 「录制→invalidate→再录制」自激空转：常态重绘由滚动/建页的既有失效驱动。 */
    void recordHwBackdrop() {
        if (!hwGlassEnabled || hwGlassDead || glassDisabled || helloOpen || rootView == null) return;
        if (Build.VERSION.SDK_INT < 31 || hwRecording || backdropCapturing) return;
        int rw = rootView.getWidth(), rh = rootView.getHeight();
        if (rw <= 0 || rh <= 0) return;
        long now = android.os.SystemClock.uptimeMillis();
        if (now - hwLastRecordMs < 16) return; // 至多每帧一次，防连环重绘自激
        hwLastRecordMs = now;
        if (!hwArmWritten) {
            // 武装：必须在第一次真正碰 HWUI 之前同步落盘（commit），崩在录制/绘制
            // 任一环，下次冷启 armed && !stable 即被识别为硬件崩并自退。
            hwArmWritten = true;
            try { if (prefs != null) prefs.edit().putBoolean("glass_hw_armed", true).putBoolean("glass_hw_stable", false).commit(); } catch (Throwable ignored) {}
        }
        java.util.Map<View, Integer> saved = new java.util.HashMap<>();
        hwRecording = true;
        // Q111（2.24，坐实形态）：录制期置 backdropCapturing——根视图录制画布遍历全树时
        // 全部 GlassBackdropView 一律自排除。旧路只按 glassHosts 藏宿主，而窗玻璃层与宿主
        // 卡在 wrap 里同级并列（详情/情景/BIN/表单/选色等窗），宿主藏了玻璃层本体不藏，
        // 录制中它照样 onDraw 并对正在录制的同一个 hwNode 执行 drawRenderNode＝把节点
        // 画进节点自己的录制画布（自引用，原生层高危）。软件路 captureBackdrop 早有此标，
        // 硬件录制漏置，本版补齐；录后再由各件对已录完的节点正常消费，不影响同帧跟随。
        backdropCapturing = true;
        boolean wasValid = hwNodeValid;
        try {
            for (ImageView iv : new java.util.ArrayList<>(glassViews)) {
                View h = glassHosts.get(iv);
                View t = h != null ? h : iv;
                if (t != null && t.isAttachedToWindow() && !saved.containsKey(t)) {
                    saved.put(t, t.getVisibility());
                    t.setVisibility(View.INVISIBLE);
                }
            }
            int bw = Math.max(1, Math.round(rw * HW_BACKDROP_SCALE));
            int bh = Math.max(1, Math.round(rh * HW_BACKDROP_SCALE));
            if (hwNode == null) hwNode = new android.graphics.RenderNode("cardboxHwGlass");
            hwNode.setPosition(0, 0, bw, bh);
            android.graphics.Canvas rc = hwNode.beginRecording(bw, bh);
            rc.drawColor(colBg()); // 宿主让开的空位以页底色垫齐（与 captureBackdrop 同口径）
            rc.scale(HW_BACKDROP_SCALE, HW_BACKDROP_SCALE);
            rootView.draw(rc);
            hwNode.endRecording();
            boolean effectChanged = updateHwEffect();
            hwNodeValid = true;
            if (!wasValid || effectChanged) invalidateHwPilots();
        } catch (Throwable t) {
            hwNodeValid = false; // 只废这一帧：硬件件回落软件背板/染色，不拖死全局（原生崩另有启动护栏）
        } finally {
            for (java.util.Map.Entry<View, Integer> e : saved.entrySet()) {
                try { e.getKey().setVisibility(e.getValue()); } catch (Throwable ignored) {}
            }
            backdropCapturing = false; // Q111：与置位成对恢复（录制互斥标 hwRecording 同段）
            hwRecording = false;
        }
    }

    void invalidateHwPilots() {
        try {
            for (ImageView iv : new java.util.ArrayList<>(glassViews)) {
                if (iv instanceof GlassBackdropView && ((GlassBackdropView) iv).hwPilot) iv.invalidate();
            }
        } catch (Throwable ignored) {}
    }

    /** 实验开关即时落地：开→立刻录一帧并让硬件件重绘；关→各件下一帧 onDraw 自查
     * 开关自动回落软件路，本函数只需补一帧软件背板并令其重绘，不必重建任何页。 */
    void applyHwGlassChange() {
        if (hwGlassEnabled) {
            recordHwBackdrop();
        } else {
            hwNodeValid = false;
            if (!glassDisabled) { backdropLastCapMs = 0; captureBackdrop(); }
        }
        invalidateHwPilots();
    }

    /** 设置行副文案：退回留痕（时间戳）在此可查。 */
    /** Q111 逐件账面状态一行（设置实验行副文案尾巴）：已验证 N/24 · 已退回软件 M · 待验证下一件。 */
    String hwPieceStatus() {
        try {
            loadHwPieces();
            int total = HW_PIECE_ORDER.length;
            String next = hwNextCandidate();
            if (isEn()) return " · HW-verified " + hwProven.size() + "/" + total
                + (hwDeadPieces.isEmpty() ? "" : " · software-reverted " + hwDeadPieces.size())
                + (next == null ? "" : " · next trial: " + hwPieceName(next));
            return " · 硬件已验证 " + hwProven.size() + "/" + total
                + (hwDeadPieces.isEmpty() ? "" : " · 已退回软件 " + hwDeadPieces.size())
                + (next == null ? "" : " · 待验证下一件：" + hwPieceName(next));
        } catch (Throwable t) { return ""; }
    }
    String hwGlassDesc() {
        if (Build.VERSION.SDK_INT < 31) return isEn() ? "Needs Android 12+ for the hardware path" : "需 Android 12 以上才有硬件通道";
        if (glassDisabled) return isEn() ? "Glass is off — turn Glass Effect on first" : "玻璃效果已关闭，先打开上面的玻璃效果";
        if (hwGlassDead && hwJustRetreated || (hwGlassDead && !hwGlassNote.isEmpty() && !hwGlassEnabled)) {
            return isEn() ? "Crashed last time — auto-reverted to safe glass (" + hwGlassNote + "). Turn on to retry"
                          : "上次开启后闪退，已自动退回安全玻璃（" + hwGlassNote + "），重新打开可再试";
        }
        if (hwGlassEnabled) return (isEn() ? "Beta: dock plus piece-by-piece verified sheets use hardware real-time blur; the rest stays software. May crash; reverts automatically on relaunch"
                                         : "实验中：底栏与逐件验证通过的窗件走硬件实时模糊，其余软件磨砂；可能闪退，闪退后重开自动退回") + hwPieceStatus();
        return (isEn() ? "Paused — all glass uses the safe software blur; hardware glass is scheduled last, after features and UI are done. Turning it on may crash"
                      : "已暂停（排期最后）：全部玻璃走安全软件磨砂；功能与 UI 收官后再议。手动打开可能闪退，闪退后重开自动退回") + hwPieceStatus();
    }

    /** 手写盒式模糊（三遍滑动窗均值近似高斯，边缘钳制取样）；直接在像素数组上原地进行。
     * Q131（2.43，件四）：通道拆装改位运算——原实现每像素每趟约 40 次 Color.alpha/
     * red/green/blue/argb 静态调用（三遍×横竖 6 趟、约 23 万像素），在开窗抓帧里是
     * 与整树绘制并列的主线程大头。位移/掩码与 android.graphics.Color 的实现逐位
     * 等价（ARGB_8888 打包、除数同为 win），产出像素逐位不变、玻璃观感一字不动。 */
    static void boxBlurPass(int[] px, int w, int h, int r, int[] tmp) {
        if (r < 1 || w <= 0 || h <= 0) return;
        int win = 2 * r + 1;
        // 横向
        for (int y = 0; y < h; y++) {
            int row = y * w;
            long sa = 0, sr = 0, sg = 0, sb = 0;
            for (int i = -r; i <= r; i++) {
                int c = px[row + Math.max(0, Math.min(w - 1, i))];
                sa += c >>> 24; sr += (c >> 16) & 0xFF; sg += (c >> 8) & 0xFF; sb += c & 0xFF;
            }
            for (int x = 0; x < w; x++) {
                tmp[row + x] = ((int) (sa / win) << 24) | ((int) (sr / win) << 16) | ((int) (sg / win) << 8) | (int) (sb / win);
                int cout = px[row + Math.max(0, Math.min(w - 1, x - r))];
                int cin = px[row + Math.max(0, Math.min(w - 1, x + r + 1))];
                sa += (cin >>> 24) - (cout >>> 24);
                sr += ((cin >> 16) & 0xFF) - ((cout >> 16) & 0xFF);
                sg += ((cin >> 8) & 0xFF) - ((cout >> 8) & 0xFF);
                sb += (cin & 0xFF) - (cout & 0xFF);
            }
        }
        // 纵向
        for (int x = 0; x < w; x++) {
            long sa = 0, sr = 0, sg = 0, sb = 0;
            for (int i = -r; i <= r; i++) {
                int c = tmp[Math.max(0, Math.min(h - 1, i)) * w + x];
                sa += c >>> 24; sr += (c >> 16) & 0xFF; sg += (c >> 8) & 0xFF; sb += c & 0xFF;
            }
            for (int y = 0; y < h; y++) {
                px[y * w + x] = ((int) (sa / win) << 24) | ((int) (sr / win) << 16) | ((int) (sg / win) << 8) | (int) (sb / win);
                int cout = tmp[Math.max(0, Math.min(h - 1, y - r)) * w + x];
                int cin = tmp[Math.max(0, Math.min(h - 1, y + r + 1)) * w + x];
                sa += (cin >>> 24) - (cout >>> 24);
                sr += ((cin >> 16) & 0xFF) - ((cout >> 16) & 0xFF);
                sg += ((cin >> 8) & 0xFF) - ((cout >> 8) & 0xFF);
                sb += (cin & 0xFF) - (cout & 0xFF);
            }
        }
    }

    // Q105（2.19）：模糊暂存数组跨次复用——旧实现每遍 boxBlurPass 都 new 一块与整带
    // 等大的 int[]（一张带约 37 万像素≈1.5MB），一帧抓图三遍、甩动中约每 500ms 一帧，
    // 主线程上稳定制造 GC 压力。算法与产出像素逐字不变，只换暂存来源（抓图只在主
    // 线程跑，静态复用无并发问题）；px 本身仍每帧新取（位图内容在变，不复用）。
    static int[] blurScratch = null;

    static void stackBlur(Bitmap bmp, int radius) {
        int w = bmp.getWidth(), h = bmp.getHeight();
        if (w <= 0 || h <= 0 || radius < 1) return;
        int[] px = new int[w * h];
        bmp.getPixels(px, 0, w, 0, 0, w, h);
        if (blurScratch == null || blurScratch.length < px.length) blurScratch = new int[px.length];
        boxBlurPass(px, w, h, radius, blurScratch);
        boxBlurPass(px, w, h, radius, blurScratch);
        boxBlurPass(px, w, h, radius, blurScratch);
        bmp.setPixels(px, 0, w, 0, 0, w, h);
    }

    /**
     * 软件背板抓图（preDraw 钩子经 captureBackdropTick 节流调用，亦可由 refreshLiveGlass
     * 清节流强制）：玻璃宿主整面让开后，把根视图以 BACKDROP_SCALE 软件渲染进复用
     * Bitmap 并模糊。Q98：异常不再一击持久关停——noteBackdropFailure 连续 3 次才
     * disableGlassNow；成功即清零计数，瞬时异常下一帧自愈。
     */
    void captureBackdrop() {
        if (backdropCapturing || glassDisabled || helloOpen || rootView == null) return; // Q99：helloOpen 时采样冻结（captureBand 同闸）
        if (rootView.getWidth() <= 0 || rootView.getHeight() <= 0) return;
        long nowMs = android.os.SystemClock.uptimeMillis();
        if (nowMs - backdropLastCapMs < BACKDROP_MIN_INTERVAL_MS) return;
        pruneGlass();
        boolean any = false;
        for (ImageView iv : glassViews) {
            if (iv instanceof GlassBackdropView && iv.isAttachedToWindow() && iv.isShown()) { any = true; break; }
        }
        if (!any) return; // 屏上无玻璃件则零开销：不抓、不占 CPU
        backdropLastCapMs = nowMs;
        int bw = Math.max(1, Math.round(rootView.getWidth() * BACKDROP_SCALE));
        int bh = Math.max(1, Math.round(rootView.getHeight() * BACKDROP_SCALE));
        java.util.Map<View, Integer> saved = new java.util.HashMap<>();
        backdropCapturing = true;
        // Q115（2.28）：抓帧期间暂关当前页滚动条——vivo 系滚动条为白色宽胶囊（带小三角），
        // 滚动停稳/开窗抓帧时它若还醒着会被原样烤进背板，透过玻璃读成面板「内滚条」
        // （23:57 图证，⋯ 菜单开窗两次强制抓帧必中）。同步 draw 一帧内关/恢复，用户无感；
        // 全玻璃件共用此一口（底栏/各窗同沾光）。captureGlassSnapshot 为 Q97 后封存旧链，不动。
        ScrollView capBarSv = bandScroll();
        boolean capBarWas = false;
        if (capBarSv != null) {
            capBarWas = capBarSv.isVerticalScrollBarEnabled();
            if (capBarWas) capBarSv.setVerticalScrollBarEnabled(false);
        }
        try {
            for (ImageView iv : new java.util.ArrayList<>(glassViews)) {
                View h = glassHosts.get(iv);
                View t = h != null ? h : iv;
                if (t != null && t.isAttachedToWindow() && !saved.containsKey(t)) {
                    saved.put(t, t.getVisibility());
                    t.setVisibility(View.INVISIBLE);
                }
            }
            // Q127（2.39，审计 B1）：加载提示层在场时同入隐藏名单——captureBackdrop 是
            // rootView 整树软件绘制，层若不让开会被原样拍进玻璃背板（captureBand 只画
            // 滚动子树、天然拍不到，不另处理）。
            if (homeLoadingLayer != null && homeLoadingLayer.isAttachedToWindow()
                    && !saved.containsKey(homeLoadingLayer)) {
                saved.put(homeLoadingLayer, homeLoadingLayer.getVisibility());
                homeLoadingLayer.setVisibility(View.INVISIBLE);
            }
            if (backdropBmp == null || backdropBmp.isRecycled()
                || backdropBmp.getWidth() != bw || backdropBmp.getHeight() != bh) {
                backdropBmp = Bitmap.createBitmap(bw, bh, Bitmap.Config.ARGB_8888); // 旧图只解引用（Q21）
            }
            Canvas cv = new Canvas(backdropBmp);
            cv.drawColor(colBg()); // Q94：复用位图先整张垫页底色，玻璃宿主让开的空位不留上一帧残像素
            cv.scale(BACKDROP_SCALE, BACKDROP_SCALE);
            rootView.draw(cv); // 软件 Canvas 渲染整树（玻璃宿主已让开，画的是纯场景）
            stackBlur(backdropBmp, BACKDROP_BLUR_R[Math.max(0, Math.min(2, glassLevel))]);
            updateBackdropPaint();
            backdropFailStreak = 0; // Q98：成功一帧即清零失败计数
            noteGlassSuccess();
        } catch (Throwable t) {
            noteBackdropFailure();
        } finally {
            for (java.util.Map.Entry<View, Integer> e : saved.entrySet()) {
                try { e.getKey().setVisibility(e.getValue()); } catch (Throwable ignored) {}
            }
            if (capBarSv != null && capBarWas) { // Q115：与暂关成对恢复
                try { capBarSv.setVerticalScrollBarEnabled(true); } catch (Throwable ignored) {}
            }
            backdropCapturing = false;
        }
        // Q108：结构性抓图点（切页/开窗/设置变更经此或 refreshLiveGlass 至此）同步录
        // 一帧硬件背板——⋯ 菜单开窗瞬间 captureBackdrop 先行、菜单玻璃随后建层首绘，
        // 节点里存的正是开窗前那一帧静止场景（frozen 语义与软件路一致）。
        recordHwBackdrop();
        // 新背板帧落地：让已上屏的玻璃层按新帧重绘（位置对位在各自 onDraw 内按当前坐标算）
        try {
            for (ImageView iv : new java.util.ArrayList<>(glassViews)) {
                if (iv instanceof GlassBackdropView) iv.invalidate();
            }
        } catch (Throwable ignored) {}
    }

    /** 抓当前根视图快照（0.2 降采样）：抓图时把所有已登记玻璃面整面隐藏，避免把玻璃自己拍进背景。 */
    Bitmap captureGlassSnapshot() {
        // Q16 (1) crash kill: full Throwable guard. On some vivo/OEM devices drawing a subtree that carries
        // RenderEffect into a software Canvas throws Error (not Exception), which the old catch missed -> crash.
        // On failure we must also restore host visibility and the glassCapturing flag, else glass layers stay
        // invisible forever. Worst case: keep previous snapshot, or none (tint layer underneath still shows).
        if (rootView == null || !rootView.isAttachedToWindow() || rootView.getWidth() <= 0 || rootView.getHeight() <= 0 || glassCapturing) return glassSnap;
        pruneGlass();
        glassCapturing = true;
        java.util.Map<View, Integer> saved = new java.util.HashMap<>();
        Bitmap out = null;
        try {
            for (ImageView iv : new java.util.ArrayList<>(glassViews)) {
                View h = glassHosts.get(iv);
                View t = h != null ? h : iv;
                if (t != null && t.isAttachedToWindow() && !saved.containsKey(t)) {
                    saved.put(t, t.getVisibility());
                    t.setVisibility(View.INVISIBLE);
                }
            }
            int w = rootView.getWidth(), h = rootView.getHeight();
            float s = 0.20f;
            out = Bitmap.createBitmap(Math.max(1, Math.round(w * s)), Math.max(1, Math.round(h * s)), Bitmap.Config.ARGB_8888);
            Canvas cv = new Canvas(out);
            cv.scale(s, s);
            rootView.draw(cv);
        } catch (Throwable t) {
            out = null; // degrade: keep previous frame; tint underneath still renders
            noteGlassFailure();
        } finally {
            for (java.util.Map.Entry<View, Integer> e : saved.entrySet()) {
                try { e.getKey().setVisibility(e.getValue()); } catch (Throwable ignored) {}
            }
            glassCapturing = false;
        }
        if (out != null) {
            // Q21：换快照只换引用——旧图可能仍被某玻璃层显示列表引用，主动 recycle 即触发黑匣子同签名闪退；0.2 降采样小图交系统回收。
            glassSnap = out;
            glassSnapStale = false; // Q63：新帧已落地，live 层可重新垫图
            noteGlassSuccess();
        }
        return glassSnap;
    }

    /** 把全屏快照按本层在根视图中的位置裁出对应区域（带饱和），API 31+ 再叠硬件模糊。 */
    void applyGlass(final ImageView iv) {
        // Q16 (1): full Throwable guard; any failure clears this layer's image/effect and the tint underneath takes over
        try {
            if (iv == null || rootView == null || !iv.isAttachedToWindow() || glassCapturing) return;
            if (iv instanceof GlassBackdropView) return; // Q90：实时背板层自绘成像，不走快照裁片
            if (iv.getWidth() <= 0 || iv.getHeight() <= 0) {
                Integer r0 = glassRetry.get(iv);
                int rn = r0 == null ? 0 : r0;
                if (rn > 24) return; // never-laid-out glass layer must not spin-post forever (old behaviour)
                glassRetry.put(iv, rn + 1);
                iv.postDelayed(() -> applyGlass(iv), 50);
                return;
            }
            glassRetry.remove(iv);
            // Q63：切页后新帧未落地前，live 层不许把旧页快照再垫回来（那正是旧页文字在新页胶囊/钮位置糊出残影的来源）；
            // 保持已清空的染色兜底，等 refreshLiveGlass 抓到新页定格帧再垫。frozen 浮窗升起时已自抓当前帧，不受此限。
            if (glassSnapStale && "live".equals(iv.getTag())) return;
            if (glassSnap == null || glassSnap.isRecycled()) captureGlassSnapshot();
            Bitmap full = glassSnap;
            if (full == null || full.isRecycled()) return;
            int[] rl = new int[2]; rootView.getLocationOnScreen(rl);
            int[] il = new int[2]; iv.getLocationOnScreen(il);
            int left = il[0] - rl[0], top = il[1] - rl[1];
            int w = iv.getWidth(), h = iv.getHeight();
            if (rootView.getWidth() <= 0) return;
            float s = (float) full.getWidth() / (float) rootView.getWidth();
            Bitmap out = Bitmap.createBitmap(Math.max(1, Math.round(w * s)), Math.max(1, Math.round(h * s)), Bitmap.Config.ARGB_8888);
            Canvas cv = new Canvas(out);
            Paint pt = new Paint(Paint.FILTER_BITMAP_FLAG);
            ColorMatrix cm = new ColorMatrix();
            cm.setSaturation(1.65f); // Q29：1.4→1.65 往混合版 saturate(2) 靠，让身后颜色透进来（彩色毛玻璃不死白）
            pt.setColorFilter(new ColorMatrixColorFilter(cm));
            android.graphics.Matrix m = new android.graphics.Matrix();
            m.setTranslate(-left * s, -top * s);
            cv.drawBitmap(full, m, pt);
            // Q37：live 面换帧交叉淡入 220ms（治用户 20:03 批的停稳硬跳色），不许 setImageBitmap 硬切；
            // frozen 浮窗升起只 apply 一次、沿用直切。Q21 纪律：旧图只解引用不 recycle。
            // Q41：live 面优先走条带画布——停稳这一帧先把条带按当前 scrollY 绘进复用画布，
            // 再交叉淡入到画布帧；滚动期 followBandScroll 只平移重绘同一画布、底色实时跟随。
            Bitmap frameBmp = out;
            if ("live".equals(iv.getTag()) && glassBand != null && bandSv == bandScroll()) {
                if (drawBandFrame(iv)) {
                    Bitmap cb = bandCanvases.get(iv);
                    if (cb != null && !cb.isRecycled()) frameBmp = cb;
                }
            }
            android.graphics.drawable.Drawable prevD = iv.getDrawable();
            boolean prevIsFrame = prevD instanceof android.graphics.drawable.BitmapDrawable
                && ((android.graphics.drawable.BitmapDrawable) prevD).getBitmap() == frameBmp;
            if ("live".equals(iv.getTag()) && prevD != null && !prevIsFrame) {
                android.graphics.drawable.BitmapDrawable nd = new android.graphics.drawable.BitmapDrawable(iv.getResources(), frameBmp);
                android.graphics.drawable.TransitionDrawable td = new android.graphics.drawable.TransitionDrawable(
                    new android.graphics.drawable.Drawable[]{ prevD, nd });
                td.setCrossFadeEnabled(true);
                iv.setImageDrawable(td);
                td.startTransition(220);
            } else if (!prevIsFrame) {
                iv.setImageBitmap(frameBmp);
            }
            glassCrops.put(iv, out); // Q21：旧裁片只解引用不 recycle（黑匣子定案：显示列表在用时 recycle 必崩，见 noteGlassFailure）
            if (Build.VERSION.SDK_INT >= 31) {
                // Q29：模糊 11→13、配合降采样快照呈彩色高斯柔糊；快照本身已 0.2 降采样，半径不许再堆到乳白糊墙，
                // 隔着玻璃要能认出身后卡片的颜色与大致形状（Q16/Q18 的通透红线继续有效）。
                try { iv.setRenderEffect(RenderEffect.createBlurEffect(13f, 13f, Shader.TileMode.CLAMP)); }
                catch (Throwable t) { noteGlassFailure(); }
            }
            noteGlassSuccess();
        } catch (Throwable t) {
            noteGlassFailure();
            try { iv.setImageBitmap(null); if (Build.VERSION.SDK_INT >= 31) iv.setRenderEffect(null); } catch (Throwable ignored) {}
        }
    }

    /**
     * Q63 切页清旧帧：showTab 一进来先执行——live 玻璃层（底栏/悬浮钮/回顶/搜索胶囊）全部
     * 清空图像退回各自的半透染色兜底，旧快照打 stale，条带（Q41）一并作废防 followBandScroll
     * 把旧页条带平移绘回新页；待决的停稳刷新任务摘除，改由 showTab 末尾代次守卫的一次
     * 延迟刷新在新页淡入落定（旧页已摘除）后抓干净新帧。Q21 纪律：只解引用不 recycle。
     */
    void clearLiveGlassForTabSwitch() {
        glassTabGen++;
        glassSnapStale = true;
        glassTabSwitchMs = android.os.SystemClock.uptimeMillis();
        try { mainHandler.removeCallbacks(glassRefreshTask); } catch (Throwable ignored) {}
        glassBand = null; bandSv = null; bandRecalibPending = false; // 旧页条带作废，滚动跟随自然停摆
        bandBmp = null; bandBmpSv = null; // Q99：文档条带同步作废，新页由 refreshLiveGlass 重抓
        for (ImageView iv : new java.util.ArrayList<>(glassViews)) {
            if (!"live".equals(iv.getTag())) continue;
            if (iv instanceof GlassBackdropView) continue; // Q90：背板层下一帧即新页实景，无旧帧可清、更不许清
            try { iv.setImageDrawable(null); } catch (Throwable ignored) {}
        }
    }

    /** Q29：静态帧刷新——只在停稳/切页这两个时刻调用（底栏/悬浮钮/回顶/搜索胶囊共用一帧）；
     *  有浮窗在场时不刷，浮窗用的是各自升起时的冻结快照。 */
    void refreshLiveGlass() {
        // Q97：软件背板——切页/停稳时刻清节流强制重抓一帧新背板；帧间跟随由 preDraw
        // 钩子的节流抓图承担，玻璃件位置对位在各自 onDraw 按当前坐标算。旧快照链
        // （captureGlassSnapshot/applyGlass/条带）仅剩 API<31 时代的登记路径调用，
        // 玻璃件现全是 GlassBackdropView，不再经它成像，代码留仓封存。
        if (detailCard != null) return; // Q118（2.31）：详情窗在场同 captureBackdropTick 闸——650ms 停稳防抖（glassRefreshTask）不许在窗内滚动的停顿间隙整帧重抓，冻结帧用开窗落定那一存档
        if (glassDisabled || rootView == null || rootView.getWidth() <= 0) return;
        backdropLastCapMs = 0;
        captureBackdrop();
        captureBand(); // Q99：结构性时刻条带同步重抓（切页/开关窗/停稳/重渲染）
    }

    void scheduleGlassRefresh() {
        // Q37：滚动事件里绝不抓图——每次事件只重置防抖计时，滚动态势下计时永不跑完即滚动零采样；
        // 静默停稳满 650ms 才补一帧静态毛玻璃（与 Q29 同路线、Q34 的空转已废）。
        // Q21：底栏手势优先——拖动/弹簧期间连排队都免了，避免手势一结束就被积压的抓图任务堵住切页。
        if (navDragging || navSpringRunning) return;
        mainHandler.removeCallbacks(glassRefreshTask);
        mainHandler.postDelayed(glassRefreshTask, 650);
    }

    /** Q127（2.39，审计 A1）：切页/欢迎进入后的玻璃重抓闸门——取代旧 +32/+140（条带）
     * 与 +280ms（全屏）定时抓：等「页面过渡落定＋滚动停稳」才由 refreshLiveGlass
     * 一次抓齐（背板＋条带同一发）。条件：距切页 ≥600ms、近 200ms 无滚动事件、
     * 切页弹簧（tabAnim）已落定、底栏弹簧/拖动不在跑。120ms 一查、代次守卫防连切
     * 抓半路页；4 秒仍未停稳则放弃本轮（滚动停稳另有 650ms 防抖补抓，不永久陈旧）。
     * 玻璃参数、冻结口径（底栏手感/Q21 纪律）一字不动，只挪触发点。 */
    void scheduleSettledGlassCapture() {
        if (rootView == null) return;
        final int gen127 = glassTabGen;
        final long start127 = android.os.SystemClock.uptimeMillis();
        final Runnable[] gate = new Runnable[1];
        gate[0] = () -> {
            if (gen127 != glassTabGen) return;
            long now = android.os.SystemClock.uptimeMillis();
            boolean settled = now - glassTabSwitchMs >= 600
                && now - lastScrollEventMs >= 200
                && tabAnim.task == null
                && !navSpringRunning && !navDragging;
            if (settled) { refreshLiveGlass(); return; }
            if (now - start127 > 4000) return;
            mainHandler.postDelayed(gate[0], 120);
        };
        mainHandler.postDelayed(gate[0], 600);
    }

    // ---------- Q41 条带跟随（底栏玻璃底色滑动实时跟随） ----------
    /** 跟随源：当前页长列表；详情/更新日志覆盖层在场时 chrome 已退场，不跟随。 */
    ScrollView bandScroll() {
        if (detailCard != null || changelogOpen) return null;
        switch (tab) {
            case "mine": return mineScrollView;
            case "student": return studentScroll;
            case "news": return newsScroll;
            case "settings": return settingsScroll;
            default: return homeScroll;
        }
    }

    /**
     * 生成条带快照：把当前页滚动内容在「chrome 带身后文档区 ± 行程裕量」范围内按 0.2 降采样
     * 渲染成一条低清带（高约 420dp，覆盖约 3 倍 dock 高加上下裕量）。只画滚动内容本体，
     * 不含 dock/悬浮钮等 chrome。只在停稳/切页（refreshLiveGlass）与覆盖将尽校准时调用，
     * 滚动跟随期绝不调用。失败即 glassBand=null 回落 Q37。
     */
    void rebuildBand() {
        try {
            if (glassDisabled || rootView == null || rootView.getWidth() <= 0 || rootView.getHeight() <= 0) { glassBand = null; return; }
            ScrollView sv = bandScroll();
            if (sv == null || sv.getChildCount() == 0) { glassBand = null; bandSv = null; return; }
            View inner = sv.getChildAt(0);
            int contentH = inner.getHeight();
            if (contentH <= 0) { glassBand = null; bandSv = null; return; }
            int bandH = Math.min(dp(this, 420), contentH);
            // chrome 带（dock+悬浮钮列）身后的文档行：以屏幕底部上方约 260dp 为带心，上下留行程裕量
            int zoneDocY = sv.getScrollY() + rootView.getHeight() - dp(this, 260);
            int top = Math.max(0, Math.min(zoneDocY - dp(this, 90), Math.max(0, contentH - bandH)));
            int bw = Math.max(1, Math.round(rootView.getWidth() * bandScale));
            int bh = Math.max(1, Math.round(bandH * bandScale));
            Bitmap b = Bitmap.createBitmap(bw, bh, Bitmap.Config.ARGB_8888);
            Canvas cv = new Canvas(b);
            cv.scale(bandScale, bandScale);
            // Q57：画布必须与 drawBandFrame 同一文档坐标系——child 在文档中的原点是
            // (inner.getLeft(), inner.getTop())（含 sv padding 与 child margin 的 layout 结果），
            // inner.draw 自带一层同值 translate，故外层再补 -原点，让文档行 Y 落在画布 (Y-top) 处；
            // 现五页原点均为 0，此校正不改现有行为、只根治换算口径。
            cv.translate(-inner.getLeft(), -top - inner.getTop());
            inner.draw(cv); // 位图设备边界天然裁剪，只画带内行
            glassBand = b; // Q21：旧带只解引用不 recycle
            bandDocTopPx = top;
            bandHeightPx = bandH;
            bandChildLeftPx = inner.getLeft();
            bandInnerH = contentH; // Q57：内容指纹，高度变了（分析卡展开/增删卡）旧带即作废
            bandSv = sv;
            bandLastBuildMs = android.os.SystemClock.uptimeMillis();
        } catch (Throwable t) {
            glassBand = null; bandSv = null; // 回落 Q37 静态帧
        }
    }

    /**
     * 把条带按当前 scrollY 平移绘制进某层 live 玻璃的复用画布（只 Canvas 平移、不触发排版）。
     * 返回 false = 条带已覆盖不到本层（覆盖将尽），调用方决定是否校准。
     */
    boolean drawBandFrame(ImageView iv) {
        try {
            if (iv == null || !iv.isAttachedToWindow() || glassBand == null || glassBand.isRecycled()
                || rootView == null || rootView.getWidth() <= 0) return false;
            ScrollView sv = bandScroll();
            if (sv == null || sv != bandSv) return false;
            int wpx = iv.getWidth(), hpx = iv.getHeight();
            if (wpx <= 0 || hpx <= 0) return false;
            int cw = Math.max(1, Math.round(wpx * bandScale));
            int ch = Math.max(1, Math.round(hpx * bandScale));
            Bitmap cvs = bandCanvases.get(iv);
            if (cvs == null || cvs.isRecycled() || cvs.getWidth() != cw || cvs.getHeight() != ch) {
                cvs = Bitmap.createBitmap(cw, ch, Bitmap.Config.ARGB_8888);
                bandCanvases.put(iv, cvs); // Q21：旧画布只解引用不 recycle
            }
            int[] il = new int[2]; iv.getLocationOnScreen(il);
            int[] sl = new int[2]; sv.getLocationOnScreen(sl);
            // Q57 纵向对位根治：层身后的文档行 = scrollY +（层顶 − ScrollView 顶），旧式少减 svTop——
            // 学生/我的卡片/资讯三页的 sv 不贴根顶（标题区在其上），docTop 系统性偏大 svTop（约 90–300dp），
            // 在 0.2 降采样带内 srcTop 偏大 18–60px 而层高仅约 17px，频繁越界判 exhausted →
            // 滚动中不换帧（冻色）、停稳走 applyGlass 截帧才跳变，与用户「静止才改变+取样错位」双定性吻合。
            // 改以 sv 实时屏幕位为基准逐像素对位，任意页通用；横向同理减 bandChildLeftPx 回到建带坐标系。
            int docTop = sv.getScrollY() + (il[1] - sl[1]);
            int srcTop = Math.round((docTop - bandDocTopPx) * bandScale);
            if (srcTop < 0 || srcTop + ch > Math.round(bandHeightPx * bandScale)) return false; // 覆盖将尽
            int srcLeft = Math.round(((il[0] - sl[0]) - bandChildLeftPx) * bandScale);
            Canvas cv = new Canvas(cvs);
            cv.drawColor(Color.TRANSPARENT, android.graphics.PorterDuff.Mode.CLEAR);
            Paint pt = new Paint(Paint.FILTER_BITMAP_FLAG);
            ColorMatrix cm = new ColorMatrix();
            cm.setSaturation(1.65f); // 与 applyGlass 同口径（往 saturate(2) 靠的彩色毛玻璃）
            pt.setColorFilter(new ColorMatrixColorFilter(cm));
            cv.drawBitmap(glassBand, -srcLeft, -srcTop, pt);
            android.graphics.drawable.Drawable d = iv.getDrawable();
            if (d instanceof android.graphics.drawable.BitmapDrawable
                && ((android.graphics.drawable.BitmapDrawable) d).getBitmap() == cvs) {
                iv.invalidate(); // 同一画布已在显示：只重绘，零 drawable 切换
            } else if (d instanceof android.graphics.drawable.TransitionDrawable) {
                iv.invalidate(); // 停稳交叉淡入进行中：其终帧即本画布，内容已更新，不抢
            } else {
                iv.setImageBitmap(cvs);
            }
            return true;
        } catch (Throwable t) {
            return false; // 跟随坏一帧不许拖死页面；停稳帧仍走 applyGlass
        }
    }

    /** 滚动事件入口：只平移条带绘制，绝不重采样；覆盖将尽时节流排一次校准。 */
    void followBandScroll() {
        if (glassDisabled || glassBand == null || bandSv == null) return;
        if (navDragging || navSpringRunning) return; // Q21：底栏手势优先
        if (isChromeCovered()) return;               // 浮窗在场 chrome 退场，不跟随
        // Q57：内容指纹校验——建带后文档总高变了（我的卡片分析卡展开/收起、自定义卡增删）
        // 旧带内容已过期，继续平移就是「冻旧色」；作废走下方 exhausted 校准（180ms 节流）重建。
        try {
            ScrollView csv = bandScroll();
            if (csv == null || csv != bandSv || csv.getChildCount() == 0
                || csv.getChildAt(0).getHeight() != bandInnerH) {
                triggerBandRecalib();
                return;
            }
        } catch (Throwable ignored) {}
        boolean exhausted = false;
        for (ImageView iv : new java.util.ArrayList<>(glassViews)) {
            if (!"live".equals(iv.getTag())) continue;
            if (!iv.isAttachedToWindow() || iv.getVisibility() != View.VISIBLE) continue;
            View host = glassHosts.get(iv);
            if (host != null && host.getVisibility() != View.VISIBLE) continue;
            if (!drawBandFrame(iv)) exhausted = true;
        }
        if (exhausted) triggerBandRecalib();
    }

    /** Q57：覆盖将尽/内容过期共用一条校准路径（180ms 节流、主线程 post 一次），滚动期绝不逐帧重采样。 */
    void triggerBandRecalib() {
        if (bandRecalibPending
            || android.os.SystemClock.uptimeMillis() - bandLastBuildMs <= 180) return;
        bandRecalibPending = true;
        mainHandler.post(() -> {
            bandRecalibPending = false;
            if (glassDisabled || isChromeCovered() || navDragging || navSpringRunning) return;
            rebuildBand(); // 以当前 scrollY 重新定带
            for (ImageView iv2 : new java.util.ArrayList<>(glassViews)) {
                if ("live".equals(iv2.getTag())) drawBandFrame(iv2);
            }
        });
    }

    // P5 空状态：对照混合版 .empty（居中、灰字、上下 36px 留白），包进白卡（圆角 14）不裸贴页面底
    View emptyState(String s) {
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setBackground(roundRect(colSurface(), 20, this)); // Q94 铺开：空状态卡圆角向 20 档
        box.setPadding(dp(this, 20), dp(this, 32), dp(this, 20), dp(this, 32));
        TextView t = tv(this, s, 13.5f, colText2(), false);
        t.setGravity(android.view.Gravity.CENTER);
        t.setLineSpacing(dp(this, 3), 1f);
        box.addView(t, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        return box;
    }
    // ---------- 显示偏好（字体/界面大小/高刷/触感） ----------
    // Q42 内置清爽黑体：苹方/PingFang 为苹果专有字体不可打包，改内置免费可商用（SIL OFL）
    // Noto Sans SC 可变字体实例化三档（400/500/700）并子集化（GB2312 一级字+卡库/资讯/
    // 更新日志/界面实际用字+常用标点，共 3940 码位，每档约 1.1MB，合计约 3.4MB）。
    // 缺字由安卓字体回落链自动落系统无衬线，不出豆腐块；资产加载失败整段回落系统无衬线。
    // fontMode：builtin=默认（内置 Noto Sans SC）/ system=本机字体 / serif=内置宋体（Q104 新增，
    // 随包子集 Noto Serif SC）/ custom=用户导入（Q55）。Q42 旧注「UI 禁用衬线」自 2.18 起作废：
    // 衬线只以随包子集宋体一档受控出现；更早的旧值 default 一律落 builtin。
    static String fontMode = "builtin";
    static float uiScale = 1f;          // 界面大小：0.9 紧凑 / 1 标准 / 1.12 大号（作用于 sp）
    static int hapticLevel = 2; // P3 触感分档：0 关 / 1 轻(10ms) / 2 中(20ms) / 3 强(40ms)，存 prefs haptic_level（旧 boolean haptic 自动迁移）
    static android.graphics.Typeface sansRegularTf = null, sansMediumTf = null, sansBoldTf = null;
    static boolean sansLoadTried = false;
    // Q104（2.18）内置宋体：Noto Serif SC 子集（与内置黑体同一 3937 码位集，400/700 两档，
    // assets/fonts/serif-regular.ttf + serif-bold.ttf，合计约 3.16MB；来源/子集细节记 PROGRESS Q104）
    static android.graphics.Typeface serifRegularTf = null, serifBoldTf = null;
    static boolean serifLoadTried = false;
    // Q55 自定义字体：用户导入的单文件 .ttf/.otf 存私有目录，字重由系统合成；异常回退链 自定义→软件字体→系统无衬线
    static android.graphics.Typeface customTf = null;
    static boolean customLoadTried = false;
    static String customFontName = "";
    static final int REQ_PICK_FONT = 7711;
    static final long MAX_CUSTOM_FONT_BYTES = 20L * 1024L * 1024L;

    static void ensureSansLoaded(Context c) {
        if (sansLoadTried) return;
        sansLoadTried = true;
        try { sansRegularTf = android.graphics.Typeface.createFromAsset(c.getAssets(), "fonts/sans-regular.ttf"); } catch (Throwable e) { sansRegularTf = null; }
        try { sansMediumTf = android.graphics.Typeface.createFromAsset(c.getAssets(), "fonts/sans-medium.ttf"); } catch (Throwable e) { sansMediumTf = null; }
        try { sansBoldTf = android.graphics.Typeface.createFromAsset(c.getAssets(), "fonts/sans-bold.ttf"); } catch (Throwable e) { sansBoldTf = null; }
    }

    // Q105（2.19）：字重合成结果缓存——旧实现每个 TextView 取字都新建一个 Typeface
    // （create(base, w)），一页列表几百个文本视图、整页重建（切页/换深色/切档）时
    // 逐个新建又逐个弃置。Typeface 不可变、可安全共享，按（基字体身份＋字重＋斜体）
    // 缓存合成结果，产出与逐次新建逐字等价；基字体只有内置三档/宋体/自定义/系统
    // 寥寥数个，缓存天然有界。取字全在主线程，预解码线程不碰字体，普通 HashMap 够用。
    static final java.util.Map<String, android.graphics.Typeface> tfWCache = new java.util.HashMap<>();

    static android.graphics.Typeface tfWeight(android.graphics.Typeface base, int weight) {
        if (base == null) return null;
        int w = Math.max(100, Math.min(1000, weight));
        String k = System.identityHashCode(base) + ":" + w;
        android.graphics.Typeface hit = tfWCache.get(k);
        if (hit != null) return hit;
        android.graphics.Typeface t;
        try { t = android.graphics.Typeface.create(base, w, false); } catch (Throwable e) { t = base; }
        if (t != null) tfWCache.put(k, t);
        return t;
    }

    static android.graphics.Typeface builtinSansTypeface(Context c, int weight) {
        ensureSansLoaded(c);
        android.graphics.Typeface base = weight >= 600 ? sansBoldTf : (weight >= 450 ? sansMediumTf : sansRegularTf);
        if (base == null) base = sansRegularTf != null ? sansRegularTf : android.graphics.Typeface.SANS_SERIF;
        if (android.os.Build.VERSION.SDK_INT >= 28) {
            return tfWeight(base, weight);
        }
        return weight >= 600 ? android.graphics.Typeface.create(base, android.graphics.Typeface.BOLD) : base;
    }

    static void ensureSerifLoaded(Context c) {
        if (serifLoadTried) return;
        serifLoadTried = true;
        try { serifRegularTf = android.graphics.Typeface.createFromAsset(c.getAssets(), "fonts/serif-regular.ttf"); } catch (Throwable e) { serifRegularTf = null; }
        try { serifBoldTf = android.graphics.Typeface.createFromAsset(c.getAssets(), "fonts/serif-bold.ttf"); } catch (Throwable e) { serifBoldTf = null; }
    }

    // Q104（2.18）：内置宋体取字（与 builtinSansTypeface 同构：≥600 走 bold 档、450+ 以 regular 为基
    // 走 API28 字重合成）；资产缺失整段回落内置黑体——不出系统杂牌衬线、不出豆腐字。
    static android.graphics.Typeface serifTypeface(Context c, int weight) {
        ensureSerifLoaded(c);
        android.graphics.Typeface base = weight >= 600 ? serifBoldTf : serifRegularTf;
        if (base == null) base = serifRegularTf != null ? serifRegularTf : serifBoldTf;
        if (base == null) return builtinSansTypeface(c, weight);
        if (android.os.Build.VERSION.SDK_INT >= 28) {
            return tfWeight(base, weight); // Q105：合成结果缓存（同 builtinSansTypeface 口径）
        }
        return weight >= 600 ? android.graphics.Typeface.create(base, android.graphics.Typeface.BOLD) : base;
    }

    static File customFontFile(Context c) {
        File d = new File(c.getFilesDir(), "fonts");
        if (!d.exists()) d.mkdirs();
        return new File(d, "custom-font.dat");
    }

    static File customFontTmpFile(Context c) {
        File d = new File(c.getFilesDir(), "fonts");
        if (!d.exists()) d.mkdirs();
        return new File(d, "custom-font.tmp");
    }

    static boolean hasCustomFont(Context c) {
        try { File f = customFontFile(c); return f.exists() && f.length() > 0; } catch (Throwable e) { return false; }
    }

    static android.graphics.Typeface ensureCustomLoaded(Context c) {
        if (customTf != null) return customTf;
        if (customLoadTried) return null;
        customLoadTried = true;
        try {
            File f = customFontFile(c);
            if (f.exists() && f.length() > 0) customTf = android.graphics.Typeface.createFromFile(f);
        } catch (Throwable e) { customTf = null; }
        return customTf;
    }

    static void resetCustomFontCache() {
        customTf = null; customLoadTried = false;
        // Q125（字体件，研报 A4）：字重合成缓存按基字体身份存键——导入/删除
        // 自定义字体后旧基字体的派生结果不许被新字体误命中，整表一并清。
        // Q128（2.40）：大小归一系数缓存同理清键（文件指纹命键之外再加双保险）。
        fontCompKey128 = ""; fontCompCache128 = -1f;
        try { tfWCache.clear(); } catch (Throwable ignored) {}
    }

    static android.graphics.Typeface customSansTypeface(Context c, int weight) {
        android.graphics.Typeface base = null;
        try { base = ensureCustomLoaded(c); } catch (Throwable ignored) { base = null; }
        if (base == null) return builtinSansTypeface(c, weight); // 回退链：自定义→软件字体（其内部再回落系统无衬线）
        if (android.os.Build.VERSION.SDK_INT >= 28) {
            return tfWeight(base, weight); // Q105：合成结果缓存（同 builtinSansTypeface 口径）
        }
        return weight >= 600 ? android.graphics.Typeface.create(base, android.graphics.Typeface.BOLD) : base;
    }

    // Q39 排字字距/行高口径不变；字形来源按 Q42：软件字体=内置 Noto Sans SC 三档，系统字体=系统无衬线。
    static android.graphics.Typeface weightTypeface(Context c, int weight) {
        if ("serif".equals(fontMode)) return serifTypeface(c, weight); // Q104（2.18）：内置宋体档
        if ("custom".equals(fontMode)) return customSansTypeface(c, weight);
        if (!"system".equals(fontMode)) return builtinSansTypeface(c, weight);
        android.graphics.Typeface base = android.graphics.Typeface.SANS_SERIF;
        if (android.os.Build.VERSION.SDK_INT >= 28) {
            return tfWeight(base, weight); // Q105：合成结果缓存（同 builtinSansTypeface 口径）
        }
        return weight >= 600 ? android.graphics.Typeface.create(base, android.graphics.Typeface.BOLD)
            : android.graphics.Typeface.create(base, android.graphics.Typeface.NORMAL);
    }

    // Q128（2.40，字体大小归一）：参考字墨迹高——同一 Paint 口径（100px 字号）
    // 量一组常用全墨汉字的并集墨迹框高。量墨迹不量行盒：两套内置字体行盒比
    // 几乎同值（研报实测 hhea 1.448/1.437），但墨迹在 em 框里的大小/位置不同，
    // 正是「换宋体字面变大」的来源。参考字取「国人中天大永」——常用全墨汉字，
    // 内置黑/宋子集（同 3937 码位集）内必有；缺字字体量到的是 .notdef 框，
    // 仍为近 em 高、且最终系数有钳幅兜底。
    static float glyphInkH128(android.graphics.Typeface tf) {
        if (tf == null) return 0f;
        try {
            android.graphics.Paint p = new android.graphics.Paint();
            p.setTypeface(tf);
            p.setTextSize(100f);
            String ref = "国人中天大永";
            android.graphics.Rect r = new android.graphics.Rect();
            p.getTextBounds(ref, 0, ref.length(), r);
            return r.height();
        } catch (Throwable e) { return 0f; }
    }

    static float fontCompCache128 = -1f;
    static String fontCompKey128 = "";
    static float builtinInk128 = -1f; // 内置黑体基准墨迹高：字体文件随包恒定，进程内量一次

    // Q128（2.40）：字体大小归一系数＝内置黑体墨迹高 ÷ 当前字体（400 基字）墨迹高。
    // 墨迹偏大的字体系数 <1、字号按比例收，视觉字面拉回与默认一致；反之放大。
    // builtin 档在此字面返回 1.0f、不进量测——默认字体下 tvW 的 setTextSize
    // 入参为 sp*uiScale*1.0f，与改前逐位相同（浮点乘 1.0 为恒等），渲染路径
    // 零变化。系数钳 [0.85, 1.15]：病字体（量测失灵/墨迹极端）最多收放 15%，
    // 不许把字缩没或撑爆。缓存按（fontMode＋custom 文件长/mtime 指纹）命键：
    // 设置切档、导入换文件、删除回退都会自动换键失效，无需在切换点手动清；
    // resetCustomFontCache 另顺手清键双保险。仅主线程构建期调用。
    static float fontComp128(Context c) {
        if (!"system".equals(fontMode) && !"serif".equals(fontMode) && !"custom".equals(fontMode)) return 1.0f;
        String key = fontMode;
        if ("custom".equals(fontMode)) {
            try { java.io.File f = customFontFile(c); key += ":" + f.length() + ":" + f.lastModified(); }
            catch (Throwable ignored) { key += ":?"; }
        }
        if (key.equals(fontCompKey128) && fontCompCache128 > 0) return fontCompCache128;
        if (builtinInk128 <= 0) builtinInk128 = glyphInkH128(builtinSansTypeface(c, 400));
        float cur = glyphInkH128(weightTypeface(c, 400));
        float f = 1.0f;
        if (cur > 0 && builtinInk128 > 0) {
            f = builtinInk128 / cur;
            if (f < 0.85f) f = 0.85f;
            if (f > 1.15f) f = 1.15f;
        }
        fontCompKey128 = key;
        fontCompCache128 = f;
        return f;
    }

    static TextView tv(Context c, String s, float sp, int color, boolean bold) {
        return tvW(c, s, sp, color, bold ? 700 : 400);
    }
    // Q42：输入框/系统按钮等不走 tv() 的文字控件统一挂当前无衬线，禁衬线落点
    void applyUiFont(TextView t, int weight) { try { t.setTypeface(weightTypeface(t.getContext(), weight)); } catch (Throwable ignored) {} }

    // Q125（2.37，字体件，研报 A3）：固定单行件角色行高——底栏标签/按钮/胶囊类
    // 控件高度靠字体自然行盒决定，换字体即跳高漂移。此处按字号 1.45 倍钉死行高
    // （与内置黑体自然行盒比 1.448 等值，定版字体下零变化），并关回退行距，
    // 不许生僻回退字把整行撑变。只钉已定版的固定件，大面积瓷砖/列表本版不动。
    static void pinFixedText125(TextView t) {
        if (t == null) return;
        try {
            if (Build.VERSION.SDK_INT >= 28) {
                t.setFallbackLineSpacing(false);
                float ts125 = t.getTextSize();
                if (ts125 > 0) t.setLineHeight(Math.max(1, Math.round(ts125 * 1.45f)));
            }
        } catch (Throwable ignored) {}
    }

    // Q125（2.37，字体件，研报 A2/五）：输入框角色口径——三处 EditText（主页
    // 搜索/悬浮搜索/customInput 全家）统一：字体走 applyUiFont（hint 与正文共用
    // 同一 TextPaint 天然同度量），includeFontPadding 关（靠控件 padding 呼吸）、
    // 单行行高按字号 1.45 倍钉死、回退行距关、最小高＝上下 padding＋行高。
    // 换字体时框高不跳、hint 与输入后文字基线不打架。
    // 换字体时框高不跳、hint 与输入后文字基线不打架。Q128（2.40）补：三处新建
    // 点都在 setTextSize(15) 之后必经此一处，字号补偿收在这里一并缩放现像素
    // 字号再钉行高，与正文 tvW 同一把尺；默认字体系数恒 1.0、直接跳过不设值。
    void pinInputRole125(EditText e) {
        if (e == null) return;
        try {
            e.setIncludeFontPadding(false);
            e.setGravity(Gravity.CENTER_VERTICAL);
            float comp128 = fontComp128(e.getContext());
            if (comp128 != 1.0f && e.getTextSize() > 0) {
                e.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX, e.getTextSize() * comp128);
            }
            if (Build.VERSION.SDK_INT >= 28) {
                e.setFallbackLineSpacing(false);
                float ts125 = e.getTextSize();
                if (ts125 > 0) {
                    int lh125 = Math.max(1, Math.round(ts125 * 1.45f));
                    e.setLineHeight(lh125);
                    e.setMinHeight(e.getPaddingTop() + e.getPaddingBottom() + lh125);
                }
            }
        } catch (Throwable ignored) {}
    }
    static TextView tvW(Context c, String s, float sp, int color, int weight) {
        // Q106（2.20）：EN 模式下纯展示串走 EN_TXT 精确替换（数据值不在表中、原样直出）
        if (EN_MODE && s != null) { String t = EN_TXT.get(s); if (t != null) s = t; }
        TextView t = new TextView(c);
        // Q128（2.40）：字号在工厂一处套字体大小归一系数（fontComp128）；默认
        // 内置黑体系数恒 1.0f，此入参逐位等于改前的 sp * uiScale。
        t.setText(s); t.setTextSize(sp * uiScale * fontComp128(c)); t.setTextColor(color);
        t.setTypeface(weightTypeface(c, weight));
        t.setIncludeFontPadding(false);
        return t;
    }
    // 正文行高：混合版 body line-height 1.5；原生多行正文统一走此助手，不在单行标签上套
    static void bodyLH(TextView t) {
        t.setLineSpacing(0, 1.45f);
        // Q125（2.37，字体件，研报 A5）：正文显式开回退行距——含生僻字/回退字
        // 的行按回退字体度量撑高，不与上下行叠字；行高倍率口径本版不动。
        if (Build.VERSION.SDK_INT >= 28) { try { t.setFallbackLineSpacing(true); } catch (Throwable ignored) {} }
    }
    // Q124（2.36，件十八）：组织未知判定与归一一处收口——数据里 org 为 JSON null 时
    // Android optString 会吐字符串 "null"（长城校园借记IC卡详情副标/tag 实证），另有
    // 字面「待核实」两张。显示层一律「无卡组织」，数据文件本身不改、不编造。
    static String normOrg124(String s) {
        if (s == null) return "";
        s = s.trim();
        if (s.isEmpty() || "null".equalsIgnoreCase(s) || "待核实".equals(s)) return "";
        return s;
    }
    static boolean orgUnknown124(String s) { return normOrg124(s).isEmpty(); }

    static String orgLabel(String org) {
        if (org == null || org.isEmpty() || "null".equalsIgnoreCase(org.trim()) || "待核实".equals(org.trim()) || "__none__".equals(org))
            return EN_MODE ? "No Network" : "无卡组织"; // Q124（件十八）：未知组织统一标记，禁再出「null」
        switch (org) {
            case "visa": return "VISA";
            case "mastercard": return "万事达";
            case "mastercard-nucc": return "万事达-网联";
            case "amex-cn": return "运通-人民币";
            case "unionpay": return "银联";
            case "jcb": return "JCB";
            default: return org;
        }
    }

    // Q125（2.37，审计一类收口）：JSONObject.optString 对「键在但值为 JSON null」
    // 返回字面字符串 "null"，满仓 == null 守卫对它无效。所有数据解析边界统一过
    // 此归一（字面 null→空串），显示层不再逐处判空。与 normOrg124 分工：org 走
    // org 专用口径（另含「待核实」），其余字符串字段一律走此一处。
    static String nz125(String s) {
        if (s == null) return "";
        return "null".equalsIgnoreCase(s.trim()) ? "" : s;
    }

    // ---------- 数据模型 ----------
    static class Card {
        String id, name, bank, org, type, status, review, image, keywords, url;
        double score;
        String scoreLabel;
        JSONObject specs;
        JSONArray variants;
        boolean hasScore;
        boolean studentPick;
        int studentOrder;
        String studentReason;
        // Q67：数据线下发的逐维度分项分（score_dims）。只读展示，不在端上按权重重算。
        java.util.LinkedHashMap<String, Double> scoreDims = new java.util.LinkedHashMap<>();
        Double scoreDim(String dim) { return scoreDims.get(dim); }
        String spec(String key) {
            if (specs == null) return "";
            return nz125(specs.optString(key, "")); // Q125：spec 值 JSON null 归一（审计一类 8，全消费方受益）
        }
        boolean isCredit() { return "credit".equals(type); }
        // Q89：未核实判定（纯数据驱动）——org 空/待核实，或 specs 任一字段值恰为「待核实」；
        // variants_note 等散文字样不算。核实后字段落值，标记随之自动消失，不落本机状态。
        boolean hasUnverified() {
            if (org == null || org.isEmpty() || "待核实".equals(org)) return true;
            if (specs != null) {
                java.util.Iterator<String> ks = specs.keys();
                while (ks.hasNext()) {
                    if ("待核实".equals(specs.optString(ks.next(), ""))) return true;
                }
            }
            return false;
        }
    }

    static class Store {
        static List<Card> all = new ArrayList<>();
        static Map<String, Card> byId = new HashMap<>();
        static int dataVersion = 0;
        // Q105（2.19）：包内资产自带数据的版本（与 dataVersion=当前生效数据版本分开记）——
        // 生效版本高于它时说明在跑 OTA 新数据，同名卡图应优先远程新图（Img.preferRemote），
        // 否则包内旧图会永久压住远端新图（v37 旋转新图真机仍旧图即此病）。只在 load() 里
        // 由资产 JSON 自身版本落定，OTA 应用不改它（资产不可变）。
        static int bundledVersion = -1;

        static String readAll(InputStream in) throws Exception {
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            byte[] buf = new byte[8192]; int n;
            while ((n = in.read(buf)) > 0) bos.write(buf, 0, n);
            in.close();
            return new String(bos.toByteArray(), "UTF-8");
        }

        static java.util.LinkedHashMap<String, Double> parseScoreDims(JSONObject o) {
            java.util.LinkedHashMap<String, Double> out = new java.util.LinkedHashMap<>();
            if (o == null) return out;
            try {
                JSONArray names = o.names();
                if (names == null) return out;
                for (int i = 0; i < names.length(); i++) {
                    String k = names.optString(i, "");
                    if (k.isEmpty() || o.isNull(k)) continue;
                    Object v = o.opt(k);
                    if (v instanceof Number) out.put(k, ((Number) v).doubleValue());
                }
            } catch (Exception ignored) { }
            return out;
        }

        // 解析一整份 cards.json 成功返回 true，并替换当前数据（先解到临时表，成功才换，避免半截数据）
        static boolean parseInto(String json) {
            try {
                JSONObject root = new JSONObject(json);
                JSONArray arr = root.getJSONArray("cards");
                if (arr == null || arr.length() == 0) return false;
                List<Card> tmp = new ArrayList<>();
                Map<String, Card> tmpBy = new HashMap<>();
                for (int i = 0; i < arr.length(); i++) {
                    JSONObject o = arr.getJSONObject(i);
                    Card cd = new Card();
                    // Q125：除 org（normOrg124 专用）外全字段过 nz125 归一，字面 "null" 不许进模型（审计一类 1）
                    cd.id = nz125(o.optString("id")); cd.name = nz125(o.optString("name"));
                    cd.bank = nz125(o.optString("bank")); cd.org = normOrg124(o.optString("org")); // Q124（件十八）
                    cd.type = nz125(o.optString("type", "debit")); cd.status = nz125(o.optString("status"));
                    cd.review = nz125(o.optString("review")); cd.image = nz125(o.optString("image"));
                    cd.keywords = nz125(o.optString("keywords")); cd.url = nz125(o.optString("url"));
                    cd.score = o.optDouble("score", 0); cd.hasScore = o.has("score") && !o.isNull("score"); cd.scoreLabel = nz125(o.optString("score_label"));
                    cd.scoreDims = parseScoreDims(o.optJSONObject("score_dims"));
                    cd.specs = o.optJSONObject("specs");
                    cd.variants = o.optJSONArray("variants");
                    JSONObject sp = o.optJSONObject("student_pick");
                    cd.studentPick = sp != null;
                    cd.studentOrder = sp != null ? sp.optInt("order", 999) : 999;
                    cd.studentReason = sp != null ? nz125(sp.optString("reason", "")) : "";
                    tmp.add(cd); tmpBy.put(cd.id, cd);
                }
                all = tmp; byId = tmpBy;
                dataVersion = root.optInt("data_version", dataVersion);
                return true;
            } catch (Exception e) { return false; }
        }

        static int versionOf(String json) {
            try { return new JSONObject(json).optInt("data_version", 0); } catch (Exception e) { return 0; }
        }

        static void load(Context c) {
            if (!all.isEmpty()) return;
            String assetJson = null;
            try { assetJson = readAll(c.getAssets().open("data/cards.json")); } catch (Exception e) { /* 读不到走空 */ }
            if (assetJson != null) bundledVersion = versionOf(assetJson); // Q105：包内资产版本落定（Img 取源优先级依据）
            // OTA 文件（filesDir/cards-ota.json）比内置新才优先用它（对照混合版 boot 的 OTA 优先逻辑）
            String otaJson = null;
            try {
                File f = new File(c.getFilesDir(), "cards-ota.json");
                if (f.exists()) otaJson = readAll(new FileInputStream(f));
            } catch (Exception e) { otaJson = null; }
            // Q98 双保险：OTA 文件只有「经确认窗应用成功后落下的标记 ota_applied_version 与文件
            // 版本一致」才认——系统备份/克隆把文件单独带回新装时标记对不上，一律回落包内资产，
            // 绝不再出现「一打开就是远端新版、没经过确认」。标记只由 applyPendingUpdate 在写入
            // 成功后落盘；老版本经确认更新过的机器首次跑本版会回落资产并重新走一次确认窗。
            int otaVer = otaJson == null ? -1 : versionOf(otaJson);
            int appliedVer = -1;
            try { appliedVer = c.getSharedPreferences("cardbox_native", Context.MODE_PRIVATE).getInt("ota_applied_version", -1); } catch (Exception e) { appliedVer = -1; }
            boolean otaConfirmed = otaJson != null && otaVer > 0 && otaVer == appliedVer;
            if (otaConfirmed && assetJson != null && otaVer > versionOf(assetJson)) {
                if (parseInto(otaJson)) return;
            }
            if (assetJson != null) parseInto(assetJson);
            if (all.isEmpty() && otaConfirmed) parseInto(otaJson);
        }
    }

    static class Img {
        // Q127（2.39，审计 A2）：LruCache 非线程安全——解码池扩到 2 线程后所有
        // cache 读写一律经 cacheGet/cachePut 在 cache 对象上同步，防并发 put/get
        // 撞坏链表；同步只锁缓存本身，解码不进锁，并发重复解码同键无害（产出同图）。
        static LruCache<String, Bitmap> cache = new LruCache<String, Bitmap>(48 * 1024) {
            protected int sizeOf(String k, Bitmap b) { return b.getByteCount() / 1024; }
        };
        static Bitmap cacheGet(String k) { synchronized (cache) { return cache.get(k); } }
        static void cachePut(String k, Bitmap b) { synchronized (cache) { cache.put(k, b); } }
        static final java.util.Set<String> fetching = new java.util.HashSet<>();

        static Bitmap decode(InputStream in) {
            BitmapFactory.Options op = new BitmapFactory.Options();
            op.inSampleSize = 2;
            Bitmap b = BitmapFactory.decodeStream(in, null, op);
            try { in.close(); } catch (Exception e) {}
            return insetFaceCrop(b);
        }

        // Q93：卡面图黑边治理（用户 15:14 定法「把图片放大，填充四个角」，有图处全改）。
        // Img.get/decode 是全 App 真实卡面图的唯一解码收口——瓷砖/详情英雄/学生/选卡/展柜双模式/我的卡片
        // 全部经此，故只在此处把源图四边各内收 2.5%（等比内裁、宽高比不变），各显示处再以 CENTER_CROP/
        // 圆角框放大铺满，源图自带黑尖/细黑框即被吃掉；占位面是程序绘制无源图，不走这里。
        // 注意：不 recycle 原图（Q21 铁律，缓存与磨砂裁片共用同一位图引用）；裁切失败回落原图不冒崩点。
        // 个别粗黑框图内裁后仍有残留的，只记录卡 id 回报，不在此逐张改数据图。
        static Bitmap insetFaceCrop(Bitmap b) {
            if (b == null) return null;
            try {
                int w = b.getWidth(), h = b.getHeight();
                if (w < 24 || h < 24) return b;
                float frac = 0.025f;
                // Q124（2.36，件十五）：资产实测——301 张源图里仅 czb-shihua 一张自带
                // 纯黑框（772×494，四边约 12–14px），其余「黑边」多为深色卡面本身；
                // 显示层为 CENTER_CROP＋透明框，不垫黑。故只对「外圈近纯黑且低方差、
                // 内圈（9% 处）明显更亮」的真黑框图加深内裁到 5.5%，深色卡面（内圈
                // 同样暗）不触发，不动任何资产原图。采样约百点，开销可忽略。
                if (hasBakedDarkFrame124(b, w, h)) frac = 0.055f;
                int ix = Math.max(1, Math.round(w * frac));
                int iy = Math.max(1, Math.round(h * frac));
                if (w - 2 * ix < 8 || h - 2 * iy < 8) return b;
                Bitmap c = Bitmap.createBitmap(b, ix, iy, w - 2 * ix, h - 2 * iy);
                return c != null ? c : b;
            } catch (Throwable t) { return b; }
        }

        static boolean hasBakedDarkFrame124(Bitmap b, int w, int h) {
            try {
                int inset = Math.max(2, Math.round(Math.min(w, h) * 0.09f));
                long sumO = 0, sumI = 0; int nO = 0, nI = 0;
                long sqO = 0;
                int step = Math.max(1, Math.min(w, h) / 48);
                for (int x = 0; x < w; x += step) {
                    int[] ysO = {0, h - 1}; int[] ysI = {inset, h - 1 - inset};
                    for (int y : ysO) { int p = b.getPixel(x, y); int v = (Color.red(p) + Color.green(p) + Color.blue(p)) / 3; sumO += v; sqO += (long) v * v; nO++; }
                    for (int y : ysI) { int p = b.getPixel(x, y); int v = (Color.red(p) + Color.green(p) + Color.blue(p)) / 3; sumI += v; nI++; }
                }
                for (int y = 0; y < h; y += step) {
                    int[] xsO = {0, w - 1}; int[] xsI = {inset, w - 1 - inset};
                    for (int x : xsO) { int p = b.getPixel(x, y); int v = (Color.red(p) + Color.green(p) + Color.blue(p)) / 3; sumO += v; sqO += (long) v * v; nO++; }
                    for (int x : xsI) { int p = b.getPixel(x, y); int v = (Color.red(p) + Color.green(p) + Color.blue(p)) / 3; sumI += v; nI++; }
                }
                if (nO == 0 || nI == 0) return false;
                double meanO = sumO / (double) nO, meanI = sumI / (double) nI;
                double sdO = Math.sqrt(Math.max(0, sqO / (double) nO - meanO * meanO));
                return meanO < 38 && sdO < 26 && (meanI - meanO) > 42;
            } catch (Throwable t) { return false; }
        }

        static File remoteCacheDir(Context c) {
            // OTA 图片按数据版本分目录：同名图片内容更新时，新版本会落到新目录，
            // 不会让 filesDir 里按文件名留存的旧图永久顶住新图。旧目录只是下载缓存，
            // 不含收藏、自定义卡等用户数据，未命中时按需重新下载。
            int v = Store.dataVersion;
            return new File(new File(c.getFilesDir(), "ota-images"), "v" + Math.max(0, v));
        }

        // Q105（2.19）取源优先级修正：旧实现无条件资产优先——包里有的图永远用包里的，
        // OTA 数据升版后同名新图（v37 的 15 张旋转填满）被旧合成图永久压住，用户更新了
        // 数据真机仍看旧图。改：生效数据版本高于包内资产版本时，远程（版本化缓存目录）
        // 优先；远程文件还没下到时先用包内图顶着（不入缓存，落盘后下次构建自动接管），
        // 两源都解码失败才回占位。2.15 的版本化目录（remoteCacheDir 按 dataVersion 分）
        // 原样保留，磁盘口径零变化；数据应用成功时另由 applyPendingUpdate 清内存缓存，
        // 保证同进程内更新即刻换图。
        static boolean preferRemote() {
            return Store.bundledVersion >= 0 && Store.dataVersion > Store.bundledVersion;
        }

        static boolean remoteFileExists(Context c, String path) {
            try { return new File(remoteCacheDir(c), new File(path).getName()).exists(); }
            catch (Exception e) { return false; }
        }

        /** 按取源优先级开一条图流：remoteFirst 时远程文件优先（缺失触发后台拉取后回落资产），
         *  否则资产优先（缺失回落远程文件，再缺失触发拉取并抛异常让调用方回占位）。 */
        static InputStream openImageStream(Context c, String path, boolean remoteFirst) throws Exception {
            File f = new File(remoteCacheDir(c), new File(path).getName());
            if (remoteFirst) {
                if (f.exists()) return new FileInputStream(f);
                fetchRemote(c.getApplicationContext(), path, f);
                return c.getAssets().open(path);
            }
            try { return c.getAssets().open(path); }
            catch (Exception e) {
                if (f.exists()) return new FileInputStream(f);
                fetchRemote(c.getApplicationContext(), path, f);
                throw e;
            }
        }

        static int bucketFor(int targetW) { return Math.max(64, (targetW + 63) / 64 * 64); }

        static Bitmap get(Context c, String path) {
            if (path == null || path.isEmpty()) return null;
            Bitmap hit = cacheGet(path);
            if (hit != null) return hit;
            boolean remoteFirst = preferRemote();
            // 远程优先但新图未落盘时包内图只是过渡帧，不入缓存——免得刚下到的新图被它顶住
            boolean provisional = remoteFirst && !remoteFileExists(c, path);
            Bitmap b = null;
            try { b = decode(openImageStream(c, path, remoteFirst)); } catch (Exception e) { /* 换另一源再试 */ }
            if (b == null) {
                try { b = decode(openImageStream(c, path, !remoteFirst)); } catch (Exception e) { /* 拿不到图就占位，不崩 */ }
            }
            if (b != null) { if (!provisional) cachePut(path, b); return b; }
            return null;
        }

        // Q99：按显示尺寸解码——先探边界算采样率，解码结果落在目标宽最近的一档（2 的幂），
        // 缓存键带尺寸桶，不同列数瓷砖各取所需；详情大图/展柜仍走 get() 全量解码。
        // Q105（2.19）：解码端再叠密度缩放——2 的幂采样后仍可达近 2 倍桶宽（如 2160 源在
        // 576 桶下采样到 1080），像素数约 4 倍于显示所需，列表构建逐张在主线程白付这笔
        // 解码/上传/合成。用 inDensity/inTargetDensity 让解码器在解码期就缩到桶宽，产出
        // 像素与旧实现同构图、同裁切（insetFaceCrop 照旧），个别机型忽略密度缩放时自然
        // 回落采样结果（旧行为）。取源走 openImageStream（远程优先口径同 get()）。
        static Bitmap getSized(Context c, String path, int targetW) {
            if (path == null || path.isEmpty() || targetW <= 0) return get(c, path);
            int bucket = bucketFor(targetW);
            String key = path + "@" + bucket;
            Bitmap hit = cacheGet(key);
            if (hit != null) return hit;
            boolean remoteFirst = preferRemote();
            boolean provisional = remoteFirst && !remoteFileExists(c, path);
            Bitmap b = decodeSized(c, path, bucket, remoteFirst);
            if (b == null) b = decodeSized(c, path, bucket, !remoteFirst); // 主源解码失败换另一源（旧版双源兜底同语义）
            if (b != null) { if (!provisional) cachePut(key, b); return b; }
            return null;
        }

        static Bitmap decodeSized(Context c, String path, int bucket, boolean remoteFirst) {
            Bitmap b = null;
            try {
                BitmapFactory.Options bo = new BitmapFactory.Options();
                bo.inJustDecodeBounds = true;
                InputStream probe = openImageStream(c, path, remoteFirst);
                BitmapFactory.decodeStream(probe, null, bo);
                try { probe.close(); } catch (Exception ignored) {}
                if (bo.outWidth <= 0) return null;
                int ss = 1;
                while (ss < 16 && bo.outWidth / (ss * 2) >= bucket) ss *= 2;
                int sampledW = Math.max(1, bo.outWidth / ss);
                BitmapFactory.Options op = new BitmapFactory.Options();
                op.inSampleSize = ss;
                if (sampledW > bucket) { // Q105：解码期缩到桶宽（源宽恒 ≥ 显示宽，桶已向上取整到 64）
                    op.inScaled = true;
                    op.inDensity = sampledW;
                    op.inTargetDensity = bucket;
                }
                InputStream in2 = openImageStream(c, path, remoteFirst);
                b = BitmapFactory.decodeStream(in2, null, op);
                try { in2.close(); } catch (Exception ignored) {}
            } catch (Exception e) { /* 解码失败回落占位 */ }
            return insetFaceCrop(b);
        }

        // Q105（2.19）：后台预解码——分帧构建列表时，下一帧的卡图先在单线程后台解进
        // 同一 LruCache（同键同桶同产出），构建到那帧时直接命中，主线程不再逐张付解码。
        // 只提前不改产出：图还是同一张图、同一桶位；预解码没赶上时构建照旧同步解码。
        // Q127（2.39，审计 A2）：解码池 1→2 线程（cache 读写已同步，见 cacheGet/
        // cachePut）；预热领先深度在 addCardRowsChunked 改 3 帧（原领先 1 帧）。
        static final java.util.concurrent.ExecutorService decodePool =
            java.util.concurrent.Executors.newFixedThreadPool(2, r -> {
                Thread t = new Thread(r, "cardimg-decode");
                t.setDaemon(true);
                return t;
            });
        static final java.util.Set<String> decodeBusy = java.util.Collections.synchronizedSet(new java.util.HashSet<>());

        static void prefetchSized(final Context c, final String path, final int targetW) {
            if (path == null || path.isEmpty() || targetW <= 0) return;
            final String key = path + "@" + bucketFor(targetW);
            if (cacheGet(key) != null) return;
            if (!decodeBusy.add(key)) return;
            final Context app = c.getApplicationContext();
            try {
                decodePool.execute(() -> {
                    try { getSized(app, path, targetW); } catch (Throwable ignored) { /* 预热失败构建时同步解码兜底 */ }
                    finally { decodeBusy.remove(key); }
                });
            } catch (Throwable t) { decodeBusy.remove(key); }
        }

        static void fetchRemote(final Context ctx, final String path, final File dest) {
            synchronized (fetching) { if (!fetching.add(path)) return; }
            new Thread(() -> {
                try {
                    String name = new File(path).getName();
                    HttpURLConnection conn = (HttpURLConnection) new URL("https://cdn.jsdelivr.net/gh/dimlogue/cardbox-data@main/images/" + name + "?v=" + Math.max(0, Store.dataVersion)).openConnection();
                    conn.setConnectTimeout(8000); conn.setReadTimeout(8000);
                    if (conn.getResponseCode() == 200) {
                        dest.getParentFile().mkdirs();
                        FileOutputStream fos = new FileOutputStream(dest);
                        InputStream in = conn.getInputStream();
                        byte[] buf = new byte[8192]; int n;
                        while ((n = in.read(buf)) > 0) fos.write(buf, 0, n);
                        in.close(); fos.close();
                    }
                    conn.disconnect();
                } catch (Exception e) { /* 断网就下次再试 */ }
                synchronized (fetching) { fetching.remove(path); }
            }).start();
        }
    }

    // ---------- Q132（2.44）外卡专区：独立数据集（assets/data/foreign.json＋data/foreign/ 图），
    // 与核心 cards.json 完全分开——不进 Store、不进主搜索、核心卡数口径不变。条目带核实状态
    // （core_verified=核心核实，其余＝待核），评分模型未定一律不出分；图缺走 Q70 占位面，
    // 不许编造图。数据由 foreign-seed-02.json 生成，字段口径见方向稿。 ----------
    static class FxCard {
        String id, name, nameEn, bank, org, type, level, status, review, url, image, tier;
        String verifyStatus, verifiedAt;
        JSONObject specs;
        java.util.List<String> keywords = new ArrayList<>();
        java.util.List<String> aliases = new ArrayList<>();
        java.util.List<String> missing = new ArrayList<>();
        boolean coreVerified() { return "core_verified".equals(verifyStatus); }
        String orgLabel() {
            if ("visa".equals(org)) return "Visa";
            if ("mastercard".equals(org)) return "Mastercard";
            if ("unionpay".equals(org)) return "UnionPay";
            if ("amex".equals(org)) return "Amex";
            if ("jcb".equals(org)) return "JCB";
            return "组织待核";
        }
        String typeLabel() { return "credit".equals(type) ? "信用卡" : "扣账卡"; }
        String verifyLabel() {
            if (coreVerified()) return "核心核实";
            if ("variant_split_required".equals(verifyStatus)) return "待核 · 系列待拆";
            if ("official_conflict_hold".equals(verifyStatus)) return "待核 · 口径待消解";
            return "待核";
        }
    }

    static class FxStore {
        static java.util.List<FxCard> all = null;
        static void load(Context c) {
            if (all != null) return;
            all = new ArrayList<>();
            try {
                JSONObject root = new JSONObject(Store.readAll(c.getAssets().open("data/foreign.json")));
                JSONArray arr = root.getJSONArray("cards");
                for (int i = 0; i < arr.length(); i++) {
                    JSONObject o = arr.getJSONObject(i);
                    FxCard f = new FxCard();
                    f.id = nz125(o.optString("id")); f.name = nz125(o.optString("name"));
                    f.nameEn = nz125(o.optString("name_en")); f.bank = nz125(o.optString("bank"));
                    f.org = nz125(o.optString("org")); f.type = nz125(o.optString("type", "debit"));
                    f.level = nz125(o.optString("card_level")); f.status = nz125(o.optString("status"));
                    f.review = nz125(o.optString("review")); f.url = nz125(o.optString("url"));
                    f.image = nz125(o.optString("image")); f.tier = nz125(o.optString("priority_tier"));
                    JSONObject v = o.optJSONObject("verification");
                    f.verifyStatus = v == null ? "" : nz125(v.optString("status"));
                    f.verifiedAt = v == null ? "" : nz125(v.optString("verified_at"));
                    if (v != null) {
                        JSONArray mf = v.optJSONArray("missing_fields");
                        if (mf != null) for (int j = 0; j < mf.length(); j++) f.missing.add(mf.optString(j));
                    }
                    JSONArray kw = o.optJSONArray("keywords");
                    if (kw != null) for (int j = 0; j < kw.length(); j++) f.keywords.add(kw.optString(j));
                    JSONArray al = o.optJSONArray("aliases");
                    if (al != null) for (int j = 0; j < al.length(); j++) f.aliases.add(al.optString(j));
                    f.specs = o.optJSONObject("specs");
                    all.add(f);
                }
            } catch (Exception e) { /* 读不到走空列表，专区页会如实提示 */ }
        }
    }

    // 待核字段键 → 展示名（只译已知键，未知原样透出不编造）
    static String fxMissingLabel(String k) {
        if ("org".equals(k)) return "卡组织";
        if ("annual_fee_hkd".equals(k)) return "年费金额";
        if ("annual_fee_status".equals(k)) return "年费状态";
        if ("supplementary_annual_fee_hkd".equals(k)) return "附属卡年费";
        if ("foreign_transaction_fee_pct".equals(k)) return "外币手续费率";
        if ("fx_fee_scope".equals(k)) return "手续费适用范围";
        if ("card_level".equals(k)) return "卡等级";
        if ("eligibility".equals(k)) return "申请资格";
        if ("min_income_hkd".equals(k)) return "年薪门槛";
        if ("supported_currency_codes".equals(k)) return "支持币种";
        if ("overseas_atm_fee".equals(k)) return "海外 ATM 费";
        if ("residency_status".equals(k)) return "居民资格";
        return k;
    }

    boolean fxZoneOpen = false, fxDetailOpen = false;
    String fxQuery = "";
    boolean fxCoreOnly = false;
    int fxZoneKeepY = 0;
    ScrollView fxZoneScroll = null;
    LinearLayout fxListBox = null;
    TextView fxCountTv = null;

    boolean fxzoneEnabled() { return prefs == null || prefs.getBoolean("fxzone_enabled", true); }

    void openFxZone() {
        captureCurrentPageScroll();
        FxStore.load(this);
        fxZoneOpen = true;
        if (navWrap != null) navWrap.setVisibility(View.GONE); // 同整页口径：藏整条 dock
        if (fullScreenPage != null && fullScreenPage.getParent() == content) content.removeView(fullScreenPage);
        if (pageHost != null) pageHost.setVisibility(View.GONE);
        fullScreenPage = buildFxZonePage();
        content.addView(fullScreenPage);
        syncTopFab();
    }

    void closeFxZone() {
        fxZoneOpen = false;
        fxZoneScroll = null; fxListBox = null; fxCountTv = null;
        if (navWrap != null) navWrap.setVisibility(View.VISIBLE); // Q32
        showTab(tab);
    }

    View buildFxZonePage() {
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        root.setBackground(softPageBg());
        root.addView(pageBackHead("外卡专区", () -> { haptic(); closeFxZone(); }),
            new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        TextView intro = tv(this, "首批香港银行卡 · 独立数据，不混入主卡库搜索", 11.5f, colText2(), false);
        intro.setPadding(dp(this, 16), dp(this, 2), dp(this, 16), 0);
        root.addView(intro);

        // 搜索行（与首页搜索同一语言：柔面胶囊＋细线放大镜＋无底输入）
        LinearLayout searchRow = new LinearLayout(this);
        searchRow.setOrientation(LinearLayout.HORIZONTAL);
        searchRow.setGravity(Gravity.CENTER_VERTICAL);
        searchRow.setBackground(roundRect(colSurface(), 999, this));
        searchRow.setPadding(dp(this, 12), dp(this, 2), dp(this, 12), dp(this, 2));
        LinearLayout.LayoutParams srlp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        srlp.leftMargin = dp(this, 16); srlp.rightMargin = dp(this, 16); srlp.topMargin = dp(this, 10);
        root.addView(searchRow, srlp);
        SearchIconView sicon = new SearchIconView(this);
        sicon.iconColor = colText2();
        searchRow.addView(sicon, new LinearLayout.LayoutParams(dp(this, 18), dp(this, 18)));
        final EditText fxBox = new EditText(this);
        applyUiFont(fxBox, 400);
        fxBox.setHint("搜卡名 / 银行，如：汇丰、Mox、渣打");
        fxBox.setTextSize(14);
        fxBox.setSingleLine(true);
        fxBox.setBackground(null);
        fxBox.setTextColor(colText()); fxBox.setHintTextColor(colText2());
        fxBox.setShadowLayer(0, 0, 0, 0);
        fxBox.setPadding(dp(this, 8), dp(this, 8), dp(this, 4), dp(this, 8));
        pinInputRole125(fxBox);
        if (fxQuery != null && !fxQuery.isEmpty()) fxBox.setText(fxQuery);
        fxBox.addTextChangedListener(new TextWatcher() {
            public void beforeTextChanged(CharSequence t, int a, int b, int c) {}
            public void onTextChanged(CharSequence t, int a, int b, int c) {
                fxQuery = t.toString();
                renderFxList();
            }
            public void afterTextChanged(Editable t) {}
        });
        searchRow.addView(fxBox, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f));

        // 筛选行：只看核心核实开关胶囊＋计数
        LinearLayout chipRow = new LinearLayout(this);
        chipRow.setOrientation(LinearLayout.HORIZONTAL);
        chipRow.setGravity(Gravity.CENTER_VERTICAL);
        chipRow.setPadding(dp(this, 16), dp(this, 10), dp(this, 16), dp(this, 2));
        root.addView(chipRow);
        final TextView coreChip = chip("只看核心核实",
            fxCoreOnly ? accentColor() : (darkEff() ? Color.rgb(0x2E, 0x2E, 0x33) : Color.rgb(0xEF, 0xF1, 0xF6)),
            fxCoreOnly ? Color.WHITE : colText(), 11.5f);
        coreChip.setOnClickListener(v -> {
            haptic();
            fxCoreOnly = !fxCoreOnly;
            coreChip.setBackground(roundRect(fxCoreOnly ? accentColor() : (darkEff() ? Color.rgb(0x2E, 0x2E, 0x33) : Color.rgb(0xEF, 0xF1, 0xF6)), 999, this));
            coreChip.setTextColor(fxCoreOnly ? Color.WHITE : colText());
            renderFxList();
        });
        chipRow.addView(coreChip);
        fxCountTv = tv(this, "", 11.5f, colText2(), false);
        LinearLayout.LayoutParams ctlp = new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f);
        ctlp.leftMargin = dp(this, 10);
        chipRow.addView(fxCountTv, ctlp);

        fxZoneScroll = new ScrollView(this);
        thinScrollbar(fxZoneScroll);
        fxListBox = new LinearLayout(this);
        fxListBox.setOrientation(LinearLayout.VERTICAL);
        fxListBox.setClipChildren(false);
        fxListBox.setPadding(dp(this, 16), dp(this, 4), dp(this, 16), dp(this, 24) + navBarH()); // dock 已藏：底部留白避手势条
        fxZoneScroll.addView(fxListBox);
        FrameLayout wrap = new FrameLayout(this);
        wrap.addView(fxZoneScroll, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        attachDragBar(wrap, fxZoneScroll, false, 8, 8);
        root.addView(wrap, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f));
        renderFxList();
        if (fxZoneKeepY > 0) {
            final int y = fxZoneKeepY;
            fxZoneScroll.post(() -> { if (fxZoneScroll != null) fxZoneScroll.scrollTo(0, y); });
        }
        // Q64 同口径轻入场
        root.setAlpha(0f); root.setTranslationY(dp(this, 4));
        root.animate().alpha(1f).translationY(0f).setDuration(ANIM_DUR_FADE).setInterpolator(ANIM_ENTER).start();
        return root;
    }

    boolean fxMatch(FxCard f, String q) {
        if (q == null || q.trim().isEmpty()) return true;
        String s = q.trim().toLowerCase(java.util.Locale.US);
        if (f.name != null && f.name.toLowerCase(java.util.Locale.US).contains(s)) return true;
        if (f.nameEn != null && f.nameEn.toLowerCase(java.util.Locale.US).contains(s)) return true;
        if (f.bank != null && f.bank.toLowerCase(java.util.Locale.US).contains(s)) return true;
        if (f.orgLabel().toLowerCase(java.util.Locale.US).contains(s)) return true;
        for (String a : f.aliases) if (a != null && a.toLowerCase(java.util.Locale.US).contains(s)) return true;
        for (String k : f.keywords) if (k != null && k.toLowerCase(java.util.Locale.US).contains(s)) return true;
        return false;
    }

    void renderFxList() {
        if (fxListBox == null) return;
        fxListBox.removeAllViews();
        java.util.List<FxCard> all = FxStore.all == null ? new ArrayList<FxCard>() : FxStore.all;
        java.util.List<FxCard> shown = new ArrayList<>();
        for (FxCard f : all) {
            if (fxCoreOnly && !f.coreVerified()) continue;
            if (!fxMatch(f, fxQuery)) continue;
            shown.add(f);
        }
        if (fxCountTv != null) fxCountTv.setText("共 " + shown.size() + " 张" + (fxCoreOnly ? "（核心核实）" : ""));
        if (all.isEmpty()) {
            TextView e = tv(this, "外卡数据读取失败", 13, colText2(), false);
            e.setGravity(Gravity.CENTER);
            e.setPadding(0, dp(this, 40), 0, 0);
            fxListBox.addView(e);
            return;
        }
        if (shown.isEmpty()) {
            TextView e = tv(this, "没有符合的外卡，换个关键词或放宽筛选试试", 13, colText2(), false);
            e.setGravity(Gravity.CENTER);
            e.setPadding(0, dp(this, 40), 0, 0);
            fxListBox.addView(e);
            return;
        }
        for (final FxCard f : shown) {
            LinearLayout cardBox = new LinearLayout(this);
            cardBox.setOrientation(LinearLayout.VERTICAL);
            cardBox.setBackground(rippleBg(colSurface(), 18));
            softShadow(cardBox, 5);
            cardBox.setClipToOutline(true);
            cardBox.setPadding(dp(this, 12), dp(this, 10), dp(this, 12), dp(this, 12));
            LinearLayout.LayoutParams clp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            clp.topMargin = dp(this, 10);
            fxListBox.addView(cardBox, clp);
            cardBox.setOnClickListener(v -> { haptic(); openFxDetail(f); });

            LinearLayout top = new LinearLayout(this);
            top.setOrientation(LinearLayout.HORIZONTAL);
            top.setGravity(Gravity.CENTER_VERTICAL);
            cardBox.addView(top);
            FrameLayout thumb = new FrameLayout(this);
            thumb.setBackground(cardFrameBg131(cardSmallR129(9f))); // Q131：缩略框底衬承托面，角区不露黑
            top.addView(thumb, new LinearLayout.LayoutParams(dp(this, 86), dp(this, 54)));
            ImageView iv = new ImageView(this);
            iv.setScaleType(ImageView.ScaleType.CENTER_CROP);
            iv.setBackground(placeholderGradFor(f.id, cardSmallR129(9f), this)); // 无图走 Q70 占位面（核心无图卡同口径）
            roundClip(iv, cardSmallR129(9f), this);
            thumb.addView(iv, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
            roundClip(thumb, cardSmallR129(9f), this);
            if (f.image != null && !f.image.isEmpty()) {
                Bitmap b = Img.getSized(this, f.image, dp(this, 86));
                if (b != null) iv.setImageBitmap(b);
            }
            LinearLayout tx = new LinearLayout(this);
            tx.setOrientation(LinearLayout.VERTICAL);
            LinearLayout.LayoutParams txLp = new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f);
            txLp.leftMargin = dp(this, 10);
            top.addView(tx, txLp);
            TextView nm = tv(this, f.name, 14, colText(), true);
            nm.setMaxLines(2);
            tx.addView(nm);
            tx.addView(tv(this, f.bank, 11, colText2(), false));
            String meta = f.orgLabel() + " · " + f.typeLabel();
            if (f.level != null && !f.level.isEmpty()) meta += " · " + f.level;
            tx.addView(tv(this, meta, 11, colText2(), false));
            TextView vc = chip(f.verifyLabel(),
                f.coreVerified() ? accentColor() : (darkEff() ? Color.rgb(0x2E, 0x2E, 0x33) : Color.rgb(0xEF, 0xF1, 0xF6)),
                f.coreVerified() ? Color.WHITE : colText2(), 10.5f);
            top.addView(vc);

            LinearLayout metaRow = new LinearLayout(this);
            metaRow.setOrientation(LinearLayout.HORIZONTAL);
            metaRow.setGravity(Gravity.CENTER_VERTICAL);
            LinearLayout.LayoutParams mlp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            mlp.topMargin = dp(this, 8);
            cardBox.addView(metaRow, mlp);
            if (f.tier != null && !f.tier.isEmpty()) metaRow.addView(chip(f.tier, darkEff() ? Color.rgb(0x2E, 0x2E, 0x33) : Color.rgb(0xEF, 0xF1, 0xF6), colText2(), 10.5f));
            if (f.status != null && !f.status.isEmpty()) {
                TextView st = tv(this, f.status, 11, colText2(), false);
                LinearLayout.LayoutParams slp2 = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT);
                slp2.leftMargin = dp(this, 8);
                metaRow.addView(st, slp2);
            }
            if (!f.missing.isEmpty()) {
                TextView mt = tv(this, f.missing.size() + " 项待核", 11, colText3(), false);
                LinearLayout.LayoutParams mtlp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT);
                mtlp.leftMargin = dp(this, 8);
                metaRow.addView(mt, mtlp);
            }
        }
    }

    void openFxDetail(FxCard f) {
        if (fxZoneScroll != null) fxZoneKeepY = fxZoneScroll.getScrollY();
        fxDetailOpen = true;
        if (fullScreenPage != null && fullScreenPage.getParent() == content) content.removeView(fullScreenPage);
        fullScreenPage = buildFxDetailPage(f);
        content.addView(fullScreenPage);
        syncTopFab();
    }

    void closeFxDetail() {
        fxDetailOpen = false;
        if (fullScreenPage != null && fullScreenPage.getParent() == content) content.removeView(fullScreenPage);
        fullScreenPage = buildFxZonePage();
        content.addView(fullScreenPage);
        syncTopFab();
    }

    View buildFxDetailPage(final FxCard f) {
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        root.setBackground(softPageBg());
        root.addView(pageBackHead(f.name, () -> { haptic(); closeFxDetail(); }),
            new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        ScrollView sc = new ScrollView(this);
        thinScrollbar(sc);
        LinearLayout body = new LinearLayout(this);
        body.setOrientation(LinearLayout.VERTICAL);
        body.setPadding(dp(this, 16), dp(this, 10), dp(this, 16), dp(this, 24) + navBarH());
        sc.addView(body);
        root.addView(sc, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f));

        // 卡面大图（无图走 Q70 占位面，与核心无图卡同口径，不编造图）
        int availW = getResources().getDisplayMetrics().widthPixels - dp(this, 32);
        float cardR = cardR129(Math.max(16f, cardRadiusDp(availW / getResources().getDisplayMetrics().density)));
        FrameLayout hero = new FrameLayout(this);
        hero.setBackground(cardFrameBg131(cardR));
        if (Build.VERSION.SDK_INT >= 21) hero.setElevation(dp(this, 6));
        roundClip(hero, cardR, this);
        ImageView hiv = new ImageView(this);
        hiv.setScaleType(ImageView.ScaleType.CENTER_CROP);
        roundClip(hiv, cardR, this);
        Bitmap hb = (f.image != null && !f.image.isEmpty()) ? Img.getSized(this, f.image, availW) : null;
        if (hb != null) hiv.setImageBitmap(hb);
        else hiv.setBackground(placeholderGradFor(f.id, cardR, this));
        hero.addView(hiv, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(this, 180)));
        body.addView(hero, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(this, 180)));

        TextView nm = tvW(this, f.name, 19, colText(), 800);
        LinearLayout.LayoutParams nlp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        nlp.topMargin = dp(this, 14);
        body.addView(nm, nlp);
        if (f.nameEn != null && !f.nameEn.isEmpty()) body.addView(tv(this, f.nameEn, 12, colText2(), false));

        // 信息胶囊两行（组织/卡种/等级/发行状态；银行/优先级）
        int chipBg = darkEff() ? Color.rgb(0x2E, 0x2E, 0x33) : Color.rgb(0xEF, 0xF1, 0xF6);
        LinearLayout cr1 = new LinearLayout(this);
        cr1.setOrientation(LinearLayout.HORIZONTAL);
        LinearLayout.LayoutParams cr1lp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        cr1lp.topMargin = dp(this, 10);
        body.addView(cr1, cr1lp);
        cr1.addView(chip(f.orgLabel(), chipBg, colText(), 11.5f));
        addChipGap(cr1); cr1.addView(chip(f.typeLabel(), chipBg, colText(), 11.5f));
        if (f.level != null && !f.level.isEmpty()) { addChipGap(cr1); cr1.addView(chip(f.level, chipBg, colText(), 11.5f)); }
        if (f.status != null && !f.status.isEmpty()) { addChipGap(cr1); cr1.addView(chip(f.status, chipBg, colText(), 11.5f)); }
        LinearLayout cr2 = new LinearLayout(this);
        cr2.setOrientation(LinearLayout.HORIZONTAL);
        LinearLayout.LayoutParams cr2lp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        cr2lp.topMargin = dp(this, 6);
        body.addView(cr2, cr2lp);
        cr2.addView(chip(f.bank, chipBg, colText(), 11.5f));
        if (f.tier != null && !f.tier.isEmpty()) { addChipGap(cr2); cr2.addView(chip(f.tier, chipBg, colText(), 11.5f)); }
        addChipGap(cr2);
        cr2.addView(chip(f.verifyLabel(), f.coreVerified() ? accentColor() : chipBg, f.coreVerified() ? Color.WHITE : colText2(), 11.5f));

        // 核实状态卡
        body.addView(detailSectionTitle("核实状态"));
        LinearLayout vBox = detailInfoCard();
        body.addView(vBox, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        vBox.addView(tv(this, f.coreVerified() ? "核心字段已按发卡行官网核实" : "产品存在已确认，部分核心字段待官方文件补核，不作推荐依据", 12.5f, colText(), false));
        if (f.verifiedAt != null && !f.verifiedAt.isEmpty()) {
            TextView vt = tv(this, "核实日期：" + f.verifiedAt, 12, colText2(), false);
            LinearLayout.LayoutParams vtlp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            vtlp.topMargin = dp(this, 6);
            vBox.addView(vt, vtlp);
        }
        if (!f.missing.isEmpty()) {
            StringBuilder sb = new StringBuilder("待核字段：");
            for (int i = 0; i < f.missing.size(); i++) {
                if (i > 0) sb.append("、");
                sb.append(fxMissingLabel(f.missing.get(i)));
            }
            TextView mt = tv(this, sb.toString(), 12, colText2(), false);
            LinearLayout.LayoutParams mtlp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            mtlp.topMargin = dp(this, 6);
            vBox.addView(mt, mtlp);
        }

        // 规格
        if (f.specs != null && f.specs.length() > 0) {
            body.addView(detailSectionTitle("规格"));
            LinearLayout specBox = detailInfoCard();
            body.addView(specBox, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
            String[] order = {"年費", "免年費條件", "貨幣轉換費", "幣種支持", "申請資格", "發行情況", "境外ATM取現手續費", "主要權益", "數據狀態", "數據來源"};
            java.util.List<String[]> rows = new ArrayList<>();
            java.util.Set<String> used = new java.util.HashSet<>();
            for (String k : order) {
                String val = f.specs.optString(k, "");
                if (val != null && !val.isEmpty() && !"null".equals(val)) { rows.add(new String[]{k, val}); used.add(k); }
            }
            java.util.Iterator<String> ks = f.specs.keys();
            while (ks.hasNext()) {
                String k = ks.next();
                if (used.contains(k)) continue;
                String val = f.specs.optString(k, "");
                if (val != null && !val.isEmpty() && !"null".equals(val)) rows.add(new String[]{k, val});
            }
            for (int i = 0; i < rows.size(); i++) {
                LinearLayout row = new LinearLayout(this);
                row.setOrientation(LinearLayout.HORIZONTAL);
                row.setGravity(Gravity.TOP);
                row.setPadding(0, dp(this, 8), 0, dp(this, 8));
                specBox.addView(row);
                row.addView(tv(this, rows.get(i)[0], 12.5f, colText3(), false),
                    new LinearLayout.LayoutParams(dp(this, 108), ViewGroup.LayoutParams.WRAP_CONTENT));
                TextView vt = tv(this, rows.get(i)[1], 12.5f, colText(), false);
                vt.setGravity(Gravity.END);
                row.addView(vt, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f));
                if (i < rows.size() - 1) {
                    View div = new View(this);
                    div.setBackgroundColor(darkEff() ? Color.rgb(0x3A, 0x3A, 0x3C) : Color.rgb(0xE6, 0xE6, 0xEB));
                    specBox.addView(div, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, Math.max(1, dp(this, 1) / 2)));
                }
            }
        }

        // 点评
        if (f.review != null && !f.review.isEmpty()) {
            body.addView(detailSectionTitle("点评"));
            TextView rv = tv(this, f.review, 13, inkBody(), false);
            bodyLH(rv);
            body.addView(rv);
        }

        // 官方链接
        if (f.url != null && !f.url.isEmpty()) {
            TextView link = tv(this, "打开官方产品页 ↗", 13.5f, accentColor(), true);
            link.setBackground(rippleBg(colSurface(), 16));
            link.setPadding(dp(this, 14), dp(this, 13), dp(this, 14), dp(this, 13));
            LinearLayout.LayoutParams llp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            llp.topMargin = dp(this, 16);
            body.addView(link, llp);
            final String fu = f.url;
            link.setOnClickListener(v -> {
                haptic();
                try { startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(fu))); } catch (Exception e) { /* 无浏览器时静默 */ }
            });
        }

        TextView foot = tv(this, "外卡专区为独立数据集，与主卡库分开维护；评分模型未定，暂不出分。", 11, colText3(), false);
        LinearLayout.LayoutParams flp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        flp.topMargin = dp(this, 14);
        body.addView(foot, flp);

        root.setAlpha(0f); root.setTranslationY(dp(this, 4));
        root.animate().alpha(1f).translationY(0f).setDuration(ANIM_DUR_FADE).setInterpolator(ANIM_ENTER).start();
        return root;
    }

    void addChipGap(LinearLayout row) {
        View sp = new View(this);
        row.addView(sp, new LinearLayout.LayoutParams(dp(this, 6), 1));
    }

