            styleIconPaint129(p); // Q129：图标包风格层（现行包空转）
            p.setStrokeJoin(Paint.Join.ROUND);
            float ox = getPaddingLeft(), oy = getPaddingTop();
            float sx = (getWidth() - getPaddingLeft() - getPaddingRight()) / 24f;
