    // Q83 标题下标签流：组织/卡种/状态/银行/评分/特点/学生推荐，手动估宽换行（全库无 FlowLayout 先例，不引新组件）
    LinearLayout buildDetailChips(Card c) {
        LinearLayout wrap = new LinearLayout(this);
        wrap.setOrientation(LinearLayout.VERTICAL);
        java.util.List<TextView> chips = new java.util.ArrayList<>();
        int chipBg = darkEff() ? Color.rgb(0x2E, 0x2E, 0x33) : Color.rgb(0xEF, 0xF1, 0xF6);
        chips.add(chip(orgLabel(c.org), chipBg, colText(), 12f));
        chips.add(chip(c.isCredit() ? "信用卡" : "借记卡", chipBg, colText(), 12f));
        if (c.status != null && !c.status.isEmpty()) chips.add(chip(c.status, chipBg, colText(), 12f));
        if (c.bank != null && !c.bank.isEmpty()) chips.add(chip(c.bank, chipBg, colText(), 12f));
        if (c.hasScore) chips.add(chip((isEn() ? "Score " : "评分 ") + String.format(java.util.Locale.US, "%.1f", c.score), accentColor(), Color.WHITE, 12f));
        for (String[] f : FEATS) if (featMatch(c, f[0])) chips.add(chip(EN_MODE ? featLabelEn(f[0]) : f[1], chipBg, colText(), 12f)); // Q114：英文缩略表，与瓷砖同口径
        if (c.studentPick) chips.add(chip("学生推荐", accentColor(), Color.WHITE, 12f));
        // Q91：宽度按文字实测（Paint 量 12sp 粗体实宽），旧版「字数×0.68」把中文宽度估小、
        // 行内总宽溢出后后面的胶囊被横向 LinearLayout 挤成一字宽、文字竖排成条（真机「评分 9.8」竖条）。
        Paint chipMp = new Paint(Paint.ANTI_ALIAS_FLAG);
        chipMp.setTextSize(12f * uiScale * getResources().getDisplayMetrics().scaledDensity);
        try { chipMp.setTypeface(weightTypeface(this, 700)); } catch (Throwable ignored) {}
        for (TextView ch : chips) {
            // 单行钉死：任何胶囊都不许换行竖排，万一单个超宽只许尾部省略
            ch.setSingleLine(true);
            ch.setMaxLines(1);
            ch.setEllipsize(android.text.TextUtils.TruncateAt.END);
        }
        int maxW = getResources().getDisplayMetrics().widthPixels - dp(this, 36);
        LinearLayout row = null;
        int rowW = 0;
        for (TextView ch : chips) {
            int w = (int) Math.ceil(chipMp.measureText(ch.getText().toString())) + dp(this, 12);
            if (row == null || (rowW > 0 && rowW + w > maxW)) {
                row = new LinearLayout(this);
                row.setOrientation(LinearLayout.HORIZONTAL);
                LinearLayout.LayoutParams rlp = new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
                if (wrap.getChildCount() > 0) rlp.topMargin = dp(this, 6);
                wrap.addView(row, rlp);
                rowW = 0;
            }
            LinearLayout.LayoutParams clp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            if (rowW > 0) clp.leftMargin = dp(this, 6);
            row.addView(ch, clp);
            rowW += w + dp(this, 6);
        }
        LinearLayout.LayoutParams lp2 = new LinearLayout.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        lp2.topMargin = dp(this, 10);
        wrap.setLayoutParams(lp2);
        return wrap;
    }

    // Q83 底部主按钮两态：未加入=蓝紫渐变实心主按钮；已加入=素面管理入口
    void updateDetailPrimary(Card c) {
        if (detailPrimaryBtn == null || c == null) return;
        boolean joined = !entriesForCard(c.id).isEmpty();
        if (joined) {
            detailPrimaryBtn.setText(S("added_manage"));
            detailPrimaryBtn.setTextColor(colText());
            // Q102（2.16）：回干净悬浮胶囊——近实白 Soft 柔面＋白边，不再叠半透玻璃染色
            // （旧口径 glassTintDrawable(999, darkEff()) 把 darkEff 误传 oval 形参，浅色下
            // 三层玻璃叠出灰雾胶囊）；钮下 pillWrap 玻璃层只作外圈光晕，不再染钮身。
            // Q123（2.35，件八补注）：已加入态钮身改全不透实面——softSheetBg 的
            // 246/238 半透坐在 pillWrap 玻璃层之上仍透出身后正文（用户 02:11 图证
            // 数据状态行被半透白钮盖住）；同色系压满 alpha、深档同理，两态都不透字。
            GradientDrawable joinedBg = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,
                darkEff() ? new int[]{Color.rgb(30, 39, 56), Color.rgb(22, 30, 45)}
                          : new int[]{Color.rgb(253, 254, 255), Color.rgb(240, 246, 252)});
            joinedBg.setStroke(dp(this, 1), darkEff() ? Color.argb(80, 255, 255, 255) : Color.argb(170, 255, 255, 255));
            joinedBg.setCornerRadius(dp(this, 999));
            detailPrimaryBtn.setBackground(joinedBg);
        } else {
            detailPrimaryBtn.setText(S("add_to_mine"));
            detailPrimaryBtn.setTextColor(Color.WHITE);
            GradientDrawable g = new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,
                new int[]{Color.rgb(0x0A, 0x84, 0xFF), Color.rgb(0x5E, 0x5C, 0xE6)});
            g.setCornerRadius(dp(this, 999));
            detailPrimaryBtn.setBackground(g);
        }
    }

