    // ---------- 资讯 / 设置 ----------
    // ---------- 数据 OTA（Phase 4c，对照 app.js checkDataUpdate/DATA_URLS） ----------
    boolean otaFetchStarted = false;

    // 启动自动查一次；设置页手动查 manual=true 给 toast 反馈。
    // Q59 修：双线都取，以 data_version 高者为准（jsDelivr 200 但回旧缓存时不被其骗成「已是最新」）。
    // Q121（2.33）：启动自动检测的发起口——延到首帧之后再发，你好页在场时顺延到
    // 散场（与 hwJustRetreated 提示同款自投递守卫），不和首帧渲染/欢迎页抢主线程；
    // 真正的拉取与全量比对在 checkDataUpdate 内部的后台线程（双线取高版本），
    // 结果回主线程只弹提示（红点/确认窗走 showUpdateTip/showUpdateConfirm 既有口径：
    // 只检测不自动应用，应用须确认且不动用户自有卡片）。
    void scheduleAutoDataCheck() {
        mainHandler.postDelayed(new Runnable() {
            @Override public void run() {
                if (helloOpen) { mainHandler.postDelayed(this, 1200); return; }
                checkDataUpdate(false);
            }
        }, 1500);
    }

    /** Q122（2.34，件六）：带总期限的读流——conn 的 readTimeout 只管单次 read 的
     * 间隔，慢滴服务器能把检查拖成无反馈假死；总期限（9s/线）到点抛
     * SocketTimeoutException，失败文案按超时人话收口。双线最坏约 2×(5s 连接+9s 读)
     * 有界，期间手动入口已有「正在检查更新…」反馈在屏。 */
    static String readAllDeadline(java.io.InputStream in, long deadlineMs) throws Exception {
        java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();
        byte[] buf = new byte[8192]; int n;
        long t0 = System.currentTimeMillis();
        try {
            while ((n = in.read(buf)) > 0) {
                bos.write(buf, 0, n);
                if (System.currentTimeMillis() - t0 > deadlineMs) throw new java.net.SocketTimeoutException("total deadline " + deadlineMs + "ms");
            }
        } finally { try { in.close(); } catch (Exception ignored) {} }
        return new String(bos.toByteArray(), "UTF-8");
    }

    void checkDataUpdate(final boolean manual) { checkDataUpdate(manual, false, null); }
    // Q62: check = detect only (never applies). Apply happens in applyPendingUpdate after confirm.
    void checkDataUpdate(final boolean manual, final boolean fromPull, final Runnable onDone) {
        if (!manual && otaFetchStarted) { if (onDone != null) onDone.run(); return; }
        otaFetchStarted = true;
        // Q122（2.34，件六）：手动点检查必须立刻有反馈——旧流程点完要等双线串行拉完
        // （最长十几秒）才出第一句 toast，用户对着无变化的界面以为卡死（01:30 点名）。
        if (manual) runOnUiThread(() -> showFloatToast("正在检查更新…"));
        final String[] urls = {
            "https://cdn.jsdelivr.net/gh/dimlogue/cardbox-data@main/cards.json",
            "https://raw.githubusercontent.com/dimlogue/cardbox-data/main/cards.json"
        };
        final boolean[] sawTimeout122 = {false};
        new Thread(() -> {
            String bestJson = null; int bestVer = -1;
            for (String u : urls) {
                try {
                    HttpURLConnection conn = (HttpURLConnection) new URL(u + "?t=" + System.currentTimeMillis()).openConnection();
                    conn.setConnectTimeout(5000); conn.setReadTimeout(5000); // Q122：单次超时收紧，下方另有总期限
                    conn.setRequestProperty("Cache-Control", "no-cache");
                    if (conn.getResponseCode() != 200) { conn.disconnect(); continue; }
                    String json = readAllDeadline(conn.getInputStream(), 9000); conn.disconnect(); // Q122（件六）：慢滴不能裸等，总期限到点按超时收口
                    int remoteVer = Store.versionOf(json);
                    try { JSONObject probe = new JSONObject(json); JSONArray pa = probe.getJSONArray("cards"); if (pa == null || pa.length() == 0) continue; } catch (Exception e) { continue; }
                    if (remoteVer > bestVer) { bestVer = remoteVer; bestJson = json; }
                } catch (Exception e) { if (e instanceof java.net.SocketTimeoutException) sawTimeout122[0] = true; }
            }
            if (bestJson == null) {
                // Q122（件六）：失败给人话原因——超时与连不上分开说，不再笼统一句「检查网络」
                final String failMsg122 = sawTimeout122[0] ? "检查超时：网络太慢或服务器没响应，请稍后再试" : "检查更新失败：两条线路都没连上，请检查网络后重试";
                runOnUiThread(() -> { otaFetchStarted = false; if (fromPull) showFloatToast(failMsg122); else if (manual) showFloatToast(failMsg122); if (onDone != null) onDone.run(); });
                return;
            }
            if (bestVer <= Store.dataVersion) {
                pendingUpdateJson = null; pendingUpdateVer = -1; pendingUpdateSummary = "";
                if (prefs != null) prefs.edit().remove("pending_update_version").apply();
                runOnUiThread(() -> { otaFetchStarted = false; if (manual || fromPull) showFloatToast("已是最新数据（v" + Store.dataVersion + "）"); if (onDone != null) onDone.run(); });
                return;
            }
            pendingUpdateJson = bestJson; pendingUpdateVer = bestVer;
            pendingUpdateSummary = updateDiffSummary(bestJson); // Q123（件三）：摘要在本后台线程先算好，确认窗只读现成串
            if (prefs != null) prefs.edit().putInt("pending_update_version", bestVer).apply();
            final int ver = bestVer;
            runOnUiThread(() -> {
                otaFetchStarted = false; // Q122：查毕放闸，后续手动/自动检查不再被首查标记永久挡下
                if (onDone != null) onDone.run();
                if ("settings".equals(tab)) rebuildPages();
                if (manual || fromPull) { showUpdateConfirm(); }
                else {
                    int prompted = prefs == null ? -1 : prefs.getInt("update_prompted_version", -1);
                    if (prompted != ver && !isChromeCovered()) {
                        if (prefs != null) prefs.edit().putInt("update_prompted_version", ver).apply();
                        showUpdateTip(ver);
                    }
                }
            });
        }).start();
    }
    // Q123（2.35，件三）：变化摘要——新版 JSON 与当前生效卡库按 id 对账：新增/移除按
    // id 集合差，内容调整按关键字段签名（名/行/组织/类型/状态/评分/图/specs/variants/
    // 学生精选）比对。算不出（解析异常）返回空串，确认窗走「以新版为准」兜底说明。
    static String cardSig123(String id, String name, String bank, String org, String type, String status,
                             double score, boolean hasScore, String image, String specsStr, int variantsLen, boolean studentPick) {
        return id + "|" + name + "|" + bank + "|" + org + "|" + type + "|" + status + "|"
            + (hasScore ? String.valueOf(score) : "-") + "|" + image + "|" + specsStr + "|" + variantsLen + "|" + (studentPick ? "1" : "0");
    }
    String updateDiffSummary(String json) {
        try {
            JSONArray arr = new JSONObject(json).optJSONArray("cards");
            if (arr == null) return "";
            java.util.Map<String, String> cur = new java.util.HashMap<>();
            for (Card c : Store.all) {
                if (c == null || c.id == null || c.id.isEmpty()) continue;
                cur.put(c.id, cardSig123(c.id, c.name, c.bank, c.org, c.type, c.status, c.score, c.hasScore,
                    c.image, c.specs == null ? "" : c.specs.toString(),
                    c.variants == null ? 0 : c.variants.length(), c.studentPick));
            }
            int added = 0, changed = 0;
            java.util.Set<String> remoteIds = new java.util.HashSet<>();
            for (int i = 0; i < arr.length(); i++) {
                JSONObject o = arr.optJSONObject(i);
                if (o == null) continue;
                String id = o.optString("id");
                if (id.isEmpty()) continue;
                remoteIds.add(id);
                JSONObject sp = o.optJSONObject("specs");
                JSONArray va = o.optJSONArray("variants");
                String sig = cardSig123(id, o.optString("name"), o.optString("bank"), o.optString("org"),
                    o.optString("type", "debit"), o.optString("status"), o.optDouble("score", 0),
                    o.has("score") && !o.isNull("score"), o.optString("image"),
                    sp == null ? "" : sp.toString(), va == null ? 0 : va.length(),
                    o.optJSONObject("student_pick") != null);
                String cs = cur.get(id);
                if (cs == null) added++;
                else if (!cs.equals(sig)) changed++;
            }
            int removed = 0;
            for (String id : cur.keySet()) if (!remoteIds.contains(id)) removed++;
            return "本次变化：新增 " + added + " 张 · 移除 " + removed + " 张 · 内容调整 " + changed + " 张。";
        } catch (Exception e) { return ""; }
    }

    void applyPendingUpdate() {
        // Q91：没有确认窗「去更新」的武装标记，一律不写库（cards-ota.json 唯一写入口在此收口）
        if (!updateApplyArmed) return;
        updateApplyArmed = false;
        if (updateApplying) return;
        final String json = pendingUpdateJson; final int ver = pendingUpdateVer;
        if (json == null || ver <= Store.dataVersion) { showFloatToast("已是最新数据（v" + Store.dataVersion + "）"); return; }
        updateApplying = true; showFloatToast("正在更新数据…");
        new Thread(() -> {
            boolean ok = false;
            try { FileOutputStream fos = new FileOutputStream(new File(getFilesDir(), "cards-ota.json")); fos.write(json.getBytes("UTF-8")); fos.close(); ok = Store.parseInto(json); } catch (Exception e) { ok = false; }
            final boolean fok = ok;
            runOnUiThread(() -> {
                updateApplying = false;
                if (!fok) { showFloatToast("检查更新失败，请检查网络"); return; }
                pendingUpdateJson = null; pendingUpdateVer = -1; pendingUpdateSummary = "";
                // Q98：确认应用成功才落标记——Store.load 凭此标记（且须与文件版本一致）才认 OTA 文件
                if (prefs != null) prefs.edit().remove("pending_update_version").putInt("ota_applied_version", Store.dataVersion).apply();
                // Q105（2.19）：数据已换版——内存图缓存仍按路径键存着旧版位图，同进程内不
                // 清就会继续顶住新图（2.15 只做了磁盘按版本分目录，内存这层漏了）。只解除
                // 引用交系统回收，不 recycle（Q21）；磨砂裁片缓存同清（源自旧位图派生）。
                try { synchronized (Img.cache) { Img.cache.evictAll(); } } catch (Throwable ignored) {}
                try { mineFrostCache.evictAll(); } catch (Throwable ignored) {}
                // Q125（2.37，件二）：换版收口——后台清 ota-images 旧版本目录
                // （只留当前＋上一版），并预热新版首页首屏卡图（刚 evictAll，
                // 冷缓存不预热则首次切首页首帧逐张同步解码）。用户数据不碰。
                new Thread(() -> { pruneOldOtaImageDirs125(); warmHomeTiles125(); }).start();
                showFloatToast("卡片数据已更新到 v" + Store.dataVersion + "（" + Store.all.size() + " 张）");
                pages.clear(); if (detailCard == null) rebuildPages();
            });
        }).start();
    }
