    /** Q99：把 target 滚到滚动视口顶沿下 gapDp 处（视口之上即固定头，天然让位）。
     * 等下一轮全局布局落定后按窗口坐标实测位移再 smoothScrollBy——不吃未布局完的
     * getTop 累加（测小滚过头是旧落点把首卡顶进固定头下的根因）。 */
    void scrollTargetBelowFixedHead(final ScrollView sv, final View target, final int gapDp, final Runnable done) {
        if (sv == null || target == null) { if (done != null) done.run(); return; }
        final boolean[] fired = { false };
        final android.view.ViewTreeObserver.OnGlobalLayoutListener[] self = new android.view.ViewTreeObserver.OnGlobalLayoutListener[1];
        self[0] = new android.view.ViewTreeObserver.OnGlobalLayoutListener() {
            @Override public void onGlobalLayout() {
                if (fired[0]) return;
                fired[0] = true;
                try { target.getViewTreeObserver().removeOnGlobalLayoutListener(self[0]); } catch (Throwable ignored) {}
                try {
                    int[] svLoc = new int[2]; sv.getLocationInWindow(svLoc);
                    int[] tgLoc = new int[2]; target.getLocationInWindow(tgLoc);
                    int delta = (tgLoc[1] - svLoc[1]) - dp(MainActivity.this, gapDp);
                    if (delta != 0) sv.smoothScrollBy(0, delta);
                } catch (Throwable ignored) {}
                if (done != null) done.run();
            }
        };
        try { target.getViewTreeObserver().addOnGlobalLayoutListener(self[0]); }
        catch (Throwable ignored) { if (done != null) done.run(); return; }
        // 兜底：目标在布局前被重渲染摘除时观察者永不触发，done（如清深链标记）仍须落闸
        sv.postDelayed(() -> {
            if (fired[0]) return;
            fired[0] = true;
            try { target.getViewTreeObserver().removeOnGlobalLayoutListener(self[0]); } catch (Throwable ignored) {}
            if (done != null) done.run();
        }, 600);
    }

    List<NewsItem> parseNews(String json) {
        try {
            JSONObject root = new JSONObject(json);
            JSONArray arr = root.getJSONArray("items");
            List<NewsItem> out = new ArrayList<>();
            for (int i = 0; i < arr.length(); i++) {
                JSONObject o = arr.getJSONObject(i);
                NewsItem n = new NewsItem();
                // Q125：全字段过 nz125 归一（审计一类 11，远端换版塞 null 不许上屏）
                n.id = nz125(o.optString("id")); n.title = nz125(o.optString("title"));
                n.tag = nz125(o.optString("tag")); n.date = nz125(o.optString("date"));
                n.source = nz125(o.optString("source")); n.summary = nz125(o.optString("summary"));
                n.url = nz125(o.optString("url"));
                out.add(n);
            }
            return out;
        } catch (Exception e) { return null; }
    }

    List<GlossaryItem> parseGlossary(String json) {
        try {
            JSONObject root = new JSONObject(json);
            JSONArray arr = root.getJSONArray("items");
            List<GlossaryItem> out = new ArrayList<>();
            for (int i = 0; i < arr.length(); i++) {
                JSONObject o = arr.getJSONObject(i);
                GlossaryItem g = new GlossaryItem();
                // Q125：全字段过 nz125 归一（审计一类 11）
                g.id = nz125(o.optString("id")); g.term = nz125(o.optString("term"));
                g.aka = nz125(o.optString("aka")); g.category = nz125(o.optString("category"));
                g.body = nz125(o.optString("body"));
                // Q114：双语字段（旧版/远端数据缺字段时为空串，显示层回落中文）
                g.termEn = nz125(o.optString("term_en")); g.akaEn = nz125(o.optString("aka_en"));
                g.categoryEn = nz125(o.optString("category_en")); g.bodyEn = nz125(o.optString("body_en"));
                // Q115：合并条的档位子条（种子已合并形态）；子条字段与主条同构、正文整段保全
                JSONArray tiersArr = o.optJSONArray("tiers");
                if (tiersArr != null) {
                    List<GlossaryItem> ts = new ArrayList<>();
                    for (int j = 0; j < tiersArr.length(); j++) {
                        JSONObject to = tiersArr.optJSONObject(j);
                        if (to == null) continue;
                        GlossaryItem tg = new GlossaryItem();
                        tg.id = nz125(to.optString("id")); tg.term = nz125(to.optString("term"));
                        tg.aka = nz125(to.optString("aka")); tg.category = nz125(to.optString("category"));
                        tg.body = nz125(to.optString("body"));
                        tg.termEn = nz125(to.optString("term_en")); tg.akaEn = nz125(to.optString("aka_en"));
                        tg.categoryEn = nz125(to.optString("category_en")); tg.bodyEn = nz125(to.optString("body_en"));
                        if (tg.id == null || tg.id.isEmpty() || tg.term == null || tg.term.isEmpty()) continue;
                        ts.add(tg);
                    }
                    if (!ts.isEmpty()) g.tiers = ts;
                }
                if (g.id == null || g.id.isEmpty() || g.term == null || g.term.isEmpty()) continue;
                out.add(g);
            }
            // Q115（2.28，用户 22:04 提议）：一/二/三类账户三条在解析层合并为一条（展开区
            // 内 III/II/I 三档切换）。种子已是合并形态（tiers）时无残留三条、天然跳过；
            // prefs 缓存与 OTA 远端仍是旧三条数据，靠此分组在运行时回落成同一条——旧数据
            // 回落逻辑不破、三档中英正文整段搬进子条不丢字。合并条落第一条原位。
            GlossaryItem m1 = null, m2 = null, m3 = null;
            int firstIdx = -1;
            for (int i = 0; i < out.size(); i++) {
                String id0 = out.get(i).id;
                if ("acct1".equals(id0) || "acct2".equals(id0) || "acct3".equals(id0)) {
                    if (firstIdx < 0) firstIdx = i;
                    if ("acct1".equals(id0)) m1 = out.get(i);
                    else if ("acct2".equals(id0)) m2 = out.get(i);
                    else m3 = out.get(i);
                }
            }
            int acctN = (m1 != null ? 1 : 0) + (m2 != null ? 1 : 0) + (m3 != null ? 1 : 0);
            if (acctN >= 2 && firstIdx >= 0) {
                GlossaryItem mg = new GlossaryItem();
                mg.id = "acct";
                mg.term = "账户分类（一/二/三类）"; mg.termEn = "Account Classes (I / II / III)";
                mg.aka = "一类账户 · 二类账户 · 三类账户"; mg.akaEn = "Class I · Class II · Class III";
                GlossaryItem anyTier = m1 != null ? m1 : (m2 != null ? m2 : m3);
                mg.category = anyTier.category; mg.categoryEn = anyTier.categoryEn;
                mg.body = ""; mg.bodyEn = ""; // 折叠态靠 aka 行预览，正文在展开区按档出
                mg.tiers = new ArrayList<>();
                if (m3 != null) mg.tiers.add(m3); // 存储序 III/II/I；Q123（件十）显示序由 acctTiersDisplay123 排一/二/三
                if (m2 != null) mg.tiers.add(m2);
                if (m1 != null) mg.tiers.add(m1);
                List<GlossaryItem> grouped = new ArrayList<>();
                for (int i = 0; i < out.size(); i++) {
                    if (i == firstIdx) grouped.add(mg);
                    String gid = out.get(i).id;
                    if ("acct1".equals(gid) || "acct2".equals(gid) || "acct3".equals(gid)) continue;
                    grouped.add(out.get(i));
                }
                out = grouped;
            }
            return out;
        } catch (Exception e) { return null; }
    }

    void ensureGlossary() {
        if (glossaryItems != null) return;
        String cached = prefs == null ? null : prefs.getString("glossary_cache", null);
        List<GlossaryItem> c = cached == null ? null : parseGlossary(cached);
        if (c != null && !c.isEmpty()) { glossaryItems = c; return; }
        String seed = readAssetText("data/glossary.json");
        List<GlossaryItem> s = seed == null ? null : parseGlossary(seed);
        glossaryItems = s == null ? new ArrayList<GlossaryItem>() : s;
    }

    void fetchGlossaryUpdate() {
        if (glossaryFetchStarted) return;
        glossaryFetchStarted = true;
        final String[] urls = {
            "https://cdn.jsdelivr.net/gh/dimlogue/cardbox-data@main/glossary.json",
            "https://raw.githubusercontent.com/dimlogue/cardbox-data/main/glossary.json"
        };
        new Thread(() -> {
            for (String u : urls) {
                try {
                    HttpURLConnection conn = (HttpURLConnection) new URL(u + "?t=" + System.currentTimeMillis()).openConnection();
                    conn.setConnectTimeout(6000); conn.setReadTimeout(6000);
                    conn.setRequestProperty("Cache-Control", "no-cache");
                    if (conn.getResponseCode() != 200) { conn.disconnect(); continue; }
                    InputStream in = conn.getInputStream();
                    ByteArrayOutputStream bos = new ByteArrayOutputStream();
                    byte[] buf = new byte[8192]; int n;
                    while ((n = in.read(buf)) > 0) bos.write(buf, 0, n);
                    in.close(); conn.disconnect();
                    String json = new String(bos.toByteArray(), "UTF-8");
                    List<GlossaryItem> fresh = parseGlossary(json);
                    if (fresh == null || fresh.isEmpty()) continue;
                    boolean changed = glossaryItems == null || glossaryItems.size() != fresh.size()
                        || (!fresh.isEmpty() && !glossaryItems.isEmpty() && !fresh.get(0).id.equals(glossaryItems.get(0).id));
                    if (prefs != null) prefs.edit().putString("glossary_cache", json).apply();
                    glossaryItems = fresh;
                    if (changed) runOnUiThread(() -> { if ("news".equals(tab) && glossaryBox != null) renderGlossary(); });
                    glossaryFetchOk124 = true; glossaryFetchChanged124 = changed; fireGlossaryFetchCb124(); // Q124
                    return;
                } catch (Exception e) { /* 换下一条，失败保持内置/缓存 */ }
            }
            fireGlossaryFetchCb124(); // Q124：双线皆败也算一次完成
        }).start();
    }

