            if (simkeepParseDate(due) == null) { showFloatToast("日期请用 yyyy-MM-dd"); inDue.requestFocus(); return; }
            int cyc = 30; try { cyc = Integer.parseInt(inCycle.getText().toString().trim()); } catch (Throwable ignored) {}
