            done.setPadding(0, dp(this, 9), 0, dp(this, 9)); done.setBackground(roundRect(accentColor(), 10, this));
            acts.addView(done, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f));
