        chip.setGravity(Gravity.CENTER); chip.setPadding(dp(this, 12), dp(this, 7), dp(this, 12), dp(this, 7));
        chip.setBackground(roundRect(on ? accentColor() : colChipOff(), 999, this));
        return chip;
