    // 保存赞助二维码到相册（对照混合版 Bridge saveSponsorQr；API29+ 走 MediaStore 无需权限，低版本先申请写权限）
    void saveSponsorQr() {
        byte[] data;
        try {
            InputStream in = getAssets().open("sponsor_alipay.jpg");
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            byte[] buf = new byte[8192]; int n;
            while ((n = in.read(buf)) > 0) bos.write(buf, 0, n);
            in.close();
            data = bos.toByteArray();
            if (data.length == 0) throw new Exception("empty");
        } catch (Exception e) {
            showFloatToast("保存失败，请稍后再试");
            return;
        }
        if (Build.VERSION.SDK_INT < 29
            && checkSelfPermission(android.Manifest.permission.WRITE_EXTERNAL_STORAGE)
                != android.content.pm.PackageManager.PERMISSION_GRANTED) {
            sponsorSavePending = true;
            requestPermissions(new String[]{android.Manifest.permission.WRITE_EXTERNAL_STORAGE}, 4201);
            return;
        }
        writeSponsorQrToAlbum(data);
    }

    void writeSponsorQrToAlbum(byte[] data) {
        try {
            if (Build.VERSION.SDK_INT >= 29) {
                android.content.ContentValues cv = new android.content.ContentValues();
                cv.put(android.provider.MediaStore.Images.Media.DISPLAY_NAME, "cardbox-sponsor-qr.jpg");
                cv.put(android.provider.MediaStore.Images.Media.MIME_TYPE, "image/jpeg");
                cv.put(android.provider.MediaStore.Images.Media.RELATIVE_PATH, "Pictures/卡盒");
                Uri uri = getContentResolver().insert(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI, cv);
                if (uri == null) throw new Exception("insert failed");
                java.io.OutputStream out = getContentResolver().openOutputStream(uri);
                if (out == null) throw new Exception("open failed");
                out.write(data); out.close();
            } else {
                File dir = new File(android.os.Environment.getExternalStoragePublicDirectory(
                    android.os.Environment.DIRECTORY_PICTURES), "卡盒");
                if (!dir.exists()) dir.mkdirs();
                File f = new File(dir, "cardbox-sponsor-qr.jpg");
                FileOutputStream out = new FileOutputStream(f);
                out.write(data); out.close();
                android.media.MediaScannerConnection.scanFile(this,
                    new String[]{f.getAbsolutePath()}, new String[]{"image/jpeg"}, null);
            }
            showFloatToast("赞助二维码已保存到相册");
        } catch (Exception e) {
            showFloatToast("保存失败，请稍后再试");
        }
    }

    @Override
    public void onRequestPermissionsResult(int requestCode, String[] permissions, int[] grantResults) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);
        if (requestCode == 4201) {
            boolean granted = grantResults.length > 0
                && grantResults[0] == android.content.pm.PackageManager.PERMISSION_GRANTED;
            if (granted && sponsorSavePending) { sponsorSavePending = false; saveSponsorQr(); }
            else {
                sponsorSavePending = false;
                showFloatToast("没有相册写入权限，二维码未保存");
            }
        }
    }

    // ---------- 欢迎页 / 更新日志（Phase 4b） ----------
    // Q93：旧欢迎页（showWelcome/closeWelcome/buildWelcomePage，白底「欢迎使用卡盒」整套）已按用户 15:54 点名删除，
    // 首启与 ⋯ 菜单入口直达下方「你好」页，不再经旧页中转。

    // ---------- Q80/Q93 「你好」页（全 App 唯一欢迎） ----------
    // 首启（welcomed/hello_done 均未落）或 ⋯ 菜单「欢迎页」入口直达本页；hello_done 落盘后日常启动不再构建、不拖冷启动。
    // 动效学 Tiny Cards 节奏自写：深底上五张彩色卡面自四周飞入依次叠成一摞，顶卡极简笑脸收束；
    // 全程只动 View 绘制层（translation/scale/alpha/rotation），不抓图不采样，时长走 Q74 的 ANIM_ENTER/SHEET_IN 口径。
    static class HelloFaceView extends View {
        final Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
        HelloFaceView(Context c) {
            super(c);
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeCap(Paint.Cap.ROUND);
            styleIconPaint129(p); // Q129：图标包风格层（现行包空转）
            p.setColor(Color.WHITE);
        }
        @Override protected void onDraw(Canvas cv) {
            super.onDraw(cv);
            float w = getWidth(), h = getHeight();
            float cx = w / 2f, cy = h / 2f, r = Math.min(w, h) * 0.34f;
            p.setStrokeWidth(Math.max(2f, w * 0.055f));
            cv.drawCircle(cx, cy, r, p);
            float er = Math.max(1.6f, w * 0.028f);
            Paint f = new Paint(Paint.ANTI_ALIAS_FLAG);
            f.setStyle(Paint.Style.FILL); f.setColor(Color.WHITE);
            cv.drawCircle(cx - r * 0.38f, cy - r * 0.18f, er, f);
            cv.drawCircle(cx + r * 0.38f, cy - r * 0.18f, er, f);
            android.graphics.RectF arc = new android.graphics.RectF(cx - r * 0.48f, cy - r * 0.05f, cx + r * 0.48f, cy + r * 0.62f);
            cv.drawArc(arc, 25f, 130f, false, p);
        }
    }

    void showHello() {
        captureCurrentPageScroll(); // 同其余整页浮层口径：关闭后 showTab 恢复原页滚动位置
        helloOpen = true;
        helloClosing = false;
        helloFlat = false;
        if (navWrap != null) navWrap.setVisibility(View.GONE); // Q32
        // Q124（2.36，件三）：欢迎页期间主页悬浮钮漏出（用户 02:43 图证）——搜索/筛选
        // 两钮带 elevation，Z 序压过欢迎页根（elevation 0），且 showHello 旧口径只藏
        // navWrap 与 pageHost、从未摘钮，仅靠同容器后加顺序盖不住高 Z 兄弟。进欢迎页
        // 先把四钮整摘（hideFabsNow 现成口径）；退场走 closeHello→showTab 的
        // syncSearchFab/syncAddFab 原口径重挂，helloOpen 在场期间 sync* 的
        // isChromeCovered 门禁保证不被任何路径召回。
        hideFabsNow();
        // Q120（2.33）：同 openAbout 口径——宿主隐藏、全屏页单挂，驻留页不陪葬。
        if (fullScreenPage != null && fullScreenPage.getParent() == content) content.removeView(fullScreenPage);
        if (pageHost != null) pageHost.setVisibility(View.GONE);
        helloView = buildHelloPage();
        fullScreenPage = helloView;
        content.addView(helloView);
        // Q95 热修（2.07）：首启时首页首次渲染原本从未在欢迎页停留期间跑过——触发它的
        // refreshHome 投在被 removeAllViews 摘掉的首页视图上（View.post 未 attach 即 park），
        // 点「开始使用」重挂瞬间才连同分帧续搭一起开跑，213 张图同步解码与切页淡入、底栏
        // 玻璃背板重 attach 重录同帧相撞（清数据首启必崩、存量用户从不走此链）。
        // 改为欢迎页一落定就在停留期间把首页渲染完（续搭已改投 mainHandler，见
        // addCardRowsChunked），点开始后 showTab 只剩签名短路的纯换页，与日常切页同路。
        mainHandler.post(() -> { if (helloOpen && homeRenderSig == null) refreshHome(); });
    }

    void closeHello() {
        if (helloClosing || !helloOpen) return;
        helloClosing = true;
        // Q95 热修（2.07）：封印必须同步落盘——原 apply() 异步写，若进程在 flush 前死，
        // hello_done 丢失，第二次打开又撞进欢迎页（深底被用户看作「黑屏」）再崩成循环。
        try { prefs.edit().putBoolean("hello_done", true).putBoolean("welcomed", true).commit(); } catch (Throwable ignored) {}
        final View gone = helloView;
        // 单次落定：淡出动画 endAction 与 postDelayed 兜底两条路只许一条真正收尾，
        // 防动画被取消时两边各跑一次 showTab（欢迎收尾是全 App 唯一从动画回调切页的路径，收口在此一处）
        final boolean[] finished = { false };
        Runnable finish = () -> {
            if (finished[0]) return;
            finished[0] = true;
            helloOpen = false;
            helloClosing = false;
            helloView = null;
            if (navWrap != null) navWrap.setVisibility(View.VISIBLE); // Q32
            showTab(tab);
            // Q127（2.39，审计 A3/B1）：欢迎预建若还没搭完（首屏 4 行由 renderHomeList
            // 同步保底、余下按 A2 让路在进入后补齐），点击段不许同步等——未落定就先
            // 亮兜底加载层，落定自摘（addCardRowsChunked 落定处回调用）。
            maybeShowHomeLoading();
        };
        if (gone != null) {
            gone.animate().cancel();
            gone.animate().alpha(0f).setDuration(ANIM_DUR_SHEET_OUT).setInterpolator(ANIM_EXIT)
                .withEndAction(finish).start();
            gone.postDelayed(() -> { if (helloClosing) finish.run(); }, ANIM_DUR_SHEET_OUT + 120);
        } else finish.run();
    }

    View buildHelloPage() {
        final FrameLayout root = new FrameLayout(this);
        root.setBackgroundColor(Color.rgb(0x10, 0x14, 0x20));
        root.setClickable(true);

        LinearLayout col = new LinearLayout(this);
        col.setOrientation(LinearLayout.VERTICAL);
        col.setGravity(Gravity.CENTER_HORIZONTAL);
        FrameLayout.LayoutParams colp = new FrameLayout.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT);
        root.addView(col, colp);
        col.setPadding(dp(this, 28), statusBarH() + dp(this, 30), dp(this, 28), dp(this, 22) + navBarH());

        final FrameLayout stage = new FrameLayout(this);
        col.addView(stage, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(this, 252)));

        // 五张彩卡（自家渐变为示意卡面，不带文字信息层，同 Q78 展柜纯卡面口径）
        final int[][] cols = {
            {0x2E7CF6, 0x174A8B}, {0x8E6BE8, 0x3D2A7A}, {0x16A085, 0x0A4A3A},
            {0xE8833A, 0x8A3D12}, {0xE84E6B, 0x7A1F38}
        };
        final int n = cols.length;
        final View[] cards = new View[n];
        final HelloFaceView[] face = new HelloFaceView[1];
        for (int i = 0; i < n; i++) {
            FrameLayout card = new FrameLayout(this);
            GradientDrawable g = new GradientDrawable(GradientDrawable.Orientation.TL_BR,
                new int[]{Color.rgb(Color.red(cols[i][0]), Color.green(cols[i][0]), Color.blue(cols[i][0])),
                          Color.rgb(Color.red(cols[i][1]), Color.green(cols[i][1]), Color.blue(cols[i][1]))});
            g.setCornerRadius(dp(this, 14));
            g.setStroke(dp(this, 1), Color.argb(70, 255, 255, 255));
            card.setBackground(g);
            if (Build.VERSION.SDK_INT >= 21) card.setElevation(dp(this, 6));
            FrameLayout.LayoutParams cp = new FrameLayout.LayoutParams(dp(this, 196), dp(this, 124));
            cp.gravity = Gravity.CENTER;
            card.setLayoutParams(cp);
            // 叠摞位：逐张上移错开，只露顶带成摞（同 Q78 堆叠口径）
            card.setTranslationY(dp(this, (n - 1 - i) * 13));
            card.setRotation((i - (n - 1) / 2f) * 2.2f);
            stage.addView(card);
            cards[i] = card;
            if (i == n - 1) {
                HelloFaceView fv = new HelloFaceView(this);
                fv.setAlpha(0f);
                FrameLayout.LayoutParams fp = new FrameLayout.LayoutParams(dp(this, 52), dp(this, 52));
                fp.gravity = Gravity.CENTER;
                card.addView(fv, fp);
                face[0] = fv;
            }
        }

        TextView hi = tvW(this, "你好", 46, Color.WHITE, 800);
        hi.setGravity(Gravity.CENTER);
        hi.setLetterSpacing(0.04f);
        hi.setAlpha(0f);
        hi.setTranslationY(dp(this, 10));
        LinearLayout.LayoutParams hip = new LinearLayout.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        hip.topMargin = dp(this, 10);
        col.addView(hi, hip);

        TextView sub = tv(this, "卡盒已经准备好了，慢慢挑你的卡。", 14, Color.argb(170, 255, 255, 255), false);
        sub.setGravity(Gravity.CENTER);
        sub.setAlpha(0f);
        sub.setTranslationY(dp(this, 10));
        LinearLayout.LayoutParams sup = new LinearLayout.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        sup.topMargin = dp(this, 8);
        col.addView(sub, sup);

        // 试玩：堆叠/平放两式切换（样品卡面，守 Q74 淡入轻移；真正展柜在「我的卡片」里用自有卡）
        LinearLayout trial = new LinearLayout(this);
        trial.setOrientation(LinearLayout.HORIZONTAL);
        trial.setGravity(Gravity.CENTER);
        trial.setAlpha(0f);
        LinearLayout.LayoutParams trp = new LinearLayout.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        trp.topMargin = dp(this, 20);
        col.addView(trial, trp);
        final TextView stackChip = tvW(this, "堆叠试玩", 13, Color.WHITE, 600);
        stackChip.setGravity(Gravity.CENTER);
        stackChip.setPadding(dp(this, 16), dp(this, 8), dp(this, 16), dp(this, 8));
        trial.addView(stackChip, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        final TextView flatChip = tvW(this, "平放试玩", 13, Color.argb(170, 255, 255, 255), 600);
        flatChip.setGravity(Gravity.CENTER);
        flatChip.setPadding(dp(this, 16), dp(this, 8), dp(this, 16), dp(this, 8));
        LinearLayout.LayoutParams flp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        flp.leftMargin = dp(this, 10);
        trial.addView(flatChip, flp);
        final Runnable styleTrial = () -> {
            stackChip.setBackground(roundRect(helloFlat ? Color.argb(36, 255, 255, 255) : Color.argb(64, 255, 255, 255), 999, this));
            flatChip.setBackground(roundRect(helloFlat ? Color.argb(64, 255, 255, 255) : Color.argb(36, 255, 255, 255), 999, this));
            stackChip.setTextColor(helloFlat ? Color.argb(170, 255, 255, 255) : Color.WHITE);
            flatChip.setTextColor(helloFlat ? Color.WHITE : Color.argb(170, 255, 255, 255));
        };
        styleTrial.run();
        final Runnable spread = () -> {
            // Q93：平放步距按舞台实宽收拢——卡 196dp 缩 0.62 后半宽约 61dp，步距取
            // min(108dp, 舞台半幅 − 半卡宽 − 6dp 余量)，窄屏自动收拢、旋 3° 后四角也不出屏
            // （旧固定 ±108dp 步距在约 360dp 屏上左右各出血约 20dp 被屏幕切边，用户 15:50 点名）。
            float stepX = dp(this, 108);
            if (helloFlat) {
                int sw = stage.getWidth();
                if (sw <= 0) sw = dp(this, 320);
                float halfAvail = sw / 2f - dp(this, 6);
                float cardHalf = dp(this, 196) * 0.62f / 2f;
                stepX = Math.min(stepX, Math.max(dp(this, 40), halfAvail - cardHalf));
            }
            for (int i = 0; i < n; i++) {
                float tx = helloFlat ? (i % 3 - 1) * stepX : 0f;
                float ty = helloFlat ? dp(this, (i / 3) * 108 - 40) : dp(this, (n - 1 - i) * 13);
                float rot = helloFlat ? (i - 2) * 3f : (i - (n - 1) / 2f) * 2.2f;
                float sc = helloFlat ? 0.62f : 1f;
                cards[i].animate().translationX(tx).translationY(ty).rotation(rot).scaleX(sc).scaleY(sc)
                    .setDuration(460).setInterpolator(ANIM_ENTER).start(); // Q98：堆叠↔平放切换同步放慢（旧 ANIM_DUR_FADE 220ms 一晃而过）
            }
        };
        stackChip.setOnClickListener(v -> { haptic(); if (helloFlat) { helloFlat = false; styleTrial.run(); spread.run(); } });
        flatChip.setOnClickListener(v -> { haptic(); if (!helloFlat) { helloFlat = true; styleTrial.run(); spread.run(); } });

        TextView go = tvW(this, "开始使用", 15.5f, Color.rgb(0x10, 0x14, 0x20), 700);
        go.setGravity(Gravity.CENTER);
        go.setBackground(roundRect(Color.WHITE, 16, this));
        go.setPadding(dp(this, 28), dp(this, 14), dp(this, 28), dp(this, 14));
        go.setAlpha(0f);
        go.setTranslationY(dp(this, 10));
        LinearLayout.LayoutParams gop = new LinearLayout.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        gop.topMargin = dp(this, 24);
        col.addView(go, gop);
        go.setOnClickListener(v -> { haptic(); closeHello(); });

        TextView hint = tv(this, "轻触任意处进入", 11.5f, Color.argb(120, 255, 255, 255), false);
        hint.setGravity(Gravity.CENTER);
        hint.setAlpha(0f);
        LinearLayout.LayoutParams hnp = new LinearLayout.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        hnp.topMargin = dp(this, 12);
        col.addView(hint, hnp);

        root.setOnClickListener(v -> closeHello());
        // 飞入：每张自四周带位移与缩小飞入，错峰错开，单张缓出（ANIM_ENTER）飞入；落定后笑脸与文案依次淡入。
        // Q98 调速（用户 17:08 点名太快没看清）：旧单张 ANIM_DUR_SHEET_IN(280ms)+错峰 120ms，五张
        // 约 0.76s 一闪而过；新单张 560ms、错峰 210ms，末张落定约 1.4s，文案尾序毕总时长约 2.0s。
        // Q99 再调（用户 18:31 点名堆叠式仍小快且卡）：单张 780ms、错峰 300ms，末张落定约 2.0s，
        // 文案尾序错开 110ms 一级，整场约 2.75s；飞入期卡片走硬件层直绘（落定即撤），
        // 且背板采样全程冻结（captureBackdrop/captureBand 的 helloOpen 闸），不与动画抢主线程。
        root.post(() -> {
            float w = Math.max(stage.getWidth(), dp(this, 320));
            float[] dx = {-w * 0.7f, w * 0.7f, -w * 0.55f, w * 0.55f, 0f};
            float[] dy = {-dp(this, 150), -dp(this, 120), dp(this, 150), dp(this, 120), -dp(this, 190)};
            for (int i = 0; i < n; i++) {
                final View c = cards[i];
                final float baseTy = c.getTranslationY();
                final float baseRot = c.getRotation();
                c.setTranslationX(dx[i]);
                c.setTranslationY(dy[i]);
                c.setScaleX(0.82f); c.setScaleY(0.82f);
                c.setAlpha(0f);
                c.setLayerType(View.LAYER_TYPE_HARDWARE, null);
                c.animate().translationX(0f).translationY(baseTy).rotation(baseRot)
                    .scaleX(1f).scaleY(1f).alpha(1f)
                    .setStartDelay(i * 300L).setDuration(780).setInterpolator(ANIM_ENTER)
                    .withEndAction(() -> c.setLayerType(View.LAYER_TYPE_NONE, null)).start();
            }
            long tail = (n - 1) * 300L + 780L;
            if (face[0] != null) face[0].animate().alpha(1f).setStartDelay(tail).setDuration(ANIM_DUR_FADE).setInterpolator(ANIM_ENTER).start();
            hi.animate().alpha(1f).translationY(0f).setStartDelay(tail + 110).setDuration(ANIM_DUR_FADE).setInterpolator(ANIM_ENTER).start();
            sub.animate().alpha(1f).translationY(0f).setStartDelay(tail + 220).setDuration(ANIM_DUR_FADE).setInterpolator(ANIM_ENTER).start();
            trial.animate().alpha(1f).setStartDelay(tail + 330).setDuration(ANIM_DUR_FADE).setInterpolator(ANIM_ENTER).start();
            go.animate().alpha(1f).translationY(0f).setStartDelay(tail + 440).setDuration(ANIM_DUR_FADE).setInterpolator(ANIM_ENTER).start();
            hint.animate().alpha(1f).setStartDelay(tail + 550).setDuration(ANIM_DUR_FADE).setInterpolator(ANIM_ENTER).start();
        });
        return root;
    }

    static class LogEntry { String v; List<String> notes = new ArrayList<>(); }

    List<LogEntry> loadChangelog() {
        List<LogEntry> out = new ArrayList<>();
        try {
            InputStream in = getAssets().open("data/changelog.json");
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            byte[] buf = new byte[8192]; int r;
            while ((r = in.read(buf)) > 0) bos.write(buf, 0, r);
            in.close();
            JSONArray arr = new JSONArray(new String(bos.toByteArray(), "UTF-8"));
            for (int i = 0; i < arr.length(); i++) {
                JSONObject o = arr.getJSONObject(i);
                LogEntry e = new LogEntry();
                e.v = o.optString("v");
                JSONArray ns = o.optJSONArray("notes");
                if (ns != null) for (int j = 0; j < ns.length(); j++) e.notes.add(ns.optString(j));
                out.add(e);
            }
        } catch (Exception e) { /* 读不到就空列表，页面会提示 */ }
        return out;
    }

    void showChangelog() {
        captureCurrentPageScroll();
        changelogOpen = true;
        if (navWrap != null) navWrap.setVisibility(View.GONE); // Q32: hide whole dock incl. glass layer - hiding navBar alone leaks a glass strip at screen bottom
        // Q120（2.33）：同 openAbout 口径——宿主隐藏、全屏页单挂，驻留页不陪葬。
        if (fullScreenPage != null && fullScreenPage.getParent() == content) content.removeView(fullScreenPage);
        if (pageHost != null) pageHost.setVisibility(View.GONE);
        fullScreenPage = buildChangelogPage();
        content.addView(fullScreenPage);
        syncTopFab();
    }

    // Q123（2.35，件六）：更新日志来路——旧通路：关于页 logLink 先自清
    // aboutPageOpen（17502 一带旧行）再 showChangelog，关时 closeChangelog 一律
    // showTab(tab) 而 tab 仍是 settings，于是「收起日志」直落设置页。改：进时记
    // 标记＋存关于滚动位，关时从来路回（重开关于并恢复滚动），与 2.34 常识浮层
    // 「从哪进回哪」同一层序口径；非关于来路仍 showTab 原样。
    boolean changelogFromAbout123 = false;
    int aboutKeepScrollY123 = 0;

    void closeChangelog() {
        changelogOpen = false;
        if (navWrap != null) navWrap.setVisibility(View.VISIBLE); // Q32
        if (changelogFromAbout123) {
            changelogFromAbout123 = false;
            openAbout();
            if (aboutScroll != null && aboutKeepScrollY123 > 0) {
                final int y123 = aboutKeepScrollY123;
                aboutScroll.post(() -> aboutScroll.scrollTo(0, y123));
            }
            return;
        }
        showTab(tab);
    }

    // Q50：更新日志底部动作行——对照混合版 styles.css .cl-actions（display:flex;gap:10px;justify-content:center）
    // 与 .cl-top（padding:9px 20px;border-radius:999px;background:#eef4fb;color:#0a5cd6;font-weight:700;font-size:.85rem）
    // 两钮居中并排药丸、紧贴日志框下沿成一组，不再整宽灰钮平摊；两处（独立页/设置页内嵌）共用此助手保证口径一致。
    // Q130（件二）：底带并入全站胶囊语言——colSurface 底带＋顶部发丝线承托，药丸改 accentSoftBg 底＋accentColor 字，
    // 不再是飘在渐变页底上的一对浅蓝钮。功能与文案一字未动。
    LinearLayout changelogActions(final Runnable onTop, final Runnable onFold) {
        LinearLayout wrap = new LinearLayout(this);
        wrap.setOrientation(LinearLayout.VERTICAL);
        wrap.setBackgroundColor(colSurface());
        View hair = new View(this);
        hair.setBackgroundColor(colDivider());
        wrap.addView(hair, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, Math.max(1, dp(this, 1))));
        LinearLayout actions = new LinearLayout(this);
        actions.setOrientation(LinearLayout.HORIZONTAL);
        actions.setGravity(Gravity.CENTER);
        actions.setPadding(dp(this, 12), dp(this, 8), dp(this, 12), dp(this, 10));
        wrap.addView(actions, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        TextView top = tvW(this, "↑ 回到顶部", 13.5f, accentColor(), 700);
        top.setGravity(Gravity.CENTER);
        top.setBackground(rippleBg(accentSoftBg(), 999));
        top.setPadding(dp(this, 20), dp(this, 9), dp(this, 20), dp(this, 9));
        top.setOnTouchListener((v, ev) -> {
            if (ev.getAction() == android.view.MotionEvent.ACTION_DOWN) pressBounce(v, true);
            else if (ev.getAction() == android.view.MotionEvent.ACTION_UP || ev.getAction() == android.view.MotionEvent.ACTION_CANCEL) pressBounce(v, false);
            return false;
        });
        top.setOnClickListener(v -> { haptic(); if (onTop != null) onTop.run(); });
        actions.addView(top, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        TextView fold = tvW(this, "收起日志", 13.5f, accentColor(), 700);
        fold.setGravity(Gravity.CENTER);
        fold.setBackground(rippleBg(accentSoftBg(), 999));
        fold.setPadding(dp(this, 20), dp(this, 9), dp(this, 20), dp(this, 9));
        fold.setOnTouchListener((v, ev) -> {
            if (ev.getAction() == android.view.MotionEvent.ACTION_DOWN) pressBounce(v, true);
            else if (ev.getAction() == android.view.MotionEvent.ACTION_UP || ev.getAction() == android.view.MotionEvent.ACTION_CANCEL) pressBounce(v, false);
            return false;
        });
        fold.setOnClickListener(v -> { haptic(); if (onFold != null) onFold.run(); });
        LinearLayout.LayoutParams flp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        flp.leftMargin = dp(this, 10);
        actions.addView(fold, flp);
        return wrap;
    }

    View buildChangelogPage() {
        // Q131（2.43，件三）：整页沉浸式——根改 FrameLayout，页底 softPageBg 一通到底
        // （状态栏后/标题区/滚动区/底带身后是同一张底）；底部动作带改以 BOTTOM 锚死
        // 在窗口物理底边，不再靠纵向 LinearLayout 的权重分配落位（2.42 真机图证：带子
        // 与屏底之间断开一截，见「白带断层」）。带高落位后回填为滚动区底边距，滚动
        // 几何与 2.42（头＋滚动区＋带）逐位一致；日志内容、文案、滚动条方案、两钮
        // 功能一字未动，手势区留白仍是带内 navBarH（全 App 既有沉浸口径）。
        final FrameLayout root = new FrameLayout(this);
        root.setBackground(softPageBg()); // Q94 铺开：雾蓝页底（原 Q72）
        LinearLayout col = new LinearLayout(this);
        col.setOrientation(LinearLayout.VERTICAL);
        root.addView(col, new FrameLayout.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));

        // Q92：全站二级页头（圆形细线返回钮 + 标题），废原生白药丸返回钮
        col.addView(pageBackHead("更新日志", () -> { haptic(); closeChangelog(); }),
            new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        changelogScroll = new ScrollView(this);
        LinearLayout page = new LinearLayout(this);
        page.setOrientation(LinearLayout.VERTICAL);
        page.setPadding(dp(this, 16), dp(this, 6), dp(this, 16), dp(this, 16));
        changelogScroll.addView(page);
        if (Build.VERSION.SDK_INT >= 23) changelogScroll.setOnScrollChangeListener((v, sx, sy, ox, oy) -> updateTopFabVisibility(sy));
        // Q49：更新日志长列表可拖拽黑条（按住拖快速拉动全文）
        // Q130（件二）：persistent 改 false 与全 App 统一——右缘不再常显一根原始条，滚动/拖动时
        // 才出既有玻璃胶囊条＋百分比气泡（DragBarView 本体即用户选定方案，只抓拇指不劫手势）。
        FrameLayout logWrap = new FrameLayout(this);
        logWrap.addView(changelogScroll, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        attachDragBar(logWrap, changelogScroll, false, 8, 8);
        col.addView(logWrap, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f));

        List<LogEntry> logs = loadChangelog();
        if (logs.isEmpty()) {
            page.addView(tv(this, "更新日志读取失败", 13.5f, colText2(), false));
        }
        // Q130（件二）：每个版本包进 Soft 白卡（roundRect(colSurface(),18) 与设置页同语言），
        // 版本号 15sp/800 突出，条目改小圆点＋正文排版；记录 note 文本一字未动（旧「• 」本就是
        // 代码拼的前缀，现由绘制圆点承担）。
        for (LogEntry e : logs) {
            LinearLayout verCard = new LinearLayout(this);
            verCard.setOrientation(LinearLayout.VERTICAL);
            verCard.setBackground(roundRect(colSurface(), 18, this));
            verCard.setClipToOutline(true);
            verCard.setPadding(dp(this, 14), dp(this, 12), dp(this, 14), dp(this, 13));
            LinearLayout.LayoutParams clp130 = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            clp130.topMargin = dp(this, 10);
            page.addView(verCard, clp130);
            TextView ver = tvW(this, "v" + e.v, 15, colText(), 800);
            verCard.addView(ver, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
            boolean firstNote130 = true;
            for (String note : e.notes) {
                LinearLayout nrow = new LinearLayout(this);
                nrow.setOrientation(LinearLayout.HORIZONTAL);
                nrow.setGravity(Gravity.TOP);
                LinearLayout.LayoutParams nrlp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
                nrlp.topMargin = dp(this, firstNote130 ? 7 : 5);
                firstNote130 = false;
                verCard.addView(nrow, nrlp);
                View dot130 = new View(this);
                GradientDrawable dotBg130 = new GradientDrawable();
                dotBg130.setShape(GradientDrawable.OVAL);
                dotBg130.setColor(colText3());
                dot130.setBackground(dotBg130);
                LinearLayout.LayoutParams dotLp130 = new LinearLayout.LayoutParams(dp(this, 5), dp(this, 5));
                dotLp130.topMargin = dp(this, 6);
                nrow.addView(dot130, dotLp130);
                TextView nt = tv(this, note, 12.5f, inkBody(), false);
                nt.setLineSpacing(0, 1.45f);
                LinearLayout.LayoutParams nlp = new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f);
                nlp.leftMargin = dp(this, 8);
                nrow.addView(nt, nlp);
            }
        }

        final LinearLayout actions = changelogActions(
            () -> { if (changelogScroll != null) changelogScroll.smoothScrollTo(0, 0); },
            () -> closeChangelog());
        // 独立页 dock 已藏，底部避让手势条一次算清，两钮完整可见不半埋
        actions.setPadding(actions.getPaddingLeft(), actions.getPaddingTop(), actions.getPaddingRight(), actions.getPaddingBottom() + navBarH());
        // Q131：带以 BOTTOM 锚死窗口底边（见函数头注释）；带高落位后回填为滚动区
        // 底边距，滚动视口止于带上沿、拖条止点随之同旧位，几何与 2.42 一致。
        FrameLayout.LayoutParams alp131 = new FrameLayout.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        alp131.gravity = Gravity.BOTTOM;
        root.addView(actions, alp131);
        actions.post(() -> {
            int bh131 = actions.getHeight();
            if (bh131 > 0 && logWrap.getLayoutParams() instanceof LinearLayout.LayoutParams) {
                LinearLayout.LayoutParams llp131 = (LinearLayout.LayoutParams) logWrap.getLayoutParams();
                if (llp131.bottomMargin != bh131) { llp131.bottomMargin = bh131; logWrap.setLayoutParams(llp131); }
            }
        });
        return root;
    }


    // ── Q58 ⋯ 菜单丝滑展开（只学机制自写：缩放原点贴按钮角、缩放+淡入同步、轻回弹、点外部反向收回）──
    class MoreDotsView extends View {
        MoreDotsView(Context c) { super(c); }
        @Override protected void onDraw(Canvas cv) {
            super.onDraw(cv);
            Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
            p.setStyle(Paint.Style.FILL);
            p.setColor(Color.rgb(0x1C, 0x1C, 0x1E));
            float cx = getWidth() / 2f;
            float r = dp(getContext(), 2.1f);
            float gap = dp(getContext(), 6.2f);
            float cy = getHeight() / 2f;
            cv.drawCircle(cx, cy - gap, r, p);
            cv.drawCircle(cx, cy, r, p);
            cv.drawCircle(cx, cy + gap, r, p);
        }
    }

    View moreMenuRow(String kind, String label, final Runnable act) {
        LinearLayout rowL = new LinearLayout(this);
        rowL.setOrientation(LinearLayout.HORIZONTAL);
        rowL.setGravity(Gravity.CENTER_VERTICAL);
        rowL.setPadding(dp(this, 10), dp(this, 8), dp(this, 10), dp(this, 8)); // Q126（件五）：行高内距收紧
        rowL.setBackground(rippleBg(Color.TRANSPARENT, 10)); // Q73: row sits on menu glass, no opaque white
        rowL.setClipToOutline(true);
        MenuIconView mi = new MenuIconView(this);
        mi.kind = kind; mi.iconColor = colText();
        rowL.addView(mi, new LinearLayout.LayoutParams(dp(this, 18), dp(this, 18))); // Q126（件五）
        TextView t = tv(this, label, 13.5f, colText(), false); // Q126（件五）
        LinearLayout.LayoutParams tlp = new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f);
        tlp.leftMargin = dp(this, 10);
        rowL.addView(t, tlp);
        rowL.setOnTouchListener((v, e) -> {
            if (e.getAction() == MotionEvent.ACTION_DOWN) pressBounce(v, true);
            else if (e.getAction() == MotionEvent.ACTION_UP || e.getAction() == MotionEvent.ACTION_CANCEL) pressBounce(v, false);
            return false;
        });
        rowL.setOnClickListener(v -> {
            haptic();
            closeMoreMenu();
            if (act != null) mainHandler.postDelayed(act, 150);
        });
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        rowL.setLayoutParams(lp);
        return rowL;
    }

    /** Q115：关 ⋯ 菜单后把设置页滚动条开关恢复到开菜单前（开菜单时暂关防透/防烤，见 openMoreMenu）。 */
    void restoreMenuPageBar() {
        if (settingsScroll != null && moreMenuBarWas) {
            try { settingsScroll.setVerticalScrollBarEnabled(true); } catch (Throwable ignored) {}
        }
    }

    void openMoreMenu(View anchor) {
        if (moreMenuOverlay != null) { closeMoreMenu(); return; }
        if (anchor == null || content == null) return;
        haptic();
        hideChrome(); // Q122（件十一）：菜单也算窗——底栏整件退场，关菜单 restoreChrome 恢复
        // Q115（2.28）：开菜单全程暂关设置页滚动条——vivo 系滚动条是白色宽胶囊（带小
        // 三角），用户滑完设置页立刻点 ⋯ 时它还醒着：一路活生生透过玻璃面、一路被下面
        // 两次 captureBackdrop 烤进冻结背板，面板里读成「内滚条」（23:57 图证）。关菜单
        // 三路（closeMoreMenu/dismissMoreMenuNow/行点击经 closeMoreMenu）统一恢复。
        if (settingsScroll != null) {
            moreMenuBarWas = settingsScroll.isVerticalScrollBarEnabled();
            settingsScroll.setVerticalScrollBarEnabled(false);
        }
        // Q102：趁菜单未上屏、画面静止先同步抓一帧背板存档，随后开窗全程冻结重抓——旧链在
        // 菜单缩放动画期间按 preDraw 反复整屏重抓＋隐藏/恢复全部玻璃宿主，背景随之抽搐闪烁。
        backdropLastCapMs = 0L;
        try { captureBackdrop(); } catch (Throwable ignored) {}
        moreMenuBackdropFrozen = true;
        final FrameLayout overlay = new FrameLayout(this);
        overlay.setBackgroundColor(Color.TRANSPARENT);
        overlay.setOnClickListener(v -> closeMoreMenu());
        // Q122（2.34，件一，用户 01:18 亲口定「重新写这个组件、不要调暗」）：撤 2.32
        // 补的 117 遮罩——页面保持原亮度一字不压。方白芯的真身是强糊背板本色透过
        // α233 薄面（见下 menuFace 处），遮罩只是拿全页变暗换面板对比，用户已否。
        // 面板改照全站没被投诉过的窗件口径：糊层＋一张提实定形面（boostWindowFace），
        // 行字直浮其上，全组件只此一层有面。
        // Q73: more-menu joins the same true-glass family (frozen blur + thin tint + wash),
        // was a solid white card. Rows keep their ripple over the glass.
        // Q104（2.17 真机回图）：菜单玻璃恰好止于 cardWrap 边界，右沿阴影带/圆角外的
        // 背景以全锐度生肉透出（红圈处）。修：玻璃宿主整体外扩 menuPad——玻璃/wash 盖满
        // 含阴影的占位，card 本体在外扩框内内缩 menuPad 保持原落位分毫不动；采样对位
        // 在 GlassBackdropView.onDraw 按宿主实测坐标算，外扩区采样画外场景天然成立。
        final int menuPad = dp(this, 16);
        final FrameLayout cardWrap = new FrameLayout(this);
        glassClip(cardWrap, floatR129(32f), false); // 外框圆角与内卡同心：16+外扩量；Q129：悬浮类收口
        cardWrap.setElevation(dp(this, 18));
        cardWrap.addView(glassLayerHw(cardWrap, floatR129(32f), false, "moremenu"), new FrameLayout.LayoutParams( // Q108 试点②⋯菜单（frozen）
            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        // Q106（2.20，用户 21:54 点名双层）：删「玻璃外框＋内嵌白板」——card 不再自带
        // glassWindowTint(16) 近实底内缩 16dp，改由窗级染色以半径 32 铺满整个 cardWrap
        // 作唯一面（糊层与染色同界，与情景窗 Q103 同口径），wash 层一并摘除，边缘只剩
        // 染色面自带的那一道白色发丝描边；card 退为透明内容架，行落位/内边距分毫不动。
        // Q118（2.31，用户 00:28 红圈）：旧 menuFace 是 glassWindowTint α≈233/223 的近不
        // 透明面——毛玻璃档下糊层本就近白，再压 91% 白即读成「圆角玻璃面板里垫了块方形
        // 白板」（2.20 删掉的是内嵌小白板，这块整面白留了下来）。改与筛选窗同口径：玻璃
        // ＋轻 wash（α58/44）作唯一面，行直接浮在磨砂上；仅玻璃关停态（糊层整面不画）
        // 才回落 glassWindowTint 实面保可读——那是静态染色语境，不成双层观感。
        // Q122（2.34，件一）：面提实定形——glassWindowTint(32) 再 boostWindowFace 顶到
        // 近实（浅 250/244、深 248/242，与加入选择窗 2.33 已验值同源）。强糊背板 ≈250
        // 亮透过旧 α233 面漏 9–13% 成内缩方亮芯；提实后漏光 ≤4%，亮芯与身后字一并
        // 不可读，且不靠遮罩压暗页面。两态同此一面：玻璃关停时糊层整面不画、此面即
        // 实面兜底，圆角同为 32、不出方圆套娃。wash 层不存在于本路径（grep 自证）。
        View menuFace = new View(this);
        GradientDrawable menuFaceBg = glassWindowTint(floatR129(32f), false); // Q129：悬浮类收口
        boostWindowFace(menuFaceBg);
        menuFace.setBackground(menuFaceBg);
        menuFace.setClickable(false);
        menuFace.setFocusable(false);
        cardWrap.addView(menuFace, new FrameLayout.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        final LinearLayout card = new LinearLayout(this);
        card.setOrientation(LinearLayout.VERTICAL);
        card.setPadding(dp(this, 5), dp(this, 5), dp(this, 5), dp(this, 5)); // Q126（件五）
        card.addView(moreMenuRow("scene", "情景选卡", () -> openWizard()));
        // Q103（2.17）去重：⋯ 菜单不再放「更新日志」——与关于页「版本与更新日志 → 查看
        // 更新日志」是重复入口，且旧实现把日志内嵌倾倒在设置页底部（用户点名「展开有
        // 什么用」）。日志只留关于页一个入口，走 showChangelog 整页从顶部呈现。
        card.addView(moreMenuRow("welcome", "欢迎页", () -> showHello())); // Q93：旧欢迎页已删，入口直达「你好」页
        card.addView(moreMenuRow("about", "关于卡盒", () -> openAbout()));
        int menuW = dp(this, 168); // Q126（件五，用户点名「有点肥了」）：208→168 收窄，落位/纵向钳制公式沿用 menuW 自适应
        // Q92：同糊层事故防线——cardWrap 先测 card 实高、钉死像素高，不让 WRAP_CONTENT
        // 把菜单背板撑出卡外一片。Q104：玻璃/wash 改盖外扩后的 cardWrap 全幅（含 menuPad 外扩带）。
        card.measure(View.MeasureSpec.makeMeasureSpec(menuW, View.MeasureSpec.EXACTLY),
            View.MeasureSpec.makeMeasureSpec(0, View.MeasureSpec.UNSPECIFIED));
        int menuH = card.getMeasuredHeight();
        FrameLayout.LayoutParams cardInWrap = new FrameLayout.LayoutParams(menuW, menuH);
        cardInWrap.leftMargin = menuPad; cardInWrap.topMargin = menuPad;
        cardWrap.addView(card, cardInWrap);
        card.setOnClickListener(v -> {});
        FrameLayout.LayoutParams clp = new FrameLayout.LayoutParams(menuW + menuPad * 2, menuH + menuPad * 2);
        int[] al = new int[2]; anchor.getLocationOnScreen(al);
        int[] cl = new int[2]; content.getLocationOnScreen(cl);
        int anchorRight = al[0] - cl[0] + anchor.getWidth();
        int anchorTop = al[1] - cl[1];
        // Q115（2.28，用户 23:57 图证面板右沿冲出屏幕）：2.18 的 Q104 修法只把玻璃宿主
        // 外扩 menuPad 盖住阴影带、锚点公式仍只保「内卡右沿 = anchorRight」——外扩后
        // 的整框右沿 = anchorRight + menuPad 再无人夹。设置页横向 padding 14dp 小于
        // menuPad 16dp，整框恒越屏 2dp、再叠 18dp elevation 阴影，看着就是面板冲出
        // 屏幕（修了又复发即此：当年夹的是内卡、不是整框）。根治：整框右沿先对
        // 「宿主宽 −10dp」封顶再回推左沿，内卡随框左移数 dp；缩放原点改按锚点右沿
        // 在框内坐标算，左移后仍贴 ⋯ 钮角长出。
        final int wrapW115 = menuW + menuPad * 2;
        int hostW115 = content.getWidth() > 0 ? content.getWidth() : (rootView != null ? rootView.getWidth() : 0);
        int wrapRight115 = anchorRight + menuPad;
        if (hostW115 > 0) wrapRight115 = Math.min(wrapRight115, hostW115 - dp(this, 10));
        final int wrapLeft115 = Math.max(dp(this, 2), wrapRight115 - wrapW115);
        clp.leftMargin = wrapLeft115;
        // Q125（审计二类 2，低危）：纵向下沿钳制——旧式只按锚点下沿算 top、无底封顶，
        // 锚点靠屏底时菜单尾会探出屏外；补「宿主高 − 整框高 − 10dp」上限。
        int wantTop125 = Math.max(dp(this, 2), Math.max(pageTopPad(), anchorTop + anchor.getHeight() + dp(this, 6)) - menuPad);
        int hostH125 = content.getHeight() > 0 ? content.getHeight() : (rootView != null ? rootView.getHeight() : 0);
        if (hostH125 > 0) wantTop125 = Math.min(wantTop125, Math.max(dp(this, 2), hostH125 - (menuH + menuPad * 2) - dp(this, 10)));
        clp.topMargin = wantTop125;
        overlay.addView(cardWrap, clp);
        content.addView(overlay, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        moreMenuOverlay = overlay;
        // Q122：遮罩已撤，菜单入场只剩 cardWrap 自 ⋯ 角缩放淡入（下方原行），页面不压暗。
        // Q104：落位落定后再同步重抓一帧冻结背板——开窗瞬间的预抓帧若与菜单最终几何
        // 有任何时序差（页面未停稳/字体落定），按最终落位重采样对齐；抓图时宿主整面
        // 让开（captureBackdrop 既有机制），画面上不会闪没。关窗后 overlay 已换则跳过。
        cardWrap.post(() -> {
            if (moreMenuOverlay != overlay) return;
            backdropLastCapMs = 0L;
            try { captureBackdrop(); } catch (Throwable ignored) {}
        });
        // 缩放原点贴按钮角（右上）：菜单像从 ⋯ 钮角上长出来；缩放与淡入同步、带轻回弹。
        // Q115：原点 x 改按锚点右沿在整框内坐标（整框夹后左移过，原 menuPad+menuW 已不对位）。
        cardWrap.setPivotX(Math.max(0, Math.min(wrapW115, anchorRight - wrapLeft115)));
        cardWrap.setPivotY(menuPad);
        cardWrap.setScaleX(0.72f); cardWrap.setScaleY(0.72f); cardWrap.setAlpha(0f);
        cardWrap.animate().scaleX(1f).scaleY(1f).alpha(1f)
            .setDuration(ANIM_DUR_MENU_IN).setInterpolator(ANIM_MENU_SPRING).start();
    }

    void closeMoreMenu() {
        restoreMenuPageBar(); // Q115：滚动条恢复（菜单未开时空转无碍）
        final View ov = moreMenuOverlay;
        if (ov == null) return;
        moreMenuBackdropFrozen = false; // Q102：关菜单即解冻背板重抓（淡出 190ms 内背板静止无碍）
        moreMenuOverlay = null;
        if (ov instanceof FrameLayout && ((FrameLayout) ov).getChildCount() > 0) {
            // Q122：overlay 唯一子即菜单框（遮罩已撤）——框走缩放淡出，落定摘窗＋
            // restoreChrome 恢复底栏（件十一）；行点击链式开下一窗时 isChromeCovered 自守。
            View card = null;
            for (int i = 0; i < ((FrameLayout) ov).getChildCount(); i++) {
                View ch = ((FrameLayout) ov).getChildAt(i);
                if (ch instanceof FrameLayout) card = ch; else animShadeOut(ch);
            }
            if (card == null) {
                if (ov.getParent() != null) ((ViewGroup) ov.getParent()).removeView(ov);
                restoreChrome();
                return;
            }
            card.animate().cancel();
            card.animate().scaleX(0.78f).scaleY(0.78f).alpha(0f)
                .setDuration(ANIM_DUR_MENU_OUT).setInterpolator(ANIM_EXIT)
                .withEndAction(() -> { if (ov.getParent() != null) ((ViewGroup) ov.getParent()).removeView(ov); restoreChrome(); })
                .start();
            // Q98 兜底：endAction 不达则全屏菜单罩以 alpha 动画中途态滞留屏上吃触摸；超时强制摘除
            mainHandler.postDelayed(() -> { if (ov.getParent() != null) ((ViewGroup) ov.getParent()).removeView(ov); restoreChrome(); }, ANIM_DUR_MENU_OUT + 130);
        } else if (ov.getParent() != null) {
            ((ViewGroup) ov.getParent()).removeView(ov);
            restoreChrome();
        }
    }

    void dismissMoreMenuNow() {
        restoreMenuPageBar(); // Q115：切页等即刻退场路径同恢复设置页滚动条
        moreMenuBackdropFrozen = false; // Q102：菜单退场即解冻背板重抓
        View ov = moreMenuOverlay;
        moreMenuOverlay = null;
        if (ov != null) {
            ov.animate().cancel();
            if (ov.getParent() != null) ((ViewGroup) ov.getParent()).removeView(ov);
        }
    }

    View buildSettingsPage() {
        LinearLayout page = basePage(S("settings_title"));
        // Q58：标题行右上角 ⋯ 菜单钮（细线三点自绘，禁用 emoji；菜单从此钮角长出）
        try {
            if (page.getChildCount() > 0 && page.getChildAt(0) instanceof TextView) {
                TextView titleTv = (TextView) page.getChildAt(0);
                page.removeViewAt(0);
                LinearLayout titleRow = new LinearLayout(this);
                titleRow.setOrientation(LinearLayout.HORIZONTAL);
                titleRow.setGravity(Gravity.CENTER_VERTICAL);
                titleRow.addView(titleTv, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f));
                FrameLayout moreBtn = new FrameLayout(this);
                moreBtn.setBackground(rippleBg(Color.rgb(0xF2, 0xF3, 0xF7), 999));
                moreBtn.setClipToOutline(true);
                MoreDotsView dots = new MoreDotsView(this);
                moreBtn.addView(dots, new FrameLayout.LayoutParams(dp(this, 22), dp(this, 22), Gravity.CENTER));
                LinearLayout.LayoutParams mbLp = new LinearLayout.LayoutParams(dp(this, 40), dp(this, 40));
                titleRow.addView(moreBtn, mbLp);
                moreBtn.setOnTouchListener((v, e) -> {
                    if (e.getAction() == MotionEvent.ACTION_DOWN) pressBounce(v, true);
                    else if (e.getAction() == MotionEvent.ACTION_UP || e.getAction() == MotionEvent.ACTION_CANCEL) pressBounce(v, false);
                    return false;
                });
                moreBtn.setOnClickListener(v -> openMoreMenu(v));
                page.addView(titleRow, 0);
            }
        } catch (Throwable ignored) {}
        // Q92：情景选卡入口已收进 ⋯ 菜单（菜单行「情景选卡」），设置页不再重复长行。

        // Q104（2.18）：功能启用六开关折成一组（默认收起、状态持久化），见 buildFeaturePanel。
        // 06:33 钉版口径不变：可选模块逐项登记于此（FEATURE_KEYS），关掉入口与界面彻底不出现、不占位。
        buildFeaturePanel(page);

        // Q104（2.18）：外观 + 显示融合为一整块大面板（内部分区小标题 + 发丝线），见 buildAppearancePanel
        buildAppearancePanel(page);
        sectionHead(page, S("sec_experience"));
        switchRow(page, "高刷新率", "把刷新率拉到屏幕最高档（耗电略增）", prefs.getBoolean("high_refresh", false), on -> {
            prefs.edit().putBoolean("high_refresh", on).apply(); haptic(); applyHighRefresh(); rebuildPages();
        });
        // Q97：玻璃控制二合一——开关（关走静态半透染色、本机保存）＋状态说明同行；
        // 旧《关于」区被动状态行（仅关停时出现、不可操作）就此退役，由本行接管。
        // Q118（2.31，用户三度澄清定版）：从属两块（硬件玻璃行＋透明程度）收进 glassSubBox
        // 折叠容器——关主开关＝整块高度收起藏匿不占位，开＝重搭后量高展开（与 2.30 我的
        // 卡片就地收展同口径），不再置灰摆着；主行副文案由 glassMainDescText() 一处口径、
        // 构建与拨动共用；拨动改走 invalidatePagesSoft 不整页重建（同 Q102 防闪），别页
        // 下次切到时按新关态重建，本页只原地收展＋副文案原地刷新，任意轮次联动一致。
        View glassMainRow = switchRow(page, "玻璃效果", glassMainDescText(),
            !glassDisabled, on -> {
                glassDisabled = !on;
                if (on) glassAutoOff = false;
                try { prefs.edit().putBoolean("glass_disabled", glassDisabled).putBoolean("glass_auto_off", glassAutoOff).putBoolean("glass_user_set", true).apply(); } catch (Throwable ignored) {} // Q125：立「用户拨过」标记，默认关口径据此分流
                haptic();
                applyGlassEnabledChange();
                animateGlassSub(!glassDisabled);
                if (glassMainDesc != null) { try { glassMainDesc.setText(glassMainDescText()); } catch (Throwable ignored) {} }
                invalidatePagesSoft();
            });
        try {
            glassMainDesc = (TextView) ((ViewGroup) ((ViewGroup) glassMainRow).getChildAt(0)).getChildAt(1);
        } catch (Throwable ignored) { glassMainDesc = null; }
        glassSubBox = new LinearLayout(this);
        glassSubBox.setOrientation(LinearLayout.VERTICAL);
        page.addView(glassSubBox, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        rebuildGlassSub();
        if (glassDisabled) glassSubBox.setVisibility(View.GONE);
        segRow(page, S("haptic"), new String[][]{{"0",S("haptic_off")},{"1",S("haptic_light")},{"2",S("haptic_mid")},{"3",S("haptic_strong")}}, String.valueOf(hapticLevel), v -> {
            hapticLevel = Integer.parseInt(v); prefs.edit().putInt("haptic_level", hapticLevel).apply(); haptic(); rebuildPages();
        });

        sectionHead(page, S("sec_data"));
        int pendVer = prefs == null ? -1 : prefs.getInt("pending_update_version", -1); if (pendVer <= Store.dataVersion) pendVer = -1; else if (pendingUpdateVer > Store.dataVersion) pendVer = pendingUpdateVer;
        String updSub = pendVer > 0
            ? (isEn() ? "v" + Store.dataVersion + " · " + Store.all.size() + " cards · New v" + pendVer + " available ›" : "v" + Store.dataVersion + " · " + Store.all.size() + " 张卡 · 有新版 v" + pendVer + " 可更新 ›")
            : (isEn() ? "v" + Store.dataVersion + " · " + Store.all.size() + " cards · Tap to check for updates ›" : "v" + Store.dataVersion + " · " + Store.all.size() + " 张卡 · 点此直接检查更新 ›");
        View updRow = settingRow("数据更新", updSub);
        if (pendVer > 0) { try { TextView ut = (TextView)((ViewGroup)updRow).getChildAt(0); String base = isEn() ? "Data Update  ●" : "数据更新  ●"; int dot = base.indexOf('●'); android.text.SpannableStringBuilder ssb = new android.text.SpannableStringBuilder(base); ssb.setSpan(new android.text.style.ForegroundColorSpan(Color.rgb(0xE0,0x31,0x31)), dot, dot + 1, android.text.Spannable.SPAN_EXCLUSIVE_EXCLUSIVE); ssb.setSpan(new android.text.style.RelativeSizeSpan(0.7f), dot, dot + 1, android.text.Spannable.SPAN_EXCLUSIVE_EXCLUSIVE); ut.setText(ssb); } catch(Throwable ignored){} }
        final int pendFinal = pendVer;
        updRow.setOnClickListener(v -> { haptic(); if (pendFinal > 0 && pendingUpdateJson != null) showUpdateConfirm(); else { showFloatToast("正在检查数据更新…"); checkDataUpdate(true); } });
        page.addView(updRow);
        switchRow(page, "启动时自动检测更新", "开启只检测并提示，不自动应用；关闭则仅手动检查", prefs != null && prefs.getBoolean("auto_check_update", false), on -> { if(prefs!=null) prefs.edit().putBoolean("auto_check_update", on).apply(); haptic(); rebuildPages(); }); // Q121：默认关（站规矩）
        // Q124（2.36，件六）：清除缓存行——占用口径与 Q124 盘点一致：cacheDir 全部
        // ＋ filesDir/ota-images（远程卡图下载缓存，按版本分目录、可按需重下）。
        // 只清这两处可再生内容；卡库 OTA 数据文件、用户卡片/收藏/设置 prefs、
        // 导入字体、崩溃记录一律不碰。清除在后台线程做，完事回主线程刷新副文案回执。
        final View cacheRow = settingRow(isEn() ? "Clear Cache" : "清除缓存", "");
        final TextView cacheSub = (TextView) ((ViewGroup) cacheRow).getChildAt(1);
        final Runnable cacheSubRefresh = () -> {
            long bytes = dirSizeBytes(getCacheDir()) + dirSizeBytes(new File(getFilesDir(), "ota-images"));
            cacheSub.setText(isEn() ? "Downloaded image cache · " + fmtBytesKb(bytes) + " · Tap to clear"
                : "已下载卡图缓存 · " + fmtBytesKb(bytes) + " · 点此清除");
        };
        cacheSubRefresh.run();
        cacheRow.setOnClickListener(v -> {
            haptic();
            cacheSub.setText(isEn() ? "Clearing…" : "正在清除…");
            new Thread(() -> {
                deleteDirRecursive(getCacheDir());
                deleteDirRecursive(new File(getFilesDir(), "ota-images"));
                runOnUiThread(() -> {
                    long left = dirSizeBytes(getCacheDir()) + dirSizeBytes(new File(getFilesDir(), "ota-images"));
                    cacheSubRefresh.run();
                    showFloatToast(isEn() ? "Cache deep-cleared (downloaded card images will re-download) · " + fmtBytesKb(left) + " left"
                        : "已深度清除缓存（已下载卡图之后会重新下载）· 还剩 " + fmtBytesKb(left)); // Q125：深度清理回执明示重下（下拉清缓存则保留卡图，两条线分开）
                });
            }).start();
        });
        page.addView(cacheRow);

        sectionHead(page, S("sec_about"));
        // Q18: last-crash trace at top of About (copyable / clearable); empty when no crash recorded
        if (crashLogText != null && !crashLogText.trim().isEmpty()) {
            LinearLayout crashBox = new LinearLayout(this);
            crashBox.setOrientation(LinearLayout.VERTICAL);
            crashBox.setBackground(roundRect(Color.rgb(0xFF, 0xF1, 0xF0), 12, this));
            crashBox.setPadding(dp(this, 14), dp(this, 10), dp(this, 14), dp(this, 12));
            LinearLayout.LayoutParams cbp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            cbp.topMargin = dp(this, 8);
            crashBox.setLayoutParams(cbp);
            crashBox.addView(tv(this, "最近一次崩溃记录", 14, Color.rgb(0xB0, 0x2A, 0x20), true));
            TextView crashTv = tv(this, crashLogText, 11, Color.rgb(0x5A, 0x2A, 0x24), false);
            crashTv.setTextIsSelectable(true);
            LinearLayout.LayoutParams clp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            clp.topMargin = dp(this, 6);
            crashTv.setLayoutParams(clp);
            crashBox.addView(crashTv);
            LinearLayout crashBtns = new LinearLayout(this);
            crashBtns.setOrientation(LinearLayout.HORIZONTAL);
            LinearLayout.LayoutParams bpl = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            bpl.topMargin = dp(this, 10);
            crashBtns.setLayoutParams(bpl);
            TextView copyBtn = softMiniBtn("复制记录", true);
            copyBtn.setOnClickListener(v -> {
                haptic();
                try {
                    android.content.ClipboardManager cm = (android.content.ClipboardManager) getSystemService(CLIPBOARD_SERVICE);
                    if (cm != null) cm.setPrimaryClip(android.content.ClipData.newPlainText("crash", crashLogText));
                    showFloatToast("崩溃记录已复制");
                } catch (Throwable ignored) { showFloatToast("复制失败"); }
            });
            crashBtns.addView(copyBtn, new LinearLayout.LayoutParams(0, dp(this, 38), 1f));
            TextView clearBtn = softMiniBtn("清除记录", false);
            clearBtn.setOnClickListener(v -> { haptic(); clearCrashLog(); rebuildPages(); showFloatToast("崩溃记录已清除"); });
            LinearLayout.LayoutParams clrLp = new LinearLayout.LayoutParams(0, dp(this, 38), 1f);
            clrLp.leftMargin = dp(this, 10);
            crashBtns.addView(clearBtn, clrLp);
            crashBox.addView(crashBtns);
            page.addView(crashBox);
        }
        page.addView(settingRow(S("version"), appVersion() + (isEn() ? " (Native)" : "（原生版）")));
        // Q92 设置页瘦身：欢迎页/关于卡盒/情景选卡次级入口已收进标题栏 ⋯ 菜单（细线图标
        // 行），此处不再重复长行。Q103（2.17）：更新日志内嵌展开框退役——日志只留关于页
        // 「查看更新日志」一个入口（showChangelog 整页从顶部呈现），设置页不再倾倒日志。
        page.addView(settingRow("迁移进度", "全部卡片 / 详情 / 我的卡片 / 学生推荐 / 筛选 / 资讯 / 情景选卡 / 自定义卡 / 拖动 / 字体与界面大小 / 高刷 / 触感 / 欢迎页 / 更新日志 / 数据 OTA 已迁移"));
        ScrollView sv = new ScrollView(this);
        thinScrollbar(sv);
        sv.setClipToPadding(false);
        settingsScroll = sv;
        if (Build.VERSION.SDK_INT >= 23) sv.setOnScrollChangeListener((v, sx, sy, ox, oy) -> { pageScrollSaveY.put("settings", sy); updateTopFabVisibility(sy); });
        // P2d-fix：此前这里把 basePage 的顶部留白覆盖成 12dp，标题被压进状态栏；改用 pageTopPad()/dockPad()
        page.setPadding(dp(this, 14), pageTopPad(), dp(this, 14), dockPad());
        sv.addView(page);
        restorePageScroll("settings", sv);
        return sv;
    }

